insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('kayak-01', 'kayak_rush', 1, 'Giải Đua Sông Ngọc', 'File mục I.1 (đua lách gỗ xoay, quái cây, tăng tốc khi trả lời đúng) + gói thế giới sông chung.', 'Giải Đua Kayak Sông Ngọc mùa hè khai mạc, cô bình luận viên Vân Anh giới thiệu từng đội trên loa. Đường đua dài sáu chặng: bến xuất phát, khúc gỗ xoay, rừng lau, ghềnh đá, cầu treo và đích đến dưới cổng hoa. Mỗi cổng phao mang một câu hỏi, đội trả lời đúng sẽ bật Nitro lướt như bay. Giữa chặng, khúc gỗ khổng lồ trôi xoay chặn ngang sông, chỉ đội đọc đúng biển báo mới tìm ra lạch tắt. Về đích, đội vô địch nhận Mái Chèo Vàng và được chèo vòng danh dự quanh hồ.', 6, 5, 30, 12, true, 'Sông xanh ngọc uốn qua rừng thông và bãi sỏi, nắng sáng, cờ đua hai bên bờ, khán giả đứng trên cầu gỗ. Nước trong thấy đá cuội. Phao cứu sinh trắng xanh treo dọc bến, đàn bồ câu đậu trên lan can cầu. Tay chèo Nắng đứng chỉ đường ở bến, khoác áo phao cam.', '[{"n": 1, "title": "Bến xuất phát", "minutes": 5, "optional": false, "goal": "Khởi động, nhận kayak và mái chèo; xuất phát.", "beats": ["Đèn xuất phát đỏ - vàng - xanh.", "Câu đúng trước đèn xanh = xuất phát sớm 1 giây.", "Trọng tài chỉ vào phao cứu sinh ở bến: ai đọc đúng tên đồ an toàn thì được xuất phát trước.", "Tay chèo Nắng vẫy cờ xuất phát: đọc đúng khẩu lệnh thì được xuống nước trước."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Nitro đầu tiên.", "vocab": ["ready", "start", "paddle", "go", "lifebuoy", "pigeon", "paddler"], "assets": ["kayak_boat", "kayak_paddle", "kayak_lifejacket", "river_dock", "camp_bunting", "river_buoy", "river_birds", "char_sunny_boy"]}, {"n": 2, "title": "Khúc gỗ xoay", "minutes": 5, "optional": false, "goal": "Lách qua khúc gỗ xoay giữa dòng.", "beats": ["Gỗ xoay theo nhịp; Nitro đúng lúc thì lướt qua."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Qua chặng không mất tốc.", "vocab": ["log", "spin", "dodge", "left", "right"], "assets": ["kayak_log_spinning", "river_driftwood", "river_log_fallen"]}, {"n": 3, "title": "Rừng lau", "minutes": 5, "optional": false, "goal": "Đi qua rừng lau rậm, tìm lạch tắt theo biển báo.", "beats": ["Biển báo tiếng Anh chỉ lạch tắt.", "Đi sai lạch: vòng xa thêm 5 giây."], "question_hook": "Câu hỏi trên biển báo lạch; câu hướng đi.", "reward": "Lạch tắt.", "vocab": ["shortcut", "sign", "reed", "narrow"], "assets": ["river_reed", "river_sign", "river_lilypad"]}, {"n": 4, "title": "Ghềnh đá", "minutes": 5, "optional": false, "goal": "Vượt ghềnh nước trắng, tránh đá ngầm.", "beats": ["Đá ngầm hiện vệt bọt trắng.", "Sai 2 câu liền: kayak xoay một vòng."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật. Câu ngắn 8 giây vì nước chảy nhanh.", "reward": "Siêu Nitro nếu đúng 3 câu liền.", "vocab": ["rapids", "rock", "splash", "careful"], "assets": ["river_rock_large", "river_rock_medium", "water_foam"]}, {"n": 5, "title": "Cầu treo", "minutes": 5, "optional": false, "goal": "Lướt dưới cầu treo, khán giả cổ vũ.", "beats": ["Khán giả ném hoa xuống nước khi đội trả lời đúng."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Nitro cổ vũ.", "vocab": ["bridge", "cheer", "crowd", "faster"], "assets": ["river_bridge", "river_birds", "camp_bunting"]}, {"n": 6, "title": "Cổng hoa về đích", "minutes": 5, "optional": false, "goal": "Nước rút cuối, về đích dưới cổng hoa.", "beats": ["100 m cuối: mọi câu đúng là Nitro gấp đôi.", "Trao Mái Chèo Vàng, MVP là người nhiều Nitro nhất.", "Hai phao cứu sinh làm cổng phụ ở vạch đích; qua đúng giữa hai phao là cộng Nitro."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Mái Chèo Vàng.", "vocab": ["finish", "win", "champion", "medal", "finish line"], "assets": ["kayak_finish_arch", "river_dock", "anim_cheer", "river_buoy"]}, {"n": 7, "title": "Chặng phụ: Vòng danh dự", "minutes": 5, "optional": true, "goal": "Kéo dài: chèo vòng danh dự quanh hồ.", "beats": ["Câu ôn nhanh."], "question_hook": "Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["lap", "honor"], "assets": ["kayak_boat"]}, {"n": 8, "title": "Chặng phụ: Phỏng vấn sau đua", "minutes": 5, "optional": true, "goal": "Trả lời phỏng vấn tiếng Anh của cô Vân Anh.", "beats": ["Câu trả lời hay phát trên loa."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu nói/viết, không tính thua.", "reward": "Huy hiệu \"Tay Chèo Sông Ngọc\".", "vocab": ["feel", "happy", "thanks"], "assets": ["river_sign"]}]'::jsonb, '{"sizes": {"1-5": "Mỗi em một kayak đua cùng 2-3 kayak máy (độ khó theo bậc của lớp).", "6-20": "Đội 2-4 kayak cùng màu. Mỗi màn hình hiện kayak của mình + 4 đối thủ gần nhất; bảng xếp hạng cả lớp ở góc.", "21-50": "10 đội × 5 kayak, đua theo 2 lượt xuất phát (25 kayak/lượt) trên cùng đường sông; điểm đội = tổng thứ hạng. Mỗi máy chỉ vẽ 8 kayak gần nhất để nhẹ."}, "roles": ["Đội trưởng (chọn đường tắt)", "Tay chèo Nitro", "Hoa tiêu (đọc biển báo)", "Người cứu hộ (giúp kayak lật)"], "scoring": "Thứ hạng + số Nitro + đường tắt mở được. Đúng 3 câu liền = Siêu Nitro.", "avatars": "Mỗi học sinh ngồi kayak bằng nhân vật riêng ghép từ hồ sơ diện mạo, áo phao màu đội, mũ ngộ nghĩnh tự chọn.", "style": "Nâng cấp theo gói thế giới sông bán thực (như 3 game mới); chướng ngại: khúc gỗ xoay, đá ngầm, xoáy nước, ghềnh, cây trôi."}'::jsonb, array['anim_cheer','camp_bunting','char_sunny_boy','kayak_boat','kayak_finish_arch','kayak_lifejacket','kayak_log_spinning','kayak_paddle','river_birds','river_bridge','river_buoy','river_dock','river_driftwood','river_lilypad','river_log_fallen','river_reed','river_rock_large','river_rock_medium','river_sign','water_foam']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
