insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('kayak-01#12', 'kayak-01', 12, 'Cá Heo Sông Nhí', 'Nhảy lên khỏi nước khi có Siêu Nitro', 'child', 'n', 'S2', false, 'E_brown', 'black', 'messy', 'short', false, false, 'casual', 'gray', 'Da xám hồng', null, null, array['pet_or_toy']::text[], 'Linh vật đường đua', 'npc');
insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('kayak-02', 'kayak_rush', 2, 'Vượt Ghềnh Thác Đá', 'Đua lách chướng ngại; gói sông chung với ghềnh đá và thác.', 'Huấn luyện viên Mạnh chọn đội kayak giỏi nhất trại cho chặng đua "Ghềnh Thác Đá", đường đua khó nhất vùng. Ba bậc thác nhỏ, những khúc ghềnh xoáy và hang đá thấp đòi hỏi tay chèo phải phản xạ thật nhanh. Mỗi khúc ghềnh có cổng an toàn đánh dấu bằng phao, trả lời đúng mới mở được cổng. Giữa đường, một cây thông đổ chắn ngang sông, các đội phải hợp sức đẩy cây sang bên. Đội về đích đầy đủ và an toàn nhất sẽ nhận Huy hiệu Thác Đá.', 6, 5, 30, 12, true, 'Sông núi dốc, nhiều ghềnh trắng xóa, vách đá rêu xanh, thác nhỏ ba bậc. Trời nắng, bụi nước tạo cầu vồng. Thác cao đổ xuống hồ xanh, bụi nước phủ cầu vồng; phao cứu sinh cam buộc vào cọc ở mỗi bến.', '[{"n": 1, "title": "Kiểm tra an toàn", "minutes": 5, "optional": false, "goal": "Kiểm tra mũ, áo phao, mái chèo trước khi xuống ghềnh.", "beats": ["Mỗi món an toàn là một câu hỏi.", "Khám phao cứu sinh và áo phao: mỗi món đúng tên là một dấu kiểm."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Bộ đồ an toàn đầy đủ.", "vocab": ["helmet", "safety", "check", "ready", "life jacket", "lifebuoy"], "assets": ["kayak_lifejacket", "kayak_paddle", "kayak_boat", "river_buoy"]}, {"n": 2, "title": "Ghềnh thứ nhất", "minutes": 5, "optional": false, "goal": "Xuống ghềnh nhẹ đầu tiên.", "beats": ["Sóng đẩy kayak lên xuống."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Nitro.", "vocab": ["wave", "down", "hold on"], "assets": ["water_foam", "river_rock_medium"]}, {"n": 3, "title": "Thác ba bậc", "minutes": 5, "optional": false, "goal": "Trượt qua ba bậc thác nhỏ.", "beats": ["Mỗi bậc thác một câu 8 giây.", "Dòng nước đổ từ thác tạo ba bậc; cổng phao đặt ngay trước vực nước."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Siêu Nitro nếu đúng cả 3 bậc.", "vocab": ["waterfall", "drop", "step", "brave", "pool"], "assets": ["river_cliff", "water_foam", "river_waterfall", "river_waterfall_pool"]}, {"n": 4, "title": "Cây thông đổ", "minutes": 5, "optional": false, "goal": "Cả lớp hợp sức đẩy cây thông chắn sông.", "beats": ["Thanh sức đẩy chung: mọi câu đúng của lớp đều cộng."], "question_hook": "Câu hỏi trên thân cây; câu đúng đẩy cây đi một chút.", "reward": "Mở đường cho cả lớp.", "vocab": ["push", "together", "tree", "block"], "assets": ["river_log_fallen", "river_tree_pine"]}, {"n": 5, "title": "Hang đá thấp", "minutes": 5, "optional": false, "goal": "Cúi thấp lướt qua hang đá.", "beats": ["Đèn hang chỉ sáng khi trả lời đúng."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Đường tắt hang.", "vocab": ["cave", "low", "duck", "dark"], "assets": ["river_cave", "camp_lantern"]}, {"n": 6, "title": "Về đích Thác Đá", "minutes": 5, "optional": false, "goal": "Khúc ghềnh cuối và vạch đích.", "beats": ["Huy hiệu cho đội an toàn nhất, MVP nhiều Nitro nhất."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Huy hiệu Thác Đá.", "vocab": ["finish", "safe", "proud"], "assets": ["kayak_finish_arch", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Xoáy nước", "minutes": 5, "optional": true, "goal": "Kéo dài: thoát xoáy nước.", "beats": ["Câu nhanh."], "question_hook": "Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["whirlpool", "escape"], "assets": ["water_foam"]}, {"n": 8, "title": "Chặng phụ: Luật an toàn", "minutes": 5, "optional": true, "goal": "Viết 3 luật an toàn khi chèo kayak.", "beats": ["Luật dán ở bến."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.", "reward": "Huy hiệu \"Tay Chèo An Toàn\".", "vocab": ["always", "never", "wear"], "assets": ["river_sign"]}]'::jsonb, '{"sizes": {"1-5": "Mỗi em một kayak đua cùng 2-3 kayak máy (độ khó theo bậc của lớp).", "6-20": "Đội 2-4 kayak cùng màu. Mỗi màn hình hiện kayak của mình + 4 đối thủ gần nhất; bảng xếp hạng cả lớp ở góc.", "21-50": "10 đội × 5 kayak, đua theo 2 lượt xuất phát (25 kayak/lượt) trên cùng đường sông; điểm đội = tổng thứ hạng. Mỗi máy chỉ vẽ 8 kayak gần nhất để nhẹ."}, "roles": ["Đội trưởng (chọn đường tắt)", "Tay chèo Nitro", "Hoa tiêu (đọc biển báo)", "Người cứu hộ (giúp kayak lật)"], "scoring": "Thứ hạng + số Nitro + đường tắt mở được. Đúng 3 câu liền = Siêu Nitro.", "avatars": "Mỗi học sinh ngồi kayak bằng nhân vật riêng ghép từ hồ sơ diện mạo, áo phao màu đội, mũ ngộ nghĩnh tự chọn.", "style": "Nâng cấp theo gói thế giới sông bán thực (như 3 game mới); chướng ngại: khúc gỗ xoay, đá ngầm, xoáy nước, ghềnh, cây trôi."}'::jsonb, array['anim_cheer','camp_lantern','kayak_boat','kayak_finish_arch','kayak_lifejacket','kayak_paddle','river_buoy','river_cave','river_cliff','river_log_fallen','river_rock_medium','river_sign','river_tree_pine','river_waterfall','river_waterfall_pool','water_foam']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
