insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('kayak-03', 'kayak_rush', 3, 'Đua Hoàng Hôn Qua Hẻm Núi', 'Gói sông chung, HDRI hoàng hôn; đua đội qua hẻm núi.', 'Cuộc đua đặc biệt chỉ diễn ra mỗi năm một lần: chèo qua Hẻm Núi Đỏ trước khi mặt trời lặn hẳn. Cô Ánh Dương đặt sáu đèn hiệu dọc hẻm núi, đội nào thắp đủ đèn khi qua sẽ được tính thời gian ưu tiên. Hẻm núi có tiếng vọng, và những câu hỏi được hỏi bằng tiếng vọng từ vách đá. Gần cuối, một đàn dơi bay ra làm tối cả lòng hẻm, các đội phải nhờ đèn hiệu để đi tiếp. Đội về đích đúng lúc mặt trời chạm núi sẽ được chụp ảnh với hoàng hôn rực rỡ.', 6, 5, 30, 12, true, 'Hẻm núi đá đỏ, sông hẹp uốn khúc, mặt trời lặn nhuộm cam vách đá. Chim bay về tổ, gió mát, bóng đổ dài. Dãy núi xa phủ sương cam phía cuối hẻm.', '[{"n": 1, "title": "Cửa hẻm núi", "minutes": 5, "optional": false, "goal": "Xuất phát ở cửa hẻm, nhận đèn hiệu.", "beats": ["Đèn hiệu đầu tiên thắp bằng câu đúng.", "Thung lũng núi xa hiện ra làm mốc: đội nào gọi đúng tên mốc thì biết mình đi đúng hướng."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Đèn hiệu 1.", "vocab": ["canyon", "sunset", "light", "valley", "mountain"], "assets": ["kayak_boat", "river_cliff", "hdri_sunset", "backdrop_mountain_valley"]}, {"n": 2, "title": "Tiếng vọng", "minutes": 5, "optional": false, "goal": "Nghe câu hỏi vọng lại từ vách đá.", "beats": ["Câu nghe ngắn."], "question_hook": "Câu nghe hiểu; trả lời trước khi tiếng vọng tắt.", "reward": "Nitro.", "vocab": ["echo", "listen", "repeat"], "assets": ["river_cliff"]}, {"n": 3, "title": "Khúc cua gắt", "minutes": 5, "optional": false, "goal": "Ôm cua gắt giữa hẻm.", "beats": ["Câu hướng trái phải."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Nitro cua.", "vocab": ["turn", "sharp", "left", "right"], "assets": ["river_rock_large"]}, {"n": 4, "title": "Đèn hiệu giữa hẻm", "minutes": 5, "optional": false, "goal": "Thắp 3 đèn hiệu giữa hẻm.", "beats": ["Mỗi đèn một câu."], "question_hook": "Câu hỏi trên đèn hiệu.", "reward": "Thời gian ưu tiên.", "vocab": ["beacon", "fire", "three"], "assets": ["camp_lantern", "fx_fire"]}, {"n": 5, "title": "Đàn dơi", "minutes": 5, "optional": false, "goal": "Đàn dơi làm tối lòng hẻm; đi theo ánh đèn hiệu.", "beats": ["Đèn đã thắp soi đường."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Qua bóng tối.", "vocab": ["bat", "dark", "follow"], "assets": ["camp_lantern", "river_birds"]}, {"n": 6, "title": "Mặt trời chạm núi", "minutes": 5, "optional": false, "goal": "Nước rút cuối về đích.", "beats": ["Ảnh hoàng hôn cho đội về đích."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Danh hiệu \"Tay Chèo Hoàng Hôn\".", "vocab": ["finish", "golden", "photo"], "assets": ["kayak_finish_arch", "hdri_sunset", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Sao đầu tiên", "minutes": 5, "optional": true, "goal": "Kéo dài: đua dưới ngôi sao đầu tiên.", "beats": ["Câu nhanh."], "question_hook": "Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["first star", "evening"], "assets": ["hdri_night"]}, {"n": 8, "title": "Chặng phụ: Tả hoàng hôn", "minutes": 5, "optional": true, "goal": "Viết 2 câu tả hoàng hôn.", "beats": ["Câu hay in lên ảnh."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.", "reward": "Huy hiệu \"Hẻm Núi Đỏ\".", "vocab": ["orange", "beautiful", "sky"], "assets": ["hdri_sunset"]}]'::jsonb, '{"sizes": {"1-5": "Mỗi em một kayak đua cùng 2-3 kayak máy (độ khó theo bậc của lớp).", "6-20": "Đội 2-4 kayak cùng màu. Mỗi màn hình hiện kayak của mình + 4 đối thủ gần nhất; bảng xếp hạng cả lớp ở góc.", "21-50": "10 đội × 5 kayak, đua theo 2 lượt xuất phát (25 kayak/lượt) trên cùng đường sông; điểm đội = tổng thứ hạng. Mỗi máy chỉ vẽ 8 kayak gần nhất để nhẹ."}, "roles": ["Đội trưởng (chọn đường tắt)", "Tay chèo Nitro", "Hoa tiêu (đọc biển báo)", "Người cứu hộ (giúp kayak lật)"], "scoring": "Thứ hạng + số Nitro + đường tắt mở được. Đúng 3 câu liền = Siêu Nitro.", "avatars": "Mỗi học sinh ngồi kayak bằng nhân vật riêng ghép từ hồ sơ diện mạo, áo phao màu đội, mũ ngộ nghĩnh tự chọn.", "style": "Nâng cấp theo gói thế giới sông bán thực (như 3 game mới); chướng ngại: khúc gỗ xoay, đá ngầm, xoáy nước, ghềnh, cây trôi."}'::jsonb, array['anim_cheer','backdrop_mountain_valley','camp_lantern','fx_fire','hdri_night','hdri_sunset','kayak_boat','kayak_finish_arch','river_birds','river_cliff','river_rock_large']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
