insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('kayak-04', 'kayak_rush', 4, 'Tiếp Sức Đội Kayak', 'Đua đội (teams.ts); gói sông chung với nhiều trạm bến.', 'Ngày hội làng chài có cuộc đua tiếp sức kayak: mỗi đội chia người chèo các chặng, trao mái chèo tại bến tiếp sức. Bác trưởng làng Sáu Hòa nói đội mạnh không phải đội có một người giỏi, mà là đội ai cũng góp sức. Mỗi lần trao mái chèo là một câu hỏi chung của đội, trả lời đúng thì người sau xuất phát với Nitro. Giữa cuộc đua, chợ nổi chắn ngang sông, các đội phải lách qua những chiếc ghe bán trái cây. Đội về đích được làng tặng giỏ trái cây và vòng hoa.', 6, 5, 30, 12, true, 'Sông rộng chảy qua làng chài, bốn trạm bến tiếp sức dọc bờ, mỗi trạm treo cờ màu đội. Buổi sáng mát, nhiều người dân ra xem. Thuyền chèo của dân chài neo dọc bến, bồ câu bay trên mái đình làng, giỏ đan bày ở chợ nổi. Dân làng dắt ngựa ra bến, bạn trẻ trượt ván dọc chợ nổi.', '[{"n": 1, "title": "Chia chặng", "minutes": 5, "optional": false, "goal": "Đội chia người cho từng chặng tiếp sức.", "beats": ["Mỗi người chọn chặng hợp sức mình.", "Hai bạn trẻ trao gậy tiếp sức: mỗi câu đúng là một lần trao gậy."], "question_hook": "Câu hỏi chung của đội ở bến.", "reward": "Đội hình.", "vocab": ["team", "relay", "turn", "baton"], "assets": ["river_dock", "camp_bunting", "kayak_boat", "char_skater_boy", "char_boy_1"]}, {"n": 2, "title": "Chặng 1: Bến làng", "minutes": 5, "optional": false, "goal": "Người thứ nhất xuất phát.", "beats": ["Trao mái chèo ở bến 2.", "Chuyền cờ tiếp sức giữa kayak và thuyền chèo của bác chài.", "Ngựa nâu của làng kéo thuyền qua bến cạn: đọc đúng tên mới đi tiếp."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Nitro trao gậy.", "vocab": ["pass", "next", "quick", "rowboat", "pigeon", "horse", "village"], "assets": ["kayak_paddle", "river_dock", "river_birds", "river_boat_row", "village_horse_a"]}, {"n": 3, "title": "Chặng 2: Chợ nổi", "minutes": 5, "optional": false, "goal": "Lách qua ghe chợ nổi.", "beats": ["Ghe trái cây di chuyển chậm.", "Chợ nổi: kayak lách qua thuyền chèo chất đầy giỏ đan, mỗi món đọc đúng tên là mở lối."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Đường lách.", "vocab": ["market", "boat", "fruit", "avoid", "basket", "rowboat"], "assets": ["river_boat_row", "food_apple", "fish_basket", "river_buoy"]}, {"n": 4, "title": "Chặng 3: Cầu làng", "minutes": 5, "optional": false, "goal": "Lướt dưới cầu làng, dân làng cổ vũ.", "beats": ["Câu đúng = tiếng trống cổ vũ, Nitro.", "Ngựa trắng đứng chờ ở đầu cầu làng, nhìn các kayak lách qua."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Nitro trống.", "vocab": ["village", "drum", "cheer", "bridge", "horse"], "assets": ["river_bridge", "village_horse_b"]}, {"n": 5, "title": "Chặng 4: Đồng sen", "minutes": 5, "optional": false, "goal": "Đi qua đồng sen, tránh lá sen lớn.", "beats": ["Lá sen làm chậm kayak."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Lạch sen.", "vocab": ["lotus", "leaf", "pink"], "assets": ["river_lilypad", "river_reed"]}, {"n": 6, "title": "Về đích ngày hội", "minutes": 5, "optional": false, "goal": "Người cuối về đích, cả đội ăn mừng.", "beats": ["Giỏ trái cây và vòng hoa."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Cúp Tiếp Sức.", "vocab": ["together", "finish", "celebrate"], "assets": ["kayak_finish_arch", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Chặng bù", "minutes": 5, "optional": true, "goal": "Kéo dài: chặng thêm cho đội muốn gỡ.", "beats": ["Câu nhanh."], "question_hook": "Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["extra", "chance"], "assets": ["kayak_boat"]}, {"n": 8, "title": "Chặng phụ: Lời cảm ơn", "minutes": 5, "optional": true, "goal": "Viết lời cảm ơn đồng đội.", "beats": ["Thẻ cảm ơn trao tay."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.", "reward": "Huy hiệu \"Đồng Đội Vàng\".", "vocab": ["thank you", "helpful", "friend"], "assets": ["river_sign"]}]'::jsonb, '{"sizes": {"1-5": "Mỗi em một kayak đua cùng 2-3 kayak máy (độ khó theo bậc của lớp).", "6-20": "Đội 2-4 kayak cùng màu. Mỗi màn hình hiện kayak của mình + 4 đối thủ gần nhất; bảng xếp hạng cả lớp ở góc.", "21-50": "10 đội × 5 kayak, đua theo 2 lượt xuất phát (25 kayak/lượt) trên cùng đường sông; điểm đội = tổng thứ hạng. Mỗi máy chỉ vẽ 8 kayak gần nhất để nhẹ."}, "roles": ["Đội trưởng (chọn đường tắt)", "Tay chèo Nitro", "Hoa tiêu (đọc biển báo)", "Người cứu hộ (giúp kayak lật)"], "scoring": "Thứ hạng + số Nitro + đường tắt mở được. Đúng 3 câu liền = Siêu Nitro.", "avatars": "Mỗi học sinh ngồi kayak bằng nhân vật riêng ghép từ hồ sơ diện mạo, áo phao màu đội, mũ ngộ nghĩnh tự chọn.", "style": "Nâng cấp theo gói thế giới sông bán thực (như 3 game mới); chướng ngại: khúc gỗ xoay, đá ngầm, xoáy nước, ghềnh, cây trôi.", "note": "Đội 4-5 người, mỗi người 1-2 chặng; ai chờ lượt thì trả lời câu \"cổ vũ\" để nạp Nitro cho người đang chèo."}'::jsonb, array['anim_cheer','camp_bunting','char_boy_1','char_skater_boy','fish_basket','food_apple','kayak_boat','kayak_finish_arch','kayak_paddle','river_birds','river_boat_row','river_bridge','river_buoy','river_dock','river_lilypad','river_reed','river_sign','village_horse_a','village_horse_b']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
