insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('kayak-05', 'kayak_rush', 5, 'Lễ Hội Đua Đèn Lồng Đêm', 'Gói sông chung, HDRI đêm, đèn lồng; đua đêm lung linh.', 'Đêm rằm tháng Tám, làng ven sông tổ chức Lễ Hội Đua Đèn Lồng: mỗi kayak gắn một đèn lồng ở mũi. Chị Hằng Nga trong vai nữ thần trăng đứng trên thuyền rồng làm trọng tài. Đèn lồng sáng hơn khi tay chèo trả lời đúng, và đèn tắt thì kayak chậm lại trong bóng tối. Giữa cuộc đua, đèn lồng trôi dày đặc thành "dòng sông ánh sáng", các đội phải lách khéo để không làm đổ đèn. Về đích, đội có đèn sáng nhất được thả đèn lồng ước nguyện đầu tiên lên trời.', 6, 5, 30, 12, true, 'Sông đêm trong lễ hội đèn lồng: hàng nghìn đèn lồng thả trôi, pháo hoa trên trời, hai bờ đông người. Ánh đèn phản chiếu lung linh trên mặt nước.', '[{"n": 1, "title": "Thắp đèn mũi kayak", "minutes": 5, "optional": false, "goal": "Thắp đèn lồng gắn mũi kayak.", "beats": ["Đèn sáng theo câu đúng."], "question_hook": "Câu hỏi trên đèn lồng.", "reward": "Đèn sáng.", "vocab": ["lantern", "festival", "moon"], "assets": ["camp_lantern", "kayak_boat", "hdri_night"]}, {"n": 2, "title": "Xuất phát dưới pháo hoa", "minutes": 5, "optional": false, "goal": "Pháo hoa khai hội, xuất phát.", "beats": ["Mỗi chùm pháo hoa một câu."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Nitro pháo hoa.", "vocab": ["fireworks", "start", "bright"], "assets": ["kayak_paddle", "fx_spark"]}, {"n": 3, "title": "Dòng sông ánh sáng", "minutes": 5, "optional": false, "goal": "Lách qua đèn lồng trôi dày đặc.", "beats": ["Chạm đèn trôi: chậm 1 giây."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Không đổ đèn = sao thưởng.", "vocab": ["float", "gently", "careful"], "assets": ["camp_lantern", "water_normal"]}, {"n": 4, "title": "Thuyền rồng", "minutes": 5, "optional": false, "goal": "Vượt qua thuyền rồng của trọng tài.", "beats": ["Chị Hằng Nga đặt câu đố trăng."], "question_hook": "Câu đố trên thuyền rồng.", "reward": "Nitro trăng.", "vocab": ["dragon", "boat", "riddle"], "assets": ["river_boat_row"]}, {"n": 5, "title": "Cầu đèn", "minutes": 5, "optional": false, "goal": "Lướt dưới cây cầu treo đầy đèn.", "beats": ["Khán giả reo khi đúng."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Nitro cầu đèn.", "vocab": ["bridge", "lights", "cheer"], "assets": ["river_bridge", "camp_string_lights"]}, {"n": 6, "title": "Thả đèn ước nguyện", "minutes": 5, "optional": false, "goal": "Về đích, thả đèn ước nguyện.", "beats": ["Đèn của đội thắng bay lên đầu tiên."], "question_hook": "Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.", "reward": "Danh hiệu \"Đèn Lồng Sáng Nhất\".", "vocab": ["wish", "fly", "happy"], "assets": ["kayak_finish_arch", "camp_lantern", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Vòng trăng", "minutes": 5, "optional": true, "goal": "Kéo dài: chèo vòng dưới trăng.", "beats": ["Câu nhanh."], "question_hook": "Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["round", "full moon"], "assets": ["hdri_night"]}, {"n": 8, "title": "Chặng phụ: Điều ước", "minutes": 5, "optional": true, "goal": "Viết điều ước tiếng Anh lên đèn.", "beats": ["Đèn thả trôi sông."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.", "reward": "Huy hiệu \"Đêm Hội Trăng\".", "vocab": ["I wish", "family", "future"], "assets": ["camp_lantern"]}]'::jsonb, '{"sizes": {"1-5": "Mỗi em một kayak đua cùng 2-3 kayak máy (độ khó theo bậc của lớp).", "6-20": "Đội 2-4 kayak cùng màu. Mỗi màn hình hiện kayak của mình + 4 đối thủ gần nhất; bảng xếp hạng cả lớp ở góc.", "21-50": "10 đội × 5 kayak, đua theo 2 lượt xuất phát (25 kayak/lượt) trên cùng đường sông; điểm đội = tổng thứ hạng. Mỗi máy chỉ vẽ 8 kayak gần nhất để nhẹ."}, "roles": ["Đội trưởng (chọn đường tắt)", "Tay chèo Nitro", "Hoa tiêu (đọc biển báo)", "Người cứu hộ (giúp kayak lật)"], "scoring": "Thứ hạng + số Nitro + đường tắt mở được. Đúng 3 câu liền = Siêu Nitro.", "avatars": "Mỗi học sinh ngồi kayak bằng nhân vật riêng ghép từ hồ sơ diện mạo, áo phao màu đội, mũ ngộ nghĩnh tự chọn.", "style": "Nâng cấp theo gói thế giới sông bán thực (như 3 game mới); chướng ngại: khúc gỗ xoay, đá ngầm, xoáy nước, ghềnh, cây trôi."}'::jsonb, array['anim_cheer','camp_lantern','camp_string_lights','fx_spark','hdri_night','kayak_boat','kayak_finish_arch','kayak_paddle','river_boat_row','river_bridge','water_normal']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
