insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('mv-01', 'multiverse_portal', 1, 'Lâu Đài Sương Mù', 'File mục I.2 (nữ chiến binh 3D, diệt Boss mở cổng Stencil Portal); thế giới lâu đài sương mù đã có.', 'Chúa Tể Vết Nứt đã đánh cắp Cuốn Sách Ngôn Từ, khiến chữ nghĩa trong vương quốc bắt đầu biến mất. Nữ chiến binh Scarlet cùng các bạn lần theo hắn vào Lâu Đài Sương Mù. Mỗi đòn đánh trúng làm rơi một trang sách, và mỗi trang mang một từ được cứu lại. Khi Chúa Tể yếu đi, hắn xé rách không gian và bỏ chạy qua vết nứt sang một thế giới khác. Scarlet phải lấy lại đủ trang sách trước khi chuông lâu đài điểm 12 tiếng.', 6, 5, 30, 12, true, 'Lâu đài gothic đổ nát trên đảo bay, sương tím phủ lối đá, cửa sổ kính màu vỡ, đèn ma trơi xanh. Tiếng chuông xa vọng lại. Bên kia hành lang kính màu là khu rừng phép lấp lánh; tường lâu đài nứt thành vết sáng.', '[{"n": 1, "title": "Cổng lâu đài", "minutes": 5, "optional": false, "goal": "Vào lâu đài, gặp lính canh sương.", "beats": ["Lính canh làm bằng sương, tan khi trúng đòn.", "Thầy Thuốc Lục, nữ tiên rừng cầm trượng, trao thảo dược hồi máu: đọc đúng tên thảo dược để nhận."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Mở cổng.", "vocab": ["castle", "gate", "fog", "healer", "herb"], "assets": ["mv_world_castle", "mv_hero_scarlet", "mv_npc_druid_elf"]}, {"n": 2, "title": "Hành lang kính màu", "minutes": 5, "optional": false, "goal": "Đánh bóng ma trên hành lang.", "beats": ["Mỗi trang sách rơi ra một từ.", "Cửa kính mở ra khu rừng phép: đọc đúng chữ thì lối đi hiện."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Trang sách 1-3.", "vocab": ["page", "word", "save", "enchanted", "forest"], "assets": ["mv_world_castle", "mv_world_enchanted_candidate"]}, {"n": 3, "title": "Chúa Tể xuất hiện", "minutes": 5, "optional": false, "goal": "Đối đầu Chúa Tể Vết Nứt pha 1.", "beats": ["Thanh máu Boss lớn.", "Lính Sương lờ mờ hiện ra trong sương: đọc đúng chữ trên khiên mờ để xua chúng đi."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Chí mạng mở Kỹ năng.", "vocab": ["boss", "attack", "shield", "mist", "guard"], "assets": ["mv_boss", "mv_minion_shadow"]}, {"n": 4, "title": "Pha 2: Cơn thịnh nộ", "minutes": 5, "optional": false, "goal": "Boss dưới 50%: đổi dạng, đánh mạnh hơn.", "beats": ["Sai 3 câu liền: Boss nổi giận, gợi ý sâu hơn."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Kỹ năng Mắt Sự Thật.", "vocab": ["angry", "phase", "strong"], "assets": ["mv_boss", "fx_spark"]}, {"n": 5, "title": "Vết nứt mở", "minutes": 5, "optional": false, "goal": "Boss xé không gian bỏ chạy: Scarlet nhảy theo qua cổng.", "beats": ["Hiệu ứng cổng Stencil.", "Vết nứt trên tường mở rộng: mỗi câu đúng làm nó khép lại một đoạn."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Thế giới mới hé lộ.", "vocab": ["portal", "jump", "chase", "crack", "wall"], "assets": ["mv_world_cyberpunk", "mv_wall_breach"]}, {"n": 6, "title": "Chuông 12 tiếng", "minutes": 5, "optional": false, "goal": "Đánh bại Boss, lấy lại Cuốn Sách Ngôn Từ.", "beats": ["Chữ nghĩa trở lại vương quốc.", "Công Chúa Ngôn nhảy mừng khi Cuốn Sách Ngôn Từ trở lại đủ trang."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Danh hiệu \"Người Giữ Sách\".", "vocab": ["victory", "book", "return", "princess"], "assets": ["mv_world_castle", "anim_cheer", "char_kid_dancer"]}, {"n": 7, "title": "Chặng phụ: Thư viện tầng hầm", "minutes": 5, "optional": true, "goal": "Kéo dài: đánh lính sương trong thư viện.", "beats": ["Câu nhanh."], "question_hook": "Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["library", "shelf"], "assets": ["mv_world_castle"]}, {"n": 8, "title": "Chặng phụ: Viết lại trang sách", "minutes": 5, "optional": true, "goal": "Viết lại một trang sách bằng câu của mình.", "beats": ["Trang sách in vào hồ sơ học viên."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.", "reward": "Huy hiệu \"Nhà Văn Lâu Đài\".", "vocab": ["once upon a time", "hero"], "assets": ["mv_world_castle"]}]'::jsonb, '{"sizes": {"1-5": "Mỗi em một Scarlet riêng đánh Boss của mình (bài tập về nhà), hoặc cả nhóm chung một Boss.", "6-20": "Tổ đội 4-5 người chung một Boss (Co-op Raid), Boss có máu theo số người.", "21-50": "10 tổ đội × 5 người, mỗi tổ đội một Boss riêng chạy song song; bảng xếp hạng tổ đội chung. Cuối trận, 10 tổ đội hợp sức đánh \"Boss Hợp Thể\" 2 phút."}, "roles": ["Kiếm sĩ (gây sát thương)", "Pháp sư Khiên (đỡ đòn)", "Thầy Thuốc (hồi máu)", "Trinh sát Cổng (tìm điểm yếu)"], "scoring": "Sát thương + chí mạng + chuỗi đúng. Máy chủ chấm đáp án và máu Boss.", "avatars": "Học sinh điều khiển phiên bản Scarlet của riêng mình (màu áo choàng và vũ khí lấy từ hồ sơ diện mạo).", "style": "Giữ phong cách giả tưởng cách điệu (không dùng gói sông)."}'::jsonb, array['anim_cheer','char_kid_dancer','fx_spark','mv_boss','mv_hero_scarlet','mv_minion_shadow','mv_npc_druid_elf','mv_wall_breach','mv_world_castle','mv_world_cyberpunk','mv_world_enchanted_candidate']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
