insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('mv-01#12', 'mv-01', 12, 'Rồng Con Bông', 'Rồng nhỏ của Scarlet, phun lửa khi chí mạng', 'child', 'n', 'S7', false, 'E_light_brown', 'brown', 'curly', 'shoulder', false, false, 'fantasy_scifi', 'orange', 'Vảy cam', null, null, array['pet_or_toy']::text[], 'Linh thú', 'heroes');
insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('mv-02', 'multiverse_portal', 2, 'Thành Phố Neon Đêm Mưa', 'Thế giới cyberpunk neon đã có trong manifest; cổng không gian.', 'Chạy qua vết nứt, Chúa Tể Vết Nứt trốn vào Thành Phố Neon và chiếm tháp truyền tin. Hắn đổi chữ trên mọi bảng hiệu thành mật mã, làm người dân lạc đường. Scarlet và tổ đội phải nhảy qua mái nhà, sửa bảng hiệu bằng câu trả lời đúng và leo lên tháp. Trên đỉnh tháp, Chúa Tể triệu hồi robot bảo vệ, rồi lại xé không gian định trốn sang sa mạc. Lần này Scarlet có Kỹ năng Khóa Cổng, nếu chuỗi đúng đủ dài.', 6, 5, 30, 12, true, 'Thành phố tương lai đêm mưa, bảng neon hồng xanh, xe bay, mái nhà ướt phản chiếu ánh đèn. Tiếng mưa và nhạc điện tử xa.', '[{"n": 1, "title": "Hẻm neon", "minutes": 5, "optional": false, "goal": "Đáp xuống hẻm neon, sửa bảng hiệu đầu tiên.", "beats": ["Bảng hiệu sáng đúng chữ.", "Tòa nhà hoang trong hẻm neon là chỗ ẩn của robot: chạm đúng cửa sổ phát sáng để vào."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Bản đồ thành phố.", "vocab": ["city", "sign", "neon", "building", "ruin"], "assets": ["mv_world_cyberpunk", "mv_hero_scarlet", "mv_ruin_building"]}, {"n": 2, "title": "Mái nhà mưa", "minutes": 5, "optional": false, "goal": "Nhảy qua mái nhà, tránh drone.", "beats": ["Drone soi đèn đỏ."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Giày phản lực.", "vocab": ["jump", "roof", "rain"], "assets": ["mv_world_cyberpunk"]}, {"n": 3, "title": "Robot bảo vệ", "minutes": 5, "optional": false, "goal": "Đánh robot bảo vệ tháp.", "beats": ["Robot có khiên năng lượng."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Phá khiên.", "vocab": ["robot", "shield", "break"], "assets": ["mv_boss"]}, {"n": 4, "title": "Đỉnh tháp", "minutes": 5, "optional": false, "goal": "Đối đầu Chúa Tể pha 1.", "beats": ["Mưa tạo sấm khi chí mạng."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Chí mạng sấm.", "vocab": ["tower", "top", "thunder"], "assets": ["mv_boss", "fx_spark"]}, {"n": 5, "title": "Pha 2 và Khóa Cổng", "minutes": 5, "optional": false, "goal": "Boss dưới 50% mở cổng; chuỗi 5 câu đúng khóa cổng 20 giây.", "beats": ["Khóa thành công = sát thương gấp đôi."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Kỹ năng Khóa Cổng.", "vocab": ["lock", "chain", "combo"], "assets": ["mv_boss", "mv_world_desert"]}, {"n": 6, "title": "Thành phố sáng lại", "minutes": 5, "optional": false, "goal": "Đánh bại Chúa Tể, mọi bảng hiệu sáng đúng chữ.", "beats": ["Pháo hoa neon."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Danh hiệu \"Anh Hùng Neon\".", "vocab": ["light", "city", "saved"], "assets": ["mv_world_cyberpunk", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Đường đua xe bay", "minutes": 5, "optional": true, "goal": "Kéo dài: đuổi Quạ Tím bằng xe bay.", "beats": ["Câu nhanh."], "question_hook": "Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["fly", "chase"], "assets": ["mv_world_cyberpunk"]}, {"n": 8, "title": "Chặng phụ: Bảng hiệu của em", "minutes": 5, "optional": true, "goal": "Thiết kế một bảng hiệu tiếng Anh cho thành phố.", "beats": ["Bảng hiệu treo trong game."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.", "reward": "Huy hiệu \"Nhà Thiết Kế Neon\".", "vocab": ["open", "welcome", "shop"], "assets": ["mv_world_cyberpunk"]}]'::jsonb, '{"sizes": {"1-5": "Mỗi em một Scarlet riêng đánh Boss của mình (bài tập về nhà), hoặc cả nhóm chung một Boss.", "6-20": "Tổ đội 4-5 người chung một Boss (Co-op Raid), Boss có máu theo số người.", "21-50": "10 tổ đội × 5 người, mỗi tổ đội một Boss riêng chạy song song; bảng xếp hạng tổ đội chung. Cuối trận, 10 tổ đội hợp sức đánh \"Boss Hợp Thể\" 2 phút."}, "roles": ["Kiếm sĩ (gây sát thương)", "Pháp sư Khiên (đỡ đòn)", "Thầy Thuốc (hồi máu)", "Trinh sát Cổng (tìm điểm yếu)"], "scoring": "Sát thương + chí mạng + chuỗi đúng. Máy chủ chấm đáp án và máu Boss.", "avatars": "Học sinh điều khiển phiên bản Scarlet của riêng mình (màu áo choàng và vũ khí lấy từ hồ sơ diện mạo).", "style": "Giữ phong cách giả tưởng cách điệu (không dùng gói sông)."}'::jsonb, array['anim_cheer','fx_spark','mv_boss','mv_hero_scarlet','mv_npc_druid_elf','mv_ruin_building','mv_world_cyberpunk','mv_world_desert']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
