insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('mv-03', 'multiverse_portal', 3, 'Tàn Tích Sa Mạc Cát Vàng', 'Thế giới sa mạc tàn tích trong manifest; cổng không gian.', 'Vết nứt cuối cùng đưa Chúa Tể Vết Nứt đến Tàn Tích Sa Mạc, nơi chôn Đá Ngữ Pháp cổ. Nếu hắn chạm được viên đá, mọi câu văn trong đa vũ trụ sẽ đảo lộn trật tự. Scarlet phải vượt bão cát, giải câu đố trên các bức tượng đá để mở cửa kim tự tháp trước hắn. Trong lòng kim tự tháp, những bậc thang chỉ hiện ra khi câu được sắp xếp đúng trật tự. Trận cuối diễn ra quanh Đá Ngữ Pháp, mỗi đòn đúng làm viên đá sáng lên che chở Scarlet.', 6, 5, 30, 12, true, 'Sa mạc cát vàng, kim tự tháp đổ nát, tượng đá khổng lồ vùi nửa người trong cát, ốc đảo xanh xa xa. Nắng gắt, bão cát nổi lên từng đợt. Giữa bão cát thấp thoáng một cù lao xanh có cọ và gốc cây cổ: ốc đảo thật.', '[{"n": 1, "title": "Bão cát", "minutes": 5, "optional": false, "goal": "Vượt bão cát đến tàn tích.", "beats": ["Cát che tầm nhìn, câu đúng soi đường."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Khăn che cát.", "vocab": ["desert", "sand", "storm"], "assets": ["mv_world_desert", "mv_hero_scarlet"]}, {"n": 2, "title": "Tượng đá", "minutes": 5, "optional": false, "goal": "Giải câu đố trên tượng đá.", "beats": ["Tượng mở mắt khi trả lời đúng.", "Tấm đá cát nằm nghiêng làm bục đứng cho tượng đá; đặt đúng chữ thì tượng mới nhúc nhích.", "Một ngôi đền cổ thu nhỏ hiện sau tượng đá: đặt đúng chữ để mở cửa đền."], "question_hook": "Câu đố khắc trên tượng; đúng = tượng nhường đường.", "reward": "Chìa khóa kim tự tháp.", "vocab": ["statue", "riddle", "ancient", "slab", "sand", "temple", "ruin"], "assets": ["mv_world_desert", "ground_sand_slab", "mv_world_ruin_candidate"]}, {"n": 3, "title": "Bậc thang trật tự", "minutes": 5, "optional": false, "goal": "Sắp xếp câu đúng để bậc thang hiện ra.", "beats": ["Hợp câu sắp xếp (reorder)."], "question_hook": "Mỗi câu xếp đúng hiện một bậc thang.", "reward": "Lên tầng trên.", "vocab": ["order", "stairs", "climb"], "assets": ["mv_world_desert"]}, {"n": 4, "title": "Chúa Tể pha 1", "minutes": 5, "optional": false, "goal": "Đối đầu Chúa Tể quanh Đá Ngữ Pháp.", "beats": ["Đá sáng lên theo đòn đúng.", "Thầy Thuốc Lục pha nước thảo dược ở ốc đảo: mỗi câu đúng là một bình hồi sức cho tổ đội."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Khiên Đá Ngữ Pháp.", "vocab": ["grammar", "stone", "glow", "oasis", "heal"], "assets": ["mv_boss", "mv_npc_druid_elf"]}, {"n": 5, "title": "Pha 2: Bọ cạp cát", "minutes": 5, "optional": false, "goal": "Boss triệu hồi bọ cạp cát khổng lồ.", "beats": ["Bọ cạp chặn đòn; trinh sát tìm điểm yếu."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Chí mạng điểm yếu.", "vocab": ["scorpion", "weak point"], "assets": ["mv_boss", "fx_spark"]}, {"n": 6, "title": "Ốc đảo", "minutes": 5, "optional": false, "goal": "Đánh bại Boss, đem Đá Ngữ Pháp về ốc đảo an toàn.", "beats": ["Cát lặng, ốc đảo nở hoa.", "Ốc đảo hiện lên giữa cát: đúng câu thì cọ xanh trở lại."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Danh hiệu \"Người Giữ Đá Ngữ Pháp\".", "vocab": ["oasis", "peace", "win", "palm tree"], "assets": ["mv_world_desert", "anim_cheer", "mini_large_island"]}, {"n": 7, "title": "Chặng phụ: Lạc đà", "minutes": 5, "optional": true, "goal": "Kéo dài: cưỡi lạc đà đuổi Quạ Tím.", "beats": ["Câu nhanh."], "question_hook": "Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["camel", "ride"], "assets": ["mv_world_desert"]}, {"n": 8, "title": "Chặng phụ: Bia đá mới", "minutes": 5, "optional": true, "goal": "Khắc một câu đúng ngữ pháp lên bia đá.", "beats": ["Bia đá đặt ở ốc đảo."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.", "reward": "Huy hiệu \"Nhà Khảo Cổ Nhí\".", "vocab": ["carve", "sentence"], "assets": ["mv_world_desert"]}]'::jsonb, '{"sizes": {"1-5": "Mỗi em một Scarlet riêng đánh Boss của mình (bài tập về nhà), hoặc cả nhóm chung một Boss.", "6-20": "Tổ đội 4-5 người chung một Boss (Co-op Raid), Boss có máu theo số người.", "21-50": "10 tổ đội × 5 người, mỗi tổ đội một Boss riêng chạy song song; bảng xếp hạng tổ đội chung. Cuối trận, 10 tổ đội hợp sức đánh \"Boss Hợp Thể\" 2 phút."}, "roles": ["Kiếm sĩ (gây sát thương)", "Pháp sư Khiên (đỡ đòn)", "Thầy Thuốc (hồi máu)", "Trinh sát Cổng (tìm điểm yếu)"], "scoring": "Sát thương + chí mạng + chuỗi đúng. Máy chủ chấm đáp án và máu Boss.", "avatars": "Học sinh điều khiển phiên bản Scarlet của riêng mình (màu áo choàng và vũ khí lấy từ hồ sơ diện mạo).", "style": "Giữ phong cách giả tưởng cách điệu (không dùng gói sông)."}'::jsonb, array['anim_cheer','fx_spark','ground_sand_slab','mini_large_island','mv_boss','mv_hero_scarlet','mv_npc_druid_elf','mv_world_desert','mv_world_ruin_candidate']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
