insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('mv-04', 'multiverse_portal', 4, 'Cổng Vỡ Đuổi Bắt', 'Cổng Stencil xé không gian; chuyển cảnh mượt giữa lâu đài và thành phố neon.', 'Chúa Tể Vết Nứt học được cách mở nhiều cổng cùng lúc, và hai thế giới lâu đài và thành phố neon bắt đầu va vào nhau. Scarlet phải đuổi theo hắn qua những mảnh thế giới trôi nổi, mỗi lần nhảy cổng là sang một thế giới khác. Cổng chỉ đứng yên khi tổ đội trả lời đúng, sai thì cổng rung và đổi chỗ. Giữa đường, Quạ Tím bày bẫy cổng giả dẫn sang chỗ không lối thoát. Đóng được cổng cuối, hai thế giới sẽ tách ra và Chúa Tể bị kẹt giữa.', 6, 5, 30, 12, true, 'Không gian nứt vỡ: một nửa là lâu đài sương mù, một nửa là thành phố neon, các mảnh thế giới trôi lơ lửng nối nhau bằng cầu ánh sáng. Một đảo xanh nhỏ có sông và hải đăng trôi lạc giữa các mảnh vỡ.', '[{"n": 1, "title": "Mảnh lâu đài", "minutes": 5, "optional": false, "goal": "Bắt đầu ở mảnh lâu đài trôi nổi.", "beats": ["Cầu ánh sáng hiện theo câu đúng."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Cầu ánh sáng.", "vocab": ["bridge", "float", "light"], "assets": ["mv_world_castle"]}, {"n": 2, "title": "Nhảy cổng 1", "minutes": 5, "optional": false, "goal": "Nhảy sang mảnh thành phố neon.", "beats": ["Cổng đứng yên khi đúng.", "Đấu sĩ Đỏ chỉ đường qua cổng đầu tiên, rồi biến mất vào ánh sáng."], "question_hook": "Câu hỏi trên khung cổng.", "reward": "Sang thế giới mới.", "vocab": ["portal", "switch", "world", "kick"], "assets": ["mv_world_cyberpunk", "char_crimson_kick"]}, {"n": 3, "title": "Cổng giả của Quạ Tím", "minutes": 5, "optional": false, "goal": "Phân biệt cổng thật và cổng giả.", "beats": ["Câu đúng soi ra cổng giả.", "Lính Sương canh cầu ánh sáng: trả lời đúng để chúng tan thành sương."], "question_hook": "Câu trắc nghiệm: chọn cổng thật.", "reward": "Tránh bẫy.", "vocab": ["true", "false", "trap", "shadow", "bridge"], "assets": ["mv_world_castle", "mv_world_cyberpunk", "mv_minion_shadow"]}, {"n": 4, "title": "Chúa Tể giữa hai thế giới", "minutes": 5, "optional": false, "goal": "Đánh Boss pha 1 trên mảnh vỡ.", "beats": ["Mảnh vỡ nghiêng khi Boss tấn công.", "Scarlet lắp nỏ ấn phép: mỗi câu đúng nạp một mũi tên sáng."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Chí mạng.", "vocab": ["boss", "balance", "crossbow", "rune"], "assets": ["mv_boss", "mv_weapon_runecrossbow"]}, {"n": 5, "title": "Pha 2: Bão cổng", "minutes": 5, "optional": false, "goal": "Boss mở hàng loạt cổng nhỏ bắn phép.", "beats": ["Pháp sư Khiên đỡ đòn khi đúng."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Khiên cổng.", "vocab": ["shield", "many", "dodge"], "assets": ["mv_boss", "fx_spark"]}, {"n": 6, "title": "Đóng cổng cuối", "minutes": 5, "optional": false, "goal": "Đánh bại Boss, đóng cổng, hai thế giới tách ra.", "beats": ["Hiệu ứng hai thế giới trượt về chỗ cũ."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Danh hiệu \"Người Đóng Cổng\".", "vocab": ["close", "separate", "safe"], "assets": ["mv_world_castle", "mv_world_cyberpunk", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Mảnh vỡ lạc", "minutes": 5, "optional": true, "goal": "Kéo dài: nhặt mảnh vỡ còn sót.", "beats": ["Câu nhanh.", "Mảnh vỡ lạc là một đảo nhỏ có hải đăng: đưa nó về đúng cổng để thắp đèn dẫn đường."], "question_hook": "Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["piece", "collect", "island", "lighthouse"], "assets": ["mv_world_castle", "mini_floating_island"]}, {"n": 8, "title": "Chặng phụ: Nhật ký cổng", "minutes": 5, "optional": true, "goal": "Ghi lại các thế giới đã đi qua.", "beats": ["Nhật ký lưu vào hồ sơ."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.", "reward": "Huy hiệu \"Lữ Khách Đa Vũ Trụ\".", "vocab": ["visited", "saw", "met"], "assets": ["mv_world_cyberpunk"]}]'::jsonb, '{"sizes": {"1-5": "Mỗi em một Scarlet riêng đánh Boss của mình (bài tập về nhà), hoặc cả nhóm chung một Boss.", "6-20": "Tổ đội 4-5 người chung một Boss (Co-op Raid), Boss có máu theo số người.", "21-50": "10 tổ đội × 5 người, mỗi tổ đội một Boss riêng chạy song song; bảng xếp hạng tổ đội chung. Cuối trận, 10 tổ đội hợp sức đánh \"Boss Hợp Thể\" 2 phút."}, "roles": ["Kiếm sĩ (gây sát thương)", "Pháp sư Khiên (đỡ đòn)", "Thầy Thuốc (hồi máu)", "Trinh sát Cổng (tìm điểm yếu)"], "scoring": "Sát thương + chí mạng + chuỗi đúng. Máy chủ chấm đáp án và máu Boss.", "avatars": "Học sinh điều khiển phiên bản Scarlet của riêng mình (màu áo choàng và vũ khí lấy từ hồ sơ diện mạo).", "style": "Giữ phong cách giả tưởng cách điệu (không dùng gói sông)."}'::jsonb, array['anim_cheer','char_crimson_kick','fx_spark','mini_floating_island','mv_boss','mv_hero_scarlet','mv_minion_shadow','mv_npc_druid_elf','mv_weapon_runecrossbow','mv_world_castle','mv_world_cyberpunk']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
