insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('mv-05', 'multiverse_portal', 5, 'Trận Chung Kết Đa Vũ Trụ', 'Tổng hợp 3 thế giới; trận cuối nhiều pha, cả lớp hợp sức.', 'Chúa Tể Vết Nứt hợp nhất sức mạnh của cả ba thế giới thành Chúa Tể Hợp Thể, đứng ở trái tim đa vũ trụ. Scarlet và mọi tổ đội từng chiến đấu được triệu tập cho trận chung kết. Mỗi pha của Boss mang sức mạnh một thế giới: sương mù lâu đài, sấm neon, bão cát. Chỉ khi cả lớp cùng góp câu trả lời đúng, ba cổng mới đóng dần và Boss mất sức mạnh. Chiến thắng sẽ trả lại hòa bình cho đa vũ trụ và trao cho Scarlet danh hiệu Người Giữ Cổng.', 6, 5, 30, 12, true, 'Trái tim đa vũ trụ: một vòng cung khổng lồ nối ba cổng lâu đài, thành phố neon và sa mạc, bầu trời đầy sao và mảnh thế giới xoay quanh. Khi hòa bình trở lại, một đảo xanh nhỏ có sông và thác nổi lên giữa ba cổng.', '[{"n": 1, "title": "Triệu tập", "minutes": 5, "optional": false, "goal": "Các tổ đội tập hợp ở trái tim đa vũ trụ.", "beats": ["Mỗi tổ đội nhận cờ màu.", "Bốn lữ khách từ các thế giới tới điểm triệu tập: ghép đúng tên và đặc điểm từng người."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Buff tổ đội.", "vocab": ["gather", "team", "final", "hero"], "assets": ["mv_hero_scarlet", "mv_world_castle", "mv_world_cyberpunk", "mv_world_desert", "char_iridescent_voyager", "char_grovaen_female", "char_tpose_boy", "char_wanderer"]}, {"n": 2, "title": "Pha sương mù", "minutes": 5, "optional": false, "goal": "Boss dùng sức mạnh lâu đài.", "beats": ["Sương che bớt đáp án (Mắt Sự Thật giúp)."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Đóng cổng lâu đài.", "vocab": ["fog", "see", "truth"], "assets": ["mv_boss", "mv_world_castle"]}, {"n": 3, "title": "Pha sấm neon", "minutes": 5, "optional": false, "goal": "Boss dùng sức mạnh thành phố.", "beats": ["Sấm đánh khi sai."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Đóng cổng thành phố.", "vocab": ["thunder", "fast", "react"], "assets": ["mv_boss", "mv_world_cyberpunk"]}, {"n": 4, "title": "Pha bão cát", "minutes": 5, "optional": false, "goal": "Boss dùng sức mạnh sa mạc.", "beats": ["Câu sắp xếp làm cát lắng.", "Thầy Thuốc Lục hồi sức cho cả tổ trước trận cuối."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Đóng cổng sa mạc.", "vocab": ["sand", "order", "calm", "heal", "team"], "assets": ["mv_boss", "mv_world_desert", "mv_npc_druid_elf"]}, {"n": 5, "title": "Boss Hợp Thể", "minutes": 5, "optional": false, "goal": "Cả lớp hợp sức đánh Boss Hợp Thể (thanh máu chung).", "beats": ["Mọi tổ đội cùng một thanh máu Boss.", "Thần giữ rừng thức dậy làm một phần của Boss Hợp Thể: câu đúng làm lá trên người nó rụng dần."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Tuyệt kỹ đồng đội.", "vocab": ["together", "ultimate", "all", "guardian", "forest"], "assets": ["mv_boss", "fx_spark", "mv_boss_verdant"]}, {"n": 6, "title": "Hòa bình đa vũ trụ", "minutes": 5, "optional": false, "goal": "Đánh bại Boss, trao danh hiệu.", "beats": ["Ba thế giới sáng rực.", "MVP: sát thương cao nhất.", "Đảo xanh nở hoa khi cả lớp đọc lời thề đúng: dấu hiệu đa vũ trụ lành lại.", "Công Chúa Ngôn nhảy mừng khi Cuốn Sách Ngôn Từ trao danh hiệu cho cả lớp."], "question_hook": "Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.", "reward": "Danh hiệu \"Người Giữ Cổng\".", "vocab": ["peace", "hero", "forever", "waterfall", "award", "celebrate"], "assets": ["mv_world_castle", "anim_cheer", "mini_floating_island", "char_kid_dancer"]}, {"n": 7, "title": "Chặng phụ: Boss phụ Quạ Tím", "minutes": 5, "optional": true, "goal": "Kéo dài: Quạ Tím biến thành chim khổng lồ.", "beats": ["Câu nhanh."], "question_hook": "Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["giant", "bird"], "assets": ["mv_boss"]}, {"n": 8, "title": "Chặng phụ: Lời thề Người Giữ Cổng", "minutes": 5, "optional": true, "goal": "Viết lời thề bảo vệ ngôn từ.", "beats": ["Lời thề khắc vào vòng cung."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.", "reward": "Huy hiệu \"Huyền Thoại Đa Vũ Trụ\".", "vocab": ["promise", "protect", "always"], "assets": ["mv_world_castle"]}]'::jsonb, '{"sizes": {"1-5": "Mỗi em một Scarlet riêng đánh Boss của mình (bài tập về nhà), hoặc cả nhóm chung một Boss.", "6-20": "Tổ đội 4-5 người chung một Boss (Co-op Raid), Boss có máu theo số người.", "21-50": "10 tổ đội × 5 người, mỗi tổ đội một Boss riêng chạy song song; bảng xếp hạng tổ đội chung. Cuối trận, 10 tổ đội hợp sức đánh \"Boss Hợp Thể\" 2 phút."}, "roles": ["Kiếm sĩ (gây sát thương)", "Pháp sư Khiên (đỡ đòn)", "Thầy Thuốc (hồi máu)", "Trinh sát Cổng (tìm điểm yếu)"], "scoring": "Sát thương + chí mạng + chuỗi đúng. Máy chủ chấm đáp án và máu Boss.", "avatars": "Học sinh điều khiển phiên bản Scarlet của riêng mình (màu áo choàng và vũ khí lấy từ hồ sơ diện mạo).", "style": "Giữ phong cách giả tưởng cách điệu (không dùng gói sông).", "note": "Pha 5 dùng thanh máu chung cho cả lớp (mọi tổ đội), các pha khác mỗi tổ đội một Boss."}'::jsonb, array['anim_cheer','char_grovaen_female','char_iridescent_voyager','char_kid_dancer','char_tpose_boy','char_wanderer','fx_spark','mini_floating_island','mv_boss','mv_boss_verdant','mv_hero_scarlet','mv_npc_druid_elf','mv_world_castle','mv_world_cyberpunk','mv_world_desert']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
