insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('camp-01', 'summer_camp', 1, 'Ngày Đầu Trại Hè Bên Hồ', 'File mục II.1 (dựng lều, nhóm lửa, nướng thịt, lọc nước) + video trại bên hồ, cờ tam giác, chảo trên bếp đá vòng.', 'Chiếc xe buýt trại hè dừng bên hồ Ngọc, anh Trưởng trại Phong giao cho mỗi Đội Lều một khoảng đất trống và một tấm Bảng Nhiệm vụ còn trắng tinh. Trước khi mặt trời lặn, cả trại phải có lều vững, lửa ấm, bữa tối nướng thơm và nước sạch cho đêm đầu tiên. Mỗi công cụ (búa cọc, đá đánh lửa, vỉ nướng, bình lọc) bị khóa trong rương gỗ, và chỉ mở khi cả đội trả lời đúng. Đúng lúc bếp vừa đỏ lửa thì một đàn sóc tinh nghịch tha mất túi xúc xích, kéo cả trại vào cuộc truy tìm nho nhỏ. Khi trăng lên, nếu Bảng Nhiệm vụ đầy sao, lửa trại sẽ bùng lên thành hình lá cờ của đội giỏi nhất.', 6, 5, 30, 12, true, 'Bãi cỏ bên hồ xanh ngọc dưới chân núi, nắng sớm xuyên kẽ lá thông, cờ tam giác nhiều màu căng giữa hai cây. Gió mát, mặt hồ lấp lánh, tiếng chim gõ kiến. Từ đồi cao nhìn xuống thấy cả khu trại nhỏ: nhà gỗ, nhà trên cây, bếp lửa; cô hướng dẫn viên đeo ba lô đứng chờ ở cổng.', '[{"n": 1, "title": "Đến trại và mở rương", "minutes": 5, "optional": false, "goal": "Nhận đất cắm trại, mở rương công cụ đầu tiên.", "beats": ["Phim ngắn: xe buýt dừng bên hồ, anh Phong phát Bảng Nhiệm vụ.", "Mỗi Đội Lều mở rương gỗ bằng 3 câu đúng.", "Cô hướng dẫn mở bản đồ nổi của trại; mỗi nơi chạm đúng tên là sáng lên."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Ổ khóa rương có 3 vòng số, mỗi câu đúng xoay một vòng.", "reward": "Búa đóng cọc + dây thừng.", "vocab": ["camp", "tent", "tool", "box", "open", "camp map", "counselor", "backpack"], "assets": ["camp_backpack", "camp_rope", "river_sign", "camp_bunting", "river_tree_pine", "hdri_dawn", "mini_camp_hero", "char_hiker_girl", "ground_grass_platform"]}, {"n": 2, "title": "Dựng lều 3 bước", "minutes": 5, "optional": false, "goal": "Đóng cọc, dựng khung, phủ bạt cho lều của đội.", "beats": ["Lều lên từng giai đoạn: cọc → khung → bạt.", "Gió thổi mạnh nếu sai 3 câu liền: bạt bay nhẹ, phải giữ lại.", "Cạnh lều bạt là một chiếc lều xanh lá của trại bạn để so sánh cách chằng."], "question_hook": "Dạng nối cặp (matching) hợp nhất: mỗi cặp đúng gắn một cọc vào đúng vị trí. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Lều hoàn chỉnh + túi ngủ.", "vocab": ["peg", "pole", "cover", "hammer", "strong", "green tent", "tent"], "assets": ["camp_tent_stage", "camp_sleeping_bag", "camp_tarp", "anim_kneel_work", "camp_tent_green"]}, {"n": 3, "title": "Củi khô và đá lửa", "minutes": 5, "optional": false, "goal": "Nhặt củi khô (tránh củi ướt), xếp bếp đá vòng và đánh lửa.", "beats": ["Củi ướt bốc khói xám, củi khô bén lửa ngay.", "Đá lửa tóe tia sáng mỗi câu đúng; đủ 4 tia thì lửa bén.", "Giá ba chân treo nồi trên vòng đá quanh bếp: dựng đúng ba chân thì nồi không nghiêng.", "Bộ đánh lửa gồm thanh thép, đá lửa và mồi khô nằm trên bàn gỗ: gọi đúng tên từng món để được đánh lửa."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên từng bó củi.", "reward": "Lửa trại + vỉ nướng.", "vocab": ["wood", "dry", "wet", "fire", "spark", "tripod", "stone circle", "fire starter", "flint"], "assets": ["camp_firepit", "river_firewood", "river_woodpile", "camp_matchbox", "camp_axe", "fx_fire", "camp_tripod", "ground_cobble_circle", "camp_fire_starter"]}, {"n": 4, "title": "Nướng xiên bữa tối", "minutes": 5, "optional": false, "goal": "Xiên thịt, cá, rau và nướng đến chín vàng.", "beats": ["Thanh độ chín: trả lời đúng để lật xiên đúng lúc.", "Sai thì xiên hơi cháy cạnh, vẫn ăn được.", "Xiên thịt và xiên rau chờ nướng: đọc đúng tên nguyên liệu trước khi xếp lên vỉ."], "question_hook": "Câu hỏi hiện trên xiên đang nướng; đúng = lật xiên đúng lúc. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Bữa tối (hồi năng lượng cả đội).", "vocab": ["grill", "turn", "cook", "delicious", "hungry", "skewer", "vegetable"], "assets": ["camp_grill", "camp_skewer", "food_meat_raw", "food_meat_cooked", "food_fish_raw", "food_fish_cooked", "camp_table", "anim_cook", "camp_skewer_meat", "camp_skewer_veg"]}, {"n": 5, "title": "Lọc nước hồ", "minutes": 5, "optional": false, "goal": "Lấy nước hồ, lọc qua sỏi, cát, than và đun sôi.", "beats": ["Bình lọc 3 tầng, mỗi câu đúng thêm một tầng.", "Nước chuyển từ đục sang trong ngay trước mắt."], "question_hook": "Câu dạng sắp xếp (reorder) hợp: xếp đúng thứ tự các tầng lọc. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Nước sạch + cốc trại.", "vocab": ["filter", "sand", "boil", "clean", "drink"], "assets": ["camp_water_filter", "camp_bucket", "camp_cup", "camp_bottle", "river_pebbles"]}, {"n": 6, "title": "Truy tìm túi xúc xích", "minutes": 5, "optional": false, "goal": "Đàn sóc tha mất túi xúc xích: lần theo dấu, lấy lại túi, hoàn thành bữa tối và lửa trại.", "beats": ["Dấu chân sóc dẫn qua bến gỗ, gốc cây, bụi dương xỉ.", "Cuối chặng: lửa trại bùng lên hình lá cờ đội nhiều sao nhất."], "question_hook": "Mỗi điểm dấu chân có một câu hỏi; đúng thì sóc lộ ra. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Cờ đỉnh trại cho Đội Lều nhiều sao nhất.", "vocab": ["squirrel", "follow", "find", "sausage"], "assets": ["food_sausage", "river_stump", "river_dock", "river_fern", "camp_lantern", "hdri_sunset"]}, {"n": 7, "title": "Chặng phụ: Nướng kẹo dẻo", "minutes": 5, "optional": true, "goal": "Kéo dài: nướng kẹo dẻo, mỗi câu đúng kẹo phồng to hơn.", "beats": ["Kẹo vàng đều được 3 sao."], "question_hook": "Câu hỏi hiện ngay trên vật thể phát sáng như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["marshmallow", "sweet", "soft"], "assets": ["camp_marshmallow_stick", "camp_firepit"]}, {"n": 8, "title": "Chặng phụ: Nhật ký trại", "minutes": 5, "optional": true, "goal": "Viết 3 câu nhật ký ngày đầu bằng tiếng Anh.", "beats": ["Nhật ký ghim lên bảng gỗ của trại."], "question_hook": "Câu viết ngắn, chấm theo tiêu chí, không tính thua.", "reward": "Huy hiệu \"Trại Viên Ngày Đầu\".", "vocab": ["today", "first", "happy"], "assets": ["camp_lantern", "river_sign"]}]'::jsonb, '{"sizes": {"1-5": "Một Đội Lều chung; mỗi em làm lần lượt các trạm, máy chủ giao thêm việc cho người làm nhanh.", "6-20": "2-4 Đội Lều (4-5 em/đội), mỗi đội một lều riêng và một lá cờ màu. Các đội cùng lấp đầy Bảng Nhiệm vụ trại chung.", "21-50": "8-10 Đội Lều (5 em/đội). Trại chia 2 bãi cạnh nhau để không quá đông; mỗi trạm (bếp, lều, nước, củi) nhận tối đa 2 đội cùng lúc, xoay vòng mỗi 5 phút."}, "roles": ["Đội trưởng Lều (giữ Bảng Nhiệm vụ)", "Thợ dựng lều", "Người giữ lửa", "Đầu bếp", "Thủ kho (công cụ mở khóa)"], "scoring": "Mỗi hành động xong = 1-3 sao theo độ chính xác và tốc độ. Bảng Nhiệm vụ trại chung là thanh \"Boss\" của trận: cả lớp cùng lấp đầy. Đội Lều nhiều sao nhất được cắm cờ trên đỉnh trại.", "avatars": "12 nhân vật dưới đây là người hướng dẫn và bạn trại trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo và đeo khăn màu Đội Lều.", "safety": "Lửa, dao, rìu chỉ dùng qua hoạt ảnh có người lớn hướng dẫn; nhân vật luôn đeo găng khi nướng."}'::jsonb, array['anim_cook','anim_kneel_work','camp_axe','camp_backpack','camp_bottle','camp_bucket','camp_bunting','camp_cup','camp_fire_starter','camp_firepit','camp_grill','camp_lantern','camp_marshmallow_stick','camp_matchbox','camp_rope','camp_skewer','camp_skewer_meat','camp_skewer_veg','camp_sleeping_bag','camp_table','camp_tarp','camp_tent_green','camp_tent_stage','camp_tripod','camp_water_filter','char_hiker_girl','food_fish_cooked','food_fish_raw','food_meat_cooked','food_meat_raw','food_sausage','fx_fire','ground_cobble_circle','ground_grass_platform','hdri_dawn','hdri_sunset','mini_camp_hero','river_dock','river_fern','river_firewood','river_pebbles','river_sign','river_stump','river_tree_pine','river_woodpile']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
