insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('camp-01#12', 'camp-01', 12, 'Sóc Hạt Dẻ', 'Thủ lĩnh đàn sóc tinh nghịch tha túi xúc xích', 'child', 'n', 'S3', false, 'E_brown_dark', 'black', 'bob', 'short', false, false, 'casual', 'brown', 'Lông nâu đuôi xù', null, null, array['pet_or_toy']::text[], 'Linh vật tinh nghịch', 'npc');
insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('camp-02', 'summer_camp', 2, 'Đại Hội Ẩm Thực Lửa Trại', 'Video bảng chế biến món ăn, chảo trên bếp đá + file: nướng thịt, bắt cá.', 'Trại tổ chức Đại hội Ẩm thực, và giám khảo năm nay là đầu bếp nổi tiếng Chef Marco ghé thăm. Mỗi Đội Lều nhận một thẻ công thức bằng tiếng Anh: cá nướng lá chuối, bắp nướng bơ, xiên thịt rau củ và bánh mì nướng. Nguyên liệu phải tự kiếm: bắt cá ở bến, hái rau ở vườn trại, đổi đồ với trại bên cạnh. Giữa chừng, lửa của ba bếp cùng tắt vì cơn gió lạ, cả trại phải cùng nhau nhóm lại. Cuối buổi, Chef Marco chấm điểm từng món, món nào được làm đúng công thức sẽ được đặt lên bàn tiệc lớn của trại.', 6, 5, 30, 12, true, 'Khu bếp chung ven sông, ba bếp đá vòng xếp hàng, bàn gỗ dài phủ khăn caro, đèn dây treo trên đầu. Buổi chiều nắng vàng, mùi khói gỗ thơm. Sau bếp là luống rau của trại và đất tơi mới xới. Chợ trại có xe lừa chở rau, bò sữa đứng gần, và giếng đá giữa sân.', '[{"n": 1, "title": "Thẻ công thức", "minutes": 5, "optional": false, "goal": "Nhận thẻ công thức, đọc nguyên liệu và các bước.", "beats": ["Chef Marco xuất hiện, chọn món cho từng đội.", "Đọc đúng thẻ = mở danh sách nguyên liệu."], "question_hook": "Thẻ công thức hiện như tờ giấy cầm tay; câu đọc hiểu hợp nhất. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Danh sách nguyên liệu.", "vocab": ["recipe", "ingredient", "step", "first"], "assets": ["camp_table", "camp_string_lights", "river_sign"]}, {"n": 2, "title": "Đi chợ trại", "minutes": 5, "optional": false, "goal": "Bắt cá ở bến, hái rau, đổi bắp với trại bên.", "beats": ["Mỗi nguyên liệu là một câu hỏi tại chỗ.", "Đổi đồ: trả lời đúng thì trại bên đồng ý đổi.", "Hái rau ở luống của trại bỏ vào giỏ đan; mỗi loại rau đọc đúng tên mới được hái.", "Xe lừa chở rau tới chợ trại, bò sữa đứng cạnh: đọc đúng tên hàng mới mua được."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Giỏ nguyên liệu đầy.", "vocab": ["fish", "corn", "vegetable", "trade", "basket", "soil", "cart", "cow", "market"], "assets": ["food_fish_raw", "food_corn", "food_apple", "river_dock", "camp_bucket", "ground_farmland", "fish_basket", "ground_soil_patch", "village_cart", "village_cow", "ground_cobble_path_b"]}, {"n": 3, "title": "Sơ chế", "minutes": 5, "optional": false, "goal": "Rửa, cắt, xiên nguyên liệu đúng thứ tự.", "beats": ["Dao chỉ cắt qua hoạt ảnh có găng tay.", "Thứ tự sai thì Chef Marco nhắc nhẹ.", "Giếng đá giữa sân dùng rửa rau: kéo gàu đúng số lần theo câu trả lời."], "question_hook": "Câu sắp xếp (reorder) để xếp các bước sơ chế. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Xiên sẵn sàng.", "vocab": ["wash", "cut", "slice", "mix", "well"], "assets": ["camp_skewer", "camp_table", "food_meat_raw", "camp_well"]}, {"n": 4, "title": "Gió lạ thổi tắt lửa", "minutes": 5, "optional": false, "goal": "Cả trại cùng nhóm lại ba bếp đá.", "beats": ["Thanh lửa chung: mọi Đội Lều trả lời đúng đều làm lửa bùng thêm.", "Củi khô ở kho, củi ướt ở bờ sông."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên từng bếp đá.", "reward": "Ba bếp đỏ lửa.", "vocab": ["wind", "together", "relight", "warm"], "assets": ["camp_firepit", "river_firewood", "camp_matchbox", "fx_fire", "fx_smoke"]}, {"n": 5, "title": "Nướng và lật", "minutes": 5, "optional": false, "goal": "Nướng đúng độ chín theo công thức.", "beats": ["Thanh độ chín cho mỗi món.", "Đúng lúc lật = 3 sao.", "Xiên cá nướng vàng và xiên rau: lật đúng lúc, đọc đúng tên món để Chef Marco chấm điểm."], "question_hook": "Câu hỏi trên món đang nướng; đúng = lật đúng lúc. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Món chín vàng.", "vocab": ["grill", "flip", "golden", "smell", "grilled fish", "turn over"], "assets": ["camp_grill", "camp_pan", "food_fish_cooked", "food_meat_cooked", "food_corn", "anim_cook", "camp_skewer_fish", "camp_skewer_veg"]}, {"n": 6, "title": "Bàn tiệc của Chef Marco", "minutes": 5, "optional": false, "goal": "Trình bày món, Chef Marco chấm, bày lên bàn tiệc lớn.", "beats": ["Mỗi đội giới thiệu món bằng một câu tiếng Anh.", "Bàn tiệc đầy món = Bảng Nhiệm vụ đầy."], "question_hook": "Câu giới thiệu món (viết ngắn hoặc chọn câu đúng). Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Cúp Đầu Bếp Lửa Trại.", "vocab": ["taste", "yummy", "present", "best"], "assets": ["camp_table", "camp_bench", "food_bread", "camp_cup", "hdri_sunset"]}, {"n": 7, "title": "Chặng phụ: Món tráng miệng", "minutes": 5, "optional": true, "goal": "Kéo dài: nướng chuối và táo cho bàn tiệc.", "beats": ["Mỗi câu đúng thêm một phần tráng miệng."], "question_hook": "Câu hỏi hiện ngay trên vật thể phát sáng như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["dessert", "banana", "apple"], "assets": ["food_apple", "camp_grill"]}, {"n": 8, "title": "Chặng phụ: Viết thực đơn", "minutes": 5, "optional": true, "goal": "Viết thực đơn tiếng Anh cho bữa sáng mai.", "beats": ["Thực đơn được dán ở bếp trại."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng gỗ của trại. Câu viết, không tính thua.", "reward": "Huy hiệu \"Đầu Bếp Nhí\".", "vocab": ["breakfast", "menu", "tomorrow"], "assets": ["river_sign"]}]'::jsonb, '{"sizes": {"1-5": "Một Đội Lều chung; mỗi em làm lần lượt các trạm, máy chủ giao thêm việc cho người làm nhanh.", "6-20": "2-4 Đội Lều (4-5 em/đội), mỗi đội một lều riêng và một lá cờ màu. Các đội cùng lấp đầy Bảng Nhiệm vụ trại chung.", "21-50": "8-10 Đội Lều (5 em/đội). Trại chia 2 bãi cạnh nhau để không quá đông; mỗi trạm (bếp, lều, nước, củi) nhận tối đa 2 đội cùng lúc, xoay vòng mỗi 5 phút."}, "roles": ["Đội trưởng Lều (giữ Bảng Nhiệm vụ)", "Thợ dựng lều", "Người giữ lửa", "Đầu bếp", "Thủ kho (công cụ mở khóa)"], "scoring": "Mỗi hành động xong = 1-3 sao theo độ chính xác và tốc độ. Bảng Nhiệm vụ trại chung là thanh \"Boss\" của trận: cả lớp cùng lấp đầy. Đội Lều nhiều sao nhất được cắm cờ trên đỉnh trại.", "avatars": "12 nhân vật dưới đây là người hướng dẫn và bạn trại trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo và đeo khăn màu Đội Lều.", "safety": "Lửa, dao, rìu chỉ dùng qua hoạt ảnh có người lớn hướng dẫn; nhân vật luôn đeo găng khi nướng.", "note": "Mỗi Đội Lều nấu một món khác nhau để các đội không tranh cùng một bếp."}'::jsonb, array['anim_cook','camp_bench','camp_bucket','camp_cup','camp_firepit','camp_grill','camp_matchbox','camp_pan','camp_skewer','camp_skewer_fish','camp_skewer_veg','camp_string_lights','camp_table','camp_well','fish_basket','food_apple','food_bread','food_corn','food_fish_cooked','food_fish_raw','food_meat_cooked','food_meat_raw','fx_fire','fx_smoke','ground_cobble_path_b','ground_farmland','ground_soil_patch','hdri_sunset','river_dock','river_firewood','river_sign','village_cart','village_cow']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
