insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('camp-03', 'summer_camp', 3, 'Bão Nhỏ Ghé Trại', 'File: dựng lều, tìm củi, lọc nước; tình huống thời tiết thay đổi để tăng kịch tính.', 'Đài radio của trại báo một cơn bão nhỏ sẽ đi qua trong nửa giờ. Cô Trưởng trại Linh giao nhiệm vụ: chằng lều thật chắc, che bạt cho bếp, gom củi khô vào kho, đổ đầy nước sạch và treo đèn bão. Gió càng lúc càng mạnh, lều nào chưa chằng sẽ bị thổi nghiêng, củi ngoài trời sẽ ướt. Đúng lúc mưa to nhất, mất một ba lô của Bé Tôm, cả trại phải tìm trong mưa. Khi bão qua, cầu vồng hiện trên sông và cả trại quây quần bên lửa, kể lại cách mình đã giữ trại an toàn.', 6, 5, 30, 12, true, 'Trại bên sông giữa buổi chiều, mây xám kéo về từ đỉnh núi, gió làm cờ tam giác bay phần phật. Mưa lất phất rồi to dần, sau đó tạnh và có cầu vồng.', '[{"n": 1, "title": "Bản tin bão", "minutes": 5, "optional": false, "goal": "Nghe bản tin, lập kế hoạch giữ trại.", "beats": ["Radio phát bản tin tiếng Anh chậm.", "Mỗi Đội Lều chọn 3 việc ưu tiên.", "Bạn nhỏ áo cỏ chạy khắp trại báo tin bão: nghe đúng bản tin mới chuyển được tin."], "question_hook": "Câu nghe hiểu ngắn hợp nhất ở chặng này. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Kế hoạch giữ trại.", "vocab": ["storm", "forecast", "plan", "safe"], "assets": ["camp_lantern", "camp_table", "river_sign", "hdri_cloudy", "char_grass_kid"]}, {"n": 2, "title": "Chằng lều", "minutes": 5, "optional": false, "goal": "Thêm cọc, căng dây gió, siết bạt.", "beats": ["Gió tăng mỗi phút; lều chưa chằng nghiêng dần.", "Mỗi câu đúng thêm một dây gió.", "Lều rách từ trận gió trước nằm cạnh lều mới để so sánh: nhìn chỗ nào hở thì chằng chỗ đó."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên từng sợi dây gió.", "reward": "Lều vững trong bão.", "vocab": ["tie", "tight", "strong", "wind", "torn tent", "rope"], "assets": ["camp_tent_stage", "camp_rope", "camp_tarp", "anim_kneel_work", "camp_tent_damaged"]}, {"n": 3, "title": "Che bếp, gom củi", "minutes": 5, "optional": false, "goal": "Căng bạt che bếp, mang củi khô vào kho trước mưa.", "beats": ["Củi để ngoài sẽ đổi màu sẫm (ướt).", "Bạt căng giữa 2 cây thông."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Kho củi khô.", "vocab": ["cover", "carry", "inside", "dry"], "assets": ["camp_tarp", "river_woodpile", "river_firewood", "river_shed"]}, {"n": 4, "title": "Nước sạch và đèn bão", "minutes": 5, "optional": false, "goal": "Đổ đầy bình nước sạch, treo đèn bão quanh trại.", "beats": ["Đèn treo đủ = lối đi sáng khi trời tối sầm.", "Nước lọc trước khi mưa làm hồ đục."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Đèn bão + nước dự trữ.", "vocab": ["lantern", "light", "fill", "storm"], "assets": ["camp_lantern", "camp_water_filter", "camp_bottle", "camp_bucket"]}, {"n": 5, "title": "Tìm ba lô trong mưa", "minutes": 5, "optional": false, "goal": "Mưa to nhất: tìm ba lô của Bé Tôm theo các manh mối.", "beats": ["Manh mối: chiếc mũ, dấu chân, một con gấu bông.", "Cả trại cùng tìm, mỗi đội một hướng."], "question_hook": "Mỗi manh mối là một câu hỏi; đúng thì manh mối tiếp theo sáng lên. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Ba lô tìm thấy.", "vocab": ["lost", "search", "where", "found"], "assets": ["camp_backpack", "river_bush", "river_stump", "decal_footprint_mud"]}, {"n": 6, "title": "Cầu vồng sau bão", "minutes": 5, "optional": false, "goal": "Bão qua: kiểm tra trại, nhóm lửa, kể chuyện.", "beats": ["Cầu vồng trên sông.", "Bảng Nhiệm vụ đầy = trại đạt \"Trại An Toàn\"."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Danh hiệu \"Trại An Toàn\" + cờ cho Đội Lều giỏi nhất.", "vocab": ["rainbow", "after", "check", "proud"], "assets": ["camp_firepit", "hdri_noon", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Phơi đồ", "minutes": 5, "optional": true, "goal": "Kéo dài: phơi túi ngủ, giày ướt quanh lửa.", "beats": ["Mỗi câu đúng phơi khô một món."], "question_hook": "Câu hỏi hiện ngay trên vật thể phát sáng như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["wet", "dry", "hang"], "assets": ["camp_sleeping_bag", "camp_rope"]}, {"n": 8, "title": "Chặng phụ: Bản tin của em", "minutes": 5, "optional": true, "goal": "Mỗi đội đọc bản tin thời tiết ngày mai bằng tiếng Anh.", "beats": ["Bản tin hay nhất phát lại trên radio trại."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng gỗ của trại. Câu nói/viết ngắn, không tính thua.", "reward": "Huy hiệu \"Người Giữ Trại\".", "vocab": ["sunny", "cloudy", "tomorrow"], "assets": ["camp_lantern"]}]'::jsonb, '{"sizes": {"1-5": "Một Đội Lều chung; mỗi em làm lần lượt các trạm, máy chủ giao thêm việc cho người làm nhanh.", "6-20": "2-4 Đội Lều (4-5 em/đội), mỗi đội một lều riêng và một lá cờ màu. Các đội cùng lấp đầy Bảng Nhiệm vụ trại chung.", "21-50": "8-10 Đội Lều (5 em/đội). Trại chia 2 bãi cạnh nhau để không quá đông; mỗi trạm (bếp, lều, nước, củi) nhận tối đa 2 đội cùng lúc, xoay vòng mỗi 5 phút."}, "roles": ["Đội trưởng Lều (giữ Bảng Nhiệm vụ)", "Thợ dựng lều", "Người giữ lửa", "Đầu bếp", "Thủ kho (công cụ mở khóa)"], "scoring": "Mỗi hành động xong = 1-3 sao theo độ chính xác và tốc độ. Bảng Nhiệm vụ trại chung là thanh \"Boss\" của trận: cả lớp cùng lấp đầy. Đội Lều nhiều sao nhất được cắm cờ trên đỉnh trại.", "avatars": "12 nhân vật dưới đây là người hướng dẫn và bạn trại trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo và đeo khăn màu Đội Lều.", "safety": "Lửa, dao, rìu chỉ dùng qua hoạt ảnh có người lớn hướng dẫn; nhân vật luôn đeo găng khi nướng."}'::jsonb, array['anim_cheer','anim_kneel_work','camp_backpack','camp_bottle','camp_bucket','camp_firepit','camp_lantern','camp_rope','camp_sleeping_bag','camp_table','camp_tarp','camp_tent_damaged','camp_tent_stage','camp_water_filter','char_grass_kid','decal_footprint_mud','hdri_cloudy','hdri_noon','river_bush','river_firewood','river_shed','river_sign','river_stump','river_woodpile']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
