insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('camp-03#12', 'camp-03', 12, 'Gấu Bông Mít', 'Gấu bông của Bé Tôm, rơi làm manh mối', 'child', 'n', 'S6', false, 'E_blue', 'ginger', 'straight', 'shoulder', false, false, 'casual', 'brown', 'Gấu nâu mặc áo đỏ', null, null, array['pet_or_toy']::text[], 'Manh mối', 'npc');
insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('camp-04', 'summer_camp', 4, 'Đêm Sao Và Lửa Trại Kể Chuyện', 'Video lều phát sáng ban đêm, lửa trại khói bốc; file: nhóm lửa trại.', 'Đêm thứ ba của trại là đêm Lửa Trại Lớn, và nhà thiên văn Dr. Stella mang kính thiên văn đến trại. Nhưng để lửa trại bùng lên, mỗi Đội Lều phải góp củi, treo đèn lồng và dựng ghế dài quanh bếp. Dr. Stella giấu bản đồ sao thành năm mảnh, mỗi mảnh nằm ở một góc trại và chỉ hiện ra khi đèn lồng sáng. Ghép đủ bản đồ, cả trại sẽ tìm được chòm sao Thuyền Câu và nghe câu chuyện cổ về nó. Đêm khép lại bằng món kẹo dẻo nướng và bài hát chung của trại.', 6, 5, 30, 12, true, 'Trại bên hồ về đêm, trời đầy sao, lều phát sáng ấm áp, đèn lồng treo dọc lối đi. Mặt hồ phản chiếu ánh trăng, tiếng dế kêu. Nhà trên cây treo đèn lồng, lối lát đá dẫn tới vòng ghế quanh lửa.', '[{"n": 1, "title": "Thắp đèn lồng", "minutes": 5, "optional": false, "goal": "Treo và thắp đèn lồng dọc lối đi.", "beats": ["Mỗi đèn sáng làm lộ một góc trại.", "Lều phát sáng dần lên.", "Đèn lồng được treo lên nhà trên cây: mỗi câu đúng thắp một ngọn."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên từng chiếc đèn lồng.", "reward": "Lối đi sáng.", "vocab": ["lantern", "light", "dark", "night", "tree house"], "assets": ["camp_lantern", "camp_string_lights", "camp_tent_stage", "hdri_night", "tree_fort"]}, {"n": 2, "title": "Góp củi lửa trại lớn", "minutes": 5, "optional": false, "goal": "Mỗi Đội Lều góp một bó củi cho bếp lớn.", "beats": ["Đống củi cao dần theo số câu đúng của cả trại."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Đống lửa trại lớn.", "vocab": ["wood", "pile", "big", "share"], "assets": ["river_woodpile", "river_firewood", "camp_firepit"]}, {"n": 3, "title": "Ghế dài quanh lửa", "minutes": 5, "optional": false, "goal": "Khiêng ghế, xếp vòng tròn quanh bếp.", "beats": ["Ghế xếp đúng vòng = chỗ ngồi cho cả lớp.", "Lối lát đá dẫn tới ghế dài: xếp ghế theo đúng thứ tự câu chuyện."], "question_hook": "Câu nối cặp (matching) gắn ghế vào đúng chỗ. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Vòng ghế quanh lửa.", "vocab": ["bench", "circle", "sit", "around", "path"], "assets": ["camp_bench", "camp_chair", "ground_cobble_path_a"]}, {"n": 4, "title": "Năm mảnh bản đồ sao", "minutes": 5, "optional": false, "goal": "Tìm 5 mảnh bản đồ sao giấu ở các góc trại.", "beats": ["Mảnh chỉ hiện khi đèn gần đó đã sáng.", "Mỗi mảnh = một câu hỏi."], "question_hook": "Câu đọc hiểu ngắn về sao và bầu trời. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Bản đồ sao hoàn chỉnh.", "vocab": ["star", "map", "piece", "sky"], "assets": ["surv_map", "camp_lantern", "river_stump"]}, {"n": 5, "title": "Chòm sao Thuyền Câu", "minutes": 5, "optional": false, "goal": "Ghép bản đồ, tìm chòm sao trên trời qua kính thiên văn.", "beats": ["Dr. Stella kể câu chuyện cổ về ông lão câu cá trên trời.", "Câu đúng nối thêm một ngôi sao."], "question_hook": "Câu sắp xếp câu chuyện (reorder). Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Câu chuyện chòm sao.", "vocab": ["constellation", "shine", "story", "telescope"], "assets": ["hdri_night", "camp_table"]}, {"n": 6, "title": "Lửa trại bùng lên", "minutes": 5, "optional": false, "goal": "Thắp lửa trại lớn, hát bài ca trại.", "beats": ["Lửa bùng lên cao, tia lửa bay lên trời sao.", "Cờ Đội Lều giỏi nhất cắm cạnh lửa.", "Cậu bé lang thang kể chuyện bên lửa: cả trại lặp lại câu cuối cho đúng."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Danh hiệu \"Đêm Sao Rực Rỡ\".", "vocab": ["campfire", "sing", "together", "happy", "storyteller"], "assets": ["camp_firepit", "fx_fire", "fx_spark", "anim_cheer", "char_nomad_boy"]}, {"n": 7, "title": "Chặng phụ: Kẹo dẻo", "minutes": 5, "optional": true, "goal": "Kéo dài: nướng kẹo dẻo quanh lửa.", "beats": ["Kẹo phồng theo câu đúng."], "question_hook": "Câu hỏi hiện ngay trên vật thể phát sáng như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["marshmallow", "toast"], "assets": ["camp_marshmallow_stick"]}, {"n": 8, "title": "Chặng phụ: Điều ước sao băng", "minutes": 5, "optional": true, "goal": "Viết một điều ước tiếng Anh.", "beats": ["Điều ước bay lên thành sao băng."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng gỗ của trại. Câu viết ngắn, không tính thua.", "reward": "Huy hiệu \"Người Ngắm Sao\".", "vocab": ["wish", "dream", "future"], "assets": ["hdri_night"]}]'::jsonb, '{"sizes": {"1-5": "Một Đội Lều chung; mỗi em làm lần lượt các trạm, máy chủ giao thêm việc cho người làm nhanh.", "6-20": "2-4 Đội Lều (4-5 em/đội), mỗi đội một lều riêng và một lá cờ màu. Các đội cùng lấp đầy Bảng Nhiệm vụ trại chung.", "21-50": "8-10 Đội Lều (5 em/đội). Trại chia 2 bãi cạnh nhau để không quá đông; mỗi trạm (bếp, lều, nước, củi) nhận tối đa 2 đội cùng lúc, xoay vòng mỗi 5 phút."}, "roles": ["Đội trưởng Lều (giữ Bảng Nhiệm vụ)", "Thợ dựng lều", "Người giữ lửa", "Đầu bếp", "Thủ kho (công cụ mở khóa)"], "scoring": "Mỗi hành động xong = 1-3 sao theo độ chính xác và tốc độ. Bảng Nhiệm vụ trại chung là thanh \"Boss\" của trận: cả lớp cùng lấp đầy. Đội Lều nhiều sao nhất được cắm cờ trên đỉnh trại.", "avatars": "12 nhân vật dưới đây là người hướng dẫn và bạn trại trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo và đeo khăn màu Đội Lều.", "safety": "Lửa, dao, rìu chỉ dùng qua hoạt ảnh có người lớn hướng dẫn; nhân vật luôn đeo găng khi nướng."}'::jsonb, array['anim_cheer','camp_bench','camp_chair','camp_firepit','camp_lantern','camp_marshmallow_stick','camp_string_lights','camp_table','camp_tent_stage','char_nomad_boy','fx_fire','fx_spark','ground_cobble_path_a','hdri_night','river_firewood','river_stump','river_woodpile','surv_map','tree_fort']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
