insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('camp-05', 'summer_camp', 5, 'Chuyến Dã Ngoại Thượng Nguồn', 'File: bối cảnh sông núi picnic, tìm thức ăn, lọc nước; video cầu gỗ ra hồ và rừng thông.', 'Cả trại khởi hành từ bến gỗ để lên bãi cắm trại mới ở thượng nguồn, nơi nghe nói có hồ nước trong nhất vùng. Hướng dẫn viên Leo đưa cho mỗi Đội Lều một bản đồ, một la bàn và một ba lô trống cần chuẩn bị đúng đồ. Trên đường, cầu gỗ cũ bị gãy một tấm ván, phải sửa mới qua được; rồi đến khúc sông cần lấy nước lọc để uống. Đến nơi, cả trại dựng lều mới, nhóm bếp, và nấu bữa trưa từ những gì hái được trên đường. Phần thưởng cuối cùng là chuyến chèo thuyền nhỏ ngắm hồ trên núi lúc hoàng hôn.', 6, 5, 30, 12, true, 'Đường mòn men theo sông lên thượng nguồn: cầu gỗ, rừng thông, thác nhỏ, và một bãi cỏ phẳng bên hồ trên núi. Trời trong, nắng nhẹ, mây trắng trôi chậm. Bản đồ nổi của thung lũng sông đặt trên bàn đá ở điểm xuất phát; trên đường có thác nhỏ đổ xuống hồ.', '[{"n": 1, "title": "Soạn ba lô", "minutes": 5, "optional": false, "goal": "Chọn đúng đồ cho chuyến đi (nước, áo mưa, đèn pin, hộp cứu thương).", "beats": ["Ba lô có giới hạn cân nặng: đồ thừa làm đi chậm.", "Chị dẫn đường kiểm ba lô của từng bạn trước khi lên đường.", "Cô hướng đạo kiểm tra danh sách đồ mang: nhận đúng tên từng món."], "question_hook": "Câu chọn đồ (trắc nghiệm, nối cặp đồ - công dụng). Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Ba lô chuẩn.", "vocab": ["pack", "need", "heavy", "light", "hiker", "backpack", "guide", "map"], "assets": ["camp_backpack", "camp_firstaid", "surv_flashlight", "camp_bottle", "river_dock", "char_hiker_girl", "char_female_a"]}, {"n": 2, "title": "Bản đồ và la bàn", "minutes": 5, "optional": false, "goal": "Đọc bản đồ, chọn đúng ngã rẽ.", "beats": ["Ba ngã rẽ, mỗi ngã có biển chỉ đường.", "Đi sai thì vòng lại 30 giây.", "Bản đồ nổi của thung lũng: ghim đúng tên nơi cần đến, kim la bàn sẽ xoay theo."], "question_hook": "Câu hướng đi (north, left, across...). Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Đường tắt.", "vocab": ["map", "compass", "north", "turn", "relief map", "valley"], "assets": ["surv_map", "surv_compass", "river_sign", "river_tree_pine", "mini_ganga_valley"]}, {"n": 3, "title": "Sửa cầu gỗ", "minutes": 5, "optional": false, "goal": "Thay tấm ván gãy để cả trại qua suối.", "beats": ["Mỗi câu đúng đóng một đinh.", "Cầu lắc nhẹ khi đông người."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên tấm ván.", "reward": "Cầu qua suối.", "vocab": ["bridge", "board", "fix", "cross"], "assets": ["river_bridge", "camp_axe", "river_log_fallen"]}, {"n": 4, "title": "Nước thượng nguồn", "minutes": 5, "optional": false, "goal": "Lấy nước sông, lọc và đun.", "beats": ["Nước thượng nguồn trong nhưng vẫn phải lọc.", "Nước thượng nguồn chảy từ thác nhỏ: lọc xong mới được uống."], "question_hook": "Câu sắp xếp các bước lọc. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Bình nước đầy.", "vocab": ["river", "filter", "boil", "safe", "waterfall", "spring water"], "assets": ["camp_water_filter", "camp_bucket", "river_rock_medium", "river_waterfall_pool"]}, {"n": 5, "title": "Dựng trại mới", "minutes": 5, "optional": false, "goal": "Dựng lều và bếp ở bãi cỏ bên hồ trên núi.", "beats": ["Lều 3 giai đoạn như ngày đầu nhưng nhanh hơn.", "Hái nấm và quả an toàn (có biển nhận biết)."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Trại mới + bữa trưa.", "vocab": ["new", "lake", "pick", "lunch"], "assets": ["camp_tent_stage", "camp_firepit", "camp_pan", "food_apple", "food_bread"]}, {"n": 6, "title": "Chèo thuyền hoàng hôn", "minutes": 5, "optional": false, "goal": "Chèo thuyền nhỏ ngắm hồ trên núi.", "beats": ["Mỗi câu đúng một nhịp chèo; cả đội chèo đồng đều thì thuyền đi thẳng.", "Chuyến chèo thuyền hoàng hôn dùng thuyền chèo gỗ trắng của bến hồ."], "question_hook": "Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.", "reward": "Danh hiệu \"Nhà Thám Hiểm Thượng Nguồn\".", "vocab": ["row", "paddle", "sunset", "beautiful", "rowboat"], "assets": ["river_boat_row", "river_dock", "hdri_sunset", "river_duck"]}, {"n": 7, "title": "Chặng phụ: Câu cá bên hồ", "minutes": 5, "optional": true, "goal": "Kéo dài: câu vài con cá cho bữa tối.", "beats": ["Mỗi câu đúng một lần giật cần."], "question_hook": "Câu hỏi hiện ngay trên vật thể phát sáng như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["fish", "catch"], "assets": ["fish_rod", "fish_bobber"]}, {"n": 8, "title": "Chặng phụ: Bưu thiếp", "minutes": 5, "optional": true, "goal": "Viết bưu thiếp tiếng Anh gửi gia đình.", "beats": ["Bưu thiếp có ảnh hồ trên núi."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng gỗ của trại. Câu viết ngắn, không tính thua.", "reward": "Huy hiệu \"Lữ Khách Nhí\".", "vocab": ["dear", "miss you", "see you"], "assets": ["river_sign"]}]'::jsonb, '{"sizes": {"1-5": "Một Đội Lều chung; mỗi em làm lần lượt các trạm, máy chủ giao thêm việc cho người làm nhanh.", "6-20": "2-4 Đội Lều (4-5 em/đội), mỗi đội một lều riêng và một lá cờ màu. Các đội cùng lấp đầy Bảng Nhiệm vụ trại chung.", "21-50": "8-10 Đội Lều (5 em/đội). Trại chia 2 bãi cạnh nhau để không quá đông; mỗi trạm (bếp, lều, nước, củi) nhận tối đa 2 đội cùng lúc, xoay vòng mỗi 5 phút."}, "roles": ["Đội trưởng Lều (giữ Bảng Nhiệm vụ)", "Thợ dựng lều", "Người giữ lửa", "Đầu bếp", "Thủ kho (công cụ mở khóa)"], "scoring": "Mỗi hành động xong = 1-3 sao theo độ chính xác và tốc độ. Bảng Nhiệm vụ trại chung là thanh \"Boss\" của trận: cả lớp cùng lấp đầy. Đội Lều nhiều sao nhất được cắm cờ trên đỉnh trại.", "avatars": "12 nhân vật dưới đây là người hướng dẫn và bạn trại trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo và đeo khăn màu Đội Lều.", "safety": "Lửa, dao, rìu chỉ dùng qua hoạt ảnh có người lớn hướng dẫn; nhân vật luôn đeo găng khi nướng.", "note": "Đường mòn chia 3 làn song song cho lớp đông; các Đội Lều xuất phát cách nhau 20 giây."}'::jsonb, array['camp_axe','camp_backpack','camp_bottle','camp_bucket','camp_firepit','camp_firstaid','camp_pan','camp_tent_stage','camp_water_filter','char_female_a','char_hiker_girl','fish_bobber','fish_rod','food_apple','food_bread','hdri_sunset','mini_ganga_valley','river_boat_row','river_bridge','river_dock','river_duck','river_log_fallen','river_rock_medium','river_sign','river_tree_pine','river_waterfall_pool','surv_compass','surv_flashlight','surv_map']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
