insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('camp-05#12', 'camp-05', 12, 'Dê Núi Bạc', 'Dê núi đứng trên đá, kêu khi đi sai đường', 'child', 'n', 'S4', false, 'E_amber', 'black', 'bob', 'short', false, false, 'casual', 'white', 'Lông trắng, sừng cong', null, null, array['pet_or_toy']::text[], 'Linh vật đường mòn', 'npc');
insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('fish-01', 'river_fishing', 1, 'Bình Minh Trên Hồ Ngọc', 'Video đứng trên thuyền nhôm câu cá giữa hồ xanh ngọc, nước trong nhìn thấy đáy; file mục II.2.', 'Sáng sớm, bác Năm ngư dân dẫn cả lớp ra bến gỗ, chia mỗi nhóm một thuyền nhôm nhỏ và một cây cần gỗ cũ. Bác kể rằng hồ Ngọc có sáu loài cá thường gặp và một truyền thuyết: Cá Hồi Hoàng Gia chỉ ngoi lên khi mặt trời vừa ló khỏi đỉnh núi. Các thuyền phải học cách quăng cần, chờ phao chìm và giữ thanh căng dây, rồi điền vào Sổ Câu Cá đủ các loài cá của hồ. Câu đúng giúp nâng cần, đổi mồi, và cá lớn sẽ tìm đến. Khi ánh nắng đầu tiên chạm mặt hồ, thuyền nào có cần vàng sẽ có cơ hội gặp Cá Hồi Hoàng Gia.', 6, 5, 30, 12, true, 'Hồ xanh ngọc dưới chân núi lúc bình minh, sương mỏng trên mặt nước, rừng thông soi bóng. Mặt hồ phẳng lặng, nhìn thấy đá cuội và đàn cá nhỏ dưới đáy. Bên cạnh thuyền nhôm là một chiếc thuyền chèo trắng có lưới vàng và phao cứu sinh treo cạnh bến.', '[{"n": 1, "title": "Ra bến, lên thuyền", "minutes": 5, "optional": false, "goal": "Nhận thuyền, áo phao, cần gỗ; chèo ra giữa hồ.", "beats": ["Bác Năm dạy 3 bước: quăng, chờ, kéo.", "Mỗi câu đúng là một nhịp chèo ra vị trí neo.", "Bác Năm chỉ chiếc thuyền chèo cũ của ông: mỗi món trên thuyền đọc đúng tên được một mồi giun.", "Cần câu gỗ cấp một của bác Năm: cầm đúng tay mới quăng được.", "Giá gác cần và ghế gấp trên thuyền: gọi đúng tên đồ nghề để ngồi vào chỗ."], "question_hook": "Câu hỏi trên mái chèo; câu đúng đưa thuyền ra khu cá nhiều hơn.", "reward": "Cần gỗ + mồi giun.", "vocab": ["boat", "paddle", "life jacket", "rod", "rowboat", "net", "lifebuoy", "wooden rod", "beginner", "rod holder", "boat chair"], "assets": ["river_dock", "river_boat_aluminium", "kayak_lifejacket", "fish_rod", "fish_bait", "hdri_dawn", "river_boat_row", "river_buoy", "fish_rod_wood", "fish_rod_holder", "fish_boat_chair"]}, {"n": 2, "title": "Cú quăng đầu tiên", "minutes": 5, "optional": false, "goal": "Học quăng cần bằng Thanh lực quăng, bắt con cá đầu tiên.", "beats": ["Thanh lực quăng: dừng đúng vùng xanh để phao rơi xa.", "Cá rô phi và cá rô đồng cắn câu nhiều."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Cá đầu tiên vào Sổ Câu Cá.", "vocab": ["cast", "float", "bite", "pull"], "assets": ["fish_bobber", "fish_reel", "fish_hook", "fish_tilapia", "fish_climbing_perch", "anim_cast"]}, {"n": 3, "title": "Đổi mồi, đổi chỗ", "minutes": 5, "optional": false, "goal": "Thử mồi tôm và mồi cá nhỏ để bắt cá chép, cá diếc.", "beats": ["Mồi khác nhau gọi loài khác nhau.", "Sau 3 câu đúng: nâng cần sợi thủy tinh."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Cần sợi thủy tinh.", "vocab": ["bait", "worm", "shrimp", "change"], "assets": ["fish_bait", "fish_carp", "fish_crucian", "fish_tackle_box"]}, {"n": 4, "title": "Khúc sâu gần bãi đá", "minutes": 5, "optional": false, "goal": "Neo thuyền gần bãi đá, săn cá trắm và cá lóc.", "beats": ["Cá lớn kéo mạnh, thanh căng dây rung nhiều.", "Vợt cần người thứ hai trên thuyền trả lời đúng."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Cá to cần 2 câu đúng liên tiếp.", "reward": "Vợt + cần carbon.", "vocab": ["deep", "strong", "net", "heavy"], "assets": ["fish_grass_carp", "fish_snakehead", "fish_net", "river_rock_large"]}, {"n": 5, "title": "Cân và ghi kỷ lục", "minutes": 5, "optional": false, "goal": "Về bến cân cá, ghi Sổ Câu Cá, thả cá lại hồ.", "beats": ["Bảng kỷ lục xếp hạng theo điểm.", "Câu đúng mở khóa \"sự thật về loài cá\".", "Cá được bỏ vào giỏ đan trước khi cân.", "Cá tuyết nhỏ nằm trong thùng cá trước khi cân: đọc tên cá trên nhãn thùng."], "question_hook": "Câu hỏi hiện trên bảng cân; đúng thì cân chính xác và cộng điểm thưởng.", "reward": "Cần vàng cho 3 thuyền dẫn đầu và mọi em đủ 9 câu đúng.", "vocab": ["weigh", "record", "release", "kilogram", "basket", "cod", "fish box"], "assets": ["fish_scale", "fish_record_board", "fish_bucket", "river_dock", "fish_basket", "fish_cod", "fish_box"]}, {"n": 6, "title": "Mặt trời ló núi", "minutes": 5, "optional": false, "goal": "Cơ hội gặp Cá Hồi Hoàng Gia cho ai có cần vàng.", "beats": ["Nắng đầu tiên chạm mặt hồ, cá hồi lấp lánh bên dưới.", "Cá Cực hiếm cần 3 câu đúng liên tiếp, câu cuối khó nhất."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Danh hiệu \"Ngư Phủ Bình Minh\"; người bắt cá to nhất là MVP.", "vocab": ["sunrise", "legend", "rare", "shine"], "assets": ["fish_king_salmon", "fish_rod", "hdri_noon", "anim_pull_fish", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Cá trê dưới bến", "minutes": 5, "optional": true, "goal": "Kéo dài: câu cá trê lẩn dưới bến gỗ.", "beats": ["Cá trê chỉ cắn mồi giun sát đáy."], "question_hook": "Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["catfish", "under", "bottom"], "assets": ["fish_walking_catfish", "river_dock"]}, {"n": 8, "title": "Chặng phụ: Sổ tay loài cá", "minutes": 5, "optional": true, "goal": "Viết một câu mô tả mỗi loài cá đã bắt.", "beats": ["Sổ tay in ra gửi phụ huynh."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết ngắn, không tính thua.", "reward": "Huy hiệu \"Nhà Sinh Vật Nhí\".", "vocab": ["scale", "fin", "color", "long"], "assets": ["fish_record_board"]}]'::jsonb, '{"sizes": {"1-5": "Một thuyền nhôm chung (2-4 người) hoặc mỗi em một thuyền nhỏ cạnh bến; bảng kỷ lục cá nhân.", "6-20": "Thuyền 3-4 người, mỗi em một cần riêng. 2-5 thuyền neo ở 2 khúc sông; bảng kỷ lục theo thuyền và cá nhân.", "21-50": "Thuyền 4 người (50 em = 13 thuyền) rải trên 3 khúc sông: bến gỗ, giữa hồ, chân thác. Mỗi khúc sông tối đa 5 thuyền để không chật màn hình; ai cũng thấy bảng kỷ lục chung."}, "roles": ["Thuyền trưởng (chọn chỗ neo)", "Thợ câu", "Người giữ vợt", "Người ghi kỷ lục"], "rules": {"score": "Điểm một con cá = cân nặng (kg) × 100 × hệ số độ hiếm (Thường 1, Khá 1,5, Hiếm 2,5, Cực hiếm 5). Trả lời nhanh cộng tới 20% điểm.", "upgrade": "Mỗi 3 câu đúng: nâng một cấp cần (gỗ → sợi thủy tinh → carbon → vàng) hoặc chọn mồi mới. Cần cấp cao kéo nhanh hơn và giữ được cá to.", "rarity": "Câu khó hơn (bậc cao hơn trong 5 bậc của gia sư) có tỉ lệ ra cá hiếm cao hơn. Cá Cực hiếm chỉ cắn khi đã có cần vàng.", "release": "Cá được thả lại sông sau khi cân và chụp ảnh (thông điệp bảo vệ thiên nhiên)."}, "avatars": "Mỗi học sinh đứng trên thuyền bằng nhân vật riêng ghép từ hồ sơ diện mạo, mặc áo phao màu thuyền. 12 nhân vật dưới đây là người dẫn chuyện và bạn câu trong phim.", "safety": "Mọi nhân vật luôn mặc áo phao trên thuyền."}'::jsonb, array['anim_cast','anim_cheer','anim_pull_fish','fish_bait','fish_basket','fish_boat_chair','fish_bobber','fish_box','fish_bucket','fish_carp','fish_climbing_perch','fish_cod','fish_crucian','fish_grass_carp','fish_hook','fish_king_salmon','fish_net','fish_record_board','fish_reel','fish_rod','fish_rod_holder','fish_rod_wood','fish_scale','fish_snakehead','fish_tackle_box','fish_tilapia','fish_walking_catfish','hdri_dawn','hdri_noon','kayak_lifejacket','river_boat_aluminium','river_boat_row','river_buoy','river_dock','river_rock_large']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
