insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('fish-01#12', 'fish-01', 12, 'Vịt Xám', 'Bơi theo thuyền, kêu khi cá cắn câu', 'child', 'n', 'S5', false, 'E_black', 'dark_brown', 'curly', 'shoulder', false, false, 'casual', 'gray', 'Lông xám', null, null, array['pet_or_toy']::text[], 'Linh vật hồ', 'npc');
insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('fish-02', 'river_fishing', 2, 'Giải Câu Cá Mùa Hè Bến Gỗ', 'Video bến cầu gỗ đưa ra nước; file: tính điểm theo kích thước và độ hiếm.', 'Trại tổ chức Giải Câu Cá Mùa Hè, phát thanh viên vui tính Bé Bự bình luận trực tiếp qua loa. Mỗi thuyền có 30 phút qua ba vòng: vòng loại ở bến, vòng bán kết giữa sông, vòng chung kết ở khúc sâu. Luật giải rất rõ: điểm theo cân nặng và độ hiếm, thả cá lại sau khi cân, và thuyền nào câu được loài mới sẽ có điểm thưởng. Giữa giải, đội vô địch năm ngoái của Captain Ray tuyên bố sẽ bảo vệ ngôi vương. Chung kết là cuộc săn cá lăng, loài cá hiếm của khúc sông sâu, và ai bắt được sẽ được khắc tên lên cúp gỗ.', 6, 5, 30, 12, true, 'Bến gỗ dài đưa ra sông, cờ giải đấu tung bay, bảng điểm lớn trên bờ, khán giả cổ vũ. Nắng sáng rực rỡ, nước sông xanh trong, gió nhẹ. Phao cứu sinh ngăn làn thi và thuyền chèo của ban tổ chức neo cạnh bến. Năm cần câu thi đấu bày trên giá ở bến, người dẫn chương trình chờ khai mạc.', '[{"n": 1, "title": "Khai mạc", "minutes": 5, "optional": false, "goal": "Đăng ký thuyền, nhận số áo, chọn cần và mồi xuất phát.", "beats": ["Bé Bự giới thiệu từng thuyền.", "Mỗi câu đúng chọn thêm một món đồ nghề.", "Năm cần câu thi đấu bày ra, mỗi đội bốc thăm một cần: nối đúng tên bộ phận trên cần để chọn."], "question_hook": "Câu hỏi trên bảng đăng ký.", "reward": "Bộ đồ nghề xuất phát.", "vocab": ["contest", "team", "start", "number", "rod", "lucky draw"], "assets": ["river_dock", "river_sign", "fish_tackle_box", "fish_rod", "camp_bunting", "rod_cand_1", "rod_cand_2", "rod_cand_3", "rod_cand_4", "rod_cand_5", "char_female_b"]}, {"n": 2, "title": "Vòng loại ở bến", "minutes": 5, "optional": false, "goal": "Câu cá thường ở bến, đạt 300 điểm để vào vòng sau.", "beats": ["Cá rô phi, cá chép, cá diếc nhiều.", "Bảng điểm cập nhật trực tiếp.", "Phao ngăn làn: thuyền nào vượt phao khi chưa trả lời đúng bị trừ điểm.", "Cá rô biển ở vòng loại cắn mồi: đọc đúng tên mồi để quăng trúng.", "Bến nổi trên thùng phuy xanh là nơi xếp hàng vòng loại: đọc đúng luật thi trước khi bước lên."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Vé bán kết.", "vocab": ["qualify", "points", "score", "catch", "lane", "lifebuoy", "bass", "qualifying", "floating dock", "rope"], "assets": ["fish_tilapia", "fish_carp", "fish_crucian", "fish_record_board", "river_buoy", "fish_bass", "fish_floating_dock"]}, {"n": 3, "title": "Bán kết giữa sông", "minutes": 5, "optional": false, "goal": "Chèo ra giữa sông, săn cá basa và cá tra.", "beats": ["Dòng chảy đẩy thuyền: câu đúng giữ thuyền đứng yên.", "Nâng cần sợi thủy tinh sau 3 câu đúng.", "Thuyền trọng tài đi giữa sông chấm cá bán kết.", "Cá mè bạc xuất hiện ở bán kết: nhìn màu vảy để đoán đúng tên.", "Cần sợi thủy tinh của vòng bán kết: mỗi câu đúng giúp đổi đúng mồi."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Cần sợi thủy tinh, vé chung kết.", "vocab": ["current", "middle", "basa", "steady", "referee boat", "net", "silver carp", "semi-final", "fiberglass rod", "reel"], "assets": ["fish_basa", "fish_tra", "river_boat_aluminium", "river_buoy", "river_boat_row", "fish_silver_carp", "fish_rod_fiberglass"]}, {"n": 4, "title": "Thách đấu Captain Ray", "minutes": 5, "optional": false, "goal": "Đối đầu trực tiếp với thuyền vô địch năm ngoái (thuyền máy điều khiển).", "beats": ["Ai bắt nhiều điểm hơn trong 5 phút thắng.", "Captain Ray câu nhanh theo mức độ khó của lớp.", "Captain Ray thách bằng cần carbon đen: đọc đúng các bộ phận của cần để nhận thách đấu."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Mỗi câu đúng trước Captain Ray cướp được một con cá khỏi lưỡi của ông.", "reward": "Cần carbon.", "vocab": ["challenge", "faster", "beat", "champion", "carbon rod"], "assets": ["fish_snakehead", "fish_rainbow_trout", "river_boat_aluminium", "fish_rod_carbon"]}, {"n": 5, "title": "Chung kết khúc sâu", "minutes": 5, "optional": false, "goal": "Săn cá lăng ở khúc sông sâu.", "beats": ["Cá lăng hiếm, kéo rất mạnh.", "Cả thuyền cùng trả lời để giữ dây.", "Cá chung kết được đặt trong giỏ đan trước bảng điểm."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Cá hiếm cần 2 câu đúng liên tiếp.", "reward": "Cá lăng vào bảng kỷ lục.", "vocab": ["final", "rare", "deep", "hold", "basket", "record"], "assets": ["fish_hemibagrus", "fish_net", "fish_rod", "anim_pull_fish", "fish_basket"]}, {"n": 6, "title": "Lễ trao cúp", "minutes": 5, "optional": false, "goal": "Cân cá cuối, công bố thuyền vô địch và MVP.", "beats": ["Tên người thắng khắc lên cúp gỗ.", "Cá được thả lại sông.", "Chiếc cần vàng là phần thưởng của nhà vô địch, đặt cạnh chiếc cúp."], "question_hook": "Câu hỏi trên bục trao giải (phỏng vấn ngắn).", "reward": "Cúp gỗ + danh hiệu \"Vua Bến Gỗ\".", "vocab": ["winner", "trophy", "congratulations", "release", "gold rod"], "assets": ["fish_scale", "fish_record_board", "river_dock", "anim_cheer", "fish_rod_gold"]}, {"n": 7, "title": "Chặng phụ: Giải phụ cá nhỏ nhất", "minutes": 5, "optional": true, "goal": "Kéo dài: giải vui cho con cá nhỏ nhất.", "beats": ["Cá nhỏ nhất cũng được thưởng."], "question_hook": "Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["small", "tiny", "funny"], "assets": ["fish_climbing_perch"]}, {"n": 8, "title": "Chặng phụ: Phỏng vấn nhà vô địch", "minutes": 5, "optional": true, "goal": "Mỗi thuyền trả lời phỏng vấn tiếng Anh của Bé Bự.", "beats": ["Câu trả lời hay phát lại trên loa."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu nói/viết ngắn, không tính thua.", "reward": "Huy hiệu \"Ngôi Sao Giải Đấu\".", "vocab": ["proud", "teamwork", "next year"], "assets": ["river_sign"]}]'::jsonb, '{"sizes": {"1-5": "Một thuyền nhôm chung (2-4 người) hoặc mỗi em một thuyền nhỏ cạnh bến; bảng kỷ lục cá nhân.", "6-20": "Thuyền 3-4 người, mỗi em một cần riêng. 2-5 thuyền neo ở 2 khúc sông; bảng kỷ lục theo thuyền và cá nhân.", "21-50": "Thuyền 4 người (50 em = 13 thuyền) rải trên 3 khúc sông: bến gỗ, giữa hồ, chân thác. Mỗi khúc sông tối đa 5 thuyền để không chật màn hình; ai cũng thấy bảng kỷ lục chung."}, "roles": ["Thuyền trưởng (chọn chỗ neo)", "Thợ câu", "Người giữ vợt", "Người ghi kỷ lục"], "rules": {"score": "Điểm một con cá = cân nặng (kg) × 100 × hệ số độ hiếm (Thường 1, Khá 1,5, Hiếm 2,5, Cực hiếm 5). Trả lời nhanh cộng tới 20% điểm.", "upgrade": "Mỗi 3 câu đúng: nâng một cấp cần (gỗ → sợi thủy tinh → carbon → vàng) hoặc chọn mồi mới. Cần cấp cao kéo nhanh hơn và giữ được cá to.", "rarity": "Câu khó hơn (bậc cao hơn trong 5 bậc của gia sư) có tỉ lệ ra cá hiếm cao hơn. Cá Cực hiếm chỉ cắn khi đã có cần vàng.", "release": "Cá được thả lại sông sau khi cân và chụp ảnh (thông điệp bảo vệ thiên nhiên)."}, "avatars": "Mỗi học sinh đứng trên thuyền bằng nhân vật riêng ghép từ hồ sơ diện mạo, mặc áo phao màu thuyền. 12 nhân vật dưới đây là người dẫn chuyện và bạn câu trong phim.", "safety": "Mọi nhân vật luôn mặc áo phao trên thuyền.", "note": "Captain Ray là thuyền máy do máy chủ điều khiển, độ khó theo bậc của lớp."}'::jsonb, array['anim_cheer','anim_pull_fish','camp_bunting','char_female_b','fish_basa','fish_basket','fish_bass','fish_carp','fish_climbing_perch','fish_crucian','fish_floating_dock','fish_hemibagrus','fish_net','fish_rainbow_trout','fish_record_board','fish_rod','fish_rod_carbon','fish_rod_fiberglass','fish_rod_gold','fish_scale','fish_silver_carp','fish_snakehead','fish_tackle_box','fish_tilapia','fish_tra','river_boat_aluminium','river_boat_row','river_buoy','river_dock','river_sign','rod_cand_1','rod_cand_2','rod_cand_3','rod_cand_4','rod_cand_5']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
