insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('fish-03', 'river_fishing', 3, 'Chân Thác Và Cá Lăng Sông Sâu', 'File: đoạn sông ngọc chảy qua chân núi; video nước trong và vách đá.', 'Thầy Quang, huấn luyện viên câu cá thể thao, đưa nhóm câu giỏi nhất trại lên chân thác lớn. Ở đây nước chảy mạnh, cá khỏe, chỉ người giữ được thanh căng dây thật vững mới thắng được. Thầy giao một thử thách: bắt đủ ba loài cá sông sâu (cá lăng, cá nheo, cá chình) để được vào "Câu lạc bộ Chân Thác". Nhưng dòng nước thay đổi theo giờ, và thuyền phải di chuyển giữa ba vũng nước khác nhau theo bản đồ dòng chảy. Cuối buổi, cả nhóm sẽ thả một con cá lăng thật lớn trở lại vũng sâu, như lời hứa giữ gìn dòng sông.', 6, 5, 30, 12, true, 'Khúc sông dưới chân thác lớn, nước xoáy trắng bọt rồi chảy chậm thành vùng sâu xanh thẫm. Vách đá cao hai bên, chim én bay quanh thác, bụi nước lấp lánh. Thung lũng sông nhìn từ trên cao làm bản đồ dòng chảy; thác cao đổ xuống vũng xanh, bọt trắng nổi đầy.', '[{"n": 1, "title": "Bản đồ dòng chảy", "minutes": 5, "optional": false, "goal": "Đọc bản đồ dòng chảy, chọn vũng nước đầu tiên.", "beats": ["Ba vũng: Vũng Bọt, Vũng Xanh, Vũng Đá.", "Chọn sai thì nước xoáy đẩy thuyền ra.", "Bản đồ nổi của thung lũng sông: ghim ba vũng cá vào đúng chỗ."], "question_hook": "Câu hỏi trên bản đồ dòng chảy.", "reward": "Vị trí neo an toàn.", "vocab": ["current", "fast", "slow", "pool", "map", "waterfall"], "assets": ["surv_map", "river_boat_aluminium", "water_foam", "river_cliff", "mini_ganga_valley", "river_waterfall"]}, {"n": 2, "title": "Neo thuyền trong nước xiết", "minutes": 5, "optional": false, "goal": "Thả neo và giữ thuyền ổn định.", "beats": ["Thanh cân bằng thuyền: câu đúng giữ thuyền không xoay.", "Chân thác nước xiết: thả neo đúng chỗ thì thuyền không trôi."], "question_hook": "Câu hỏi trên sợi dây neo; đúng thì neo bám đá.", "reward": "Thuyền đứng vững.", "vocab": ["anchor", "stay", "balance", "rope", "rapids"], "assets": ["camp_rope", "river_rock_large", "river_buoy", "river_waterfall_pool"]}, {"n": 3, "title": "Vũng Bọt: cá nheo", "minutes": 5, "optional": false, "goal": "Câu cá nheo trong vũng nước trắng bọt.", "beats": ["Cá nheo kéo ngang, thanh căng dây lắc trái phải.", "Vũng Bọt: bong bóng nổi lên là dấu cá nheo ở dưới."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Cá nheo + cần carbon.", "vocab": ["pull", "side", "strong", "whiskers", "foam", "bubble"], "assets": ["fish_sheatfish", "fish_rod", "anim_pull_fish", "fx_bubbles"]}, {"n": 4, "title": "Vũng Xanh: cá lăng", "minutes": 5, "optional": false, "goal": "Câu cá lăng trong vùng sâu xanh thẫm.", "beats": ["Cá lăng hiếm, cần 2 câu đúng liên tiếp.", "Cá lăng nhiều màu chỉ ngoi lên ở Vũng Xanh."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Cá lăng.", "vocab": ["deep", "patient", "rare", "wait", "hemibagrus", "deep pool"], "assets": ["fish_hemibagrus", "fish_bait", "water_normal"]}, {"n": 5, "title": "Vũng Đá: cá chình", "minutes": 5, "optional": false, "goal": "Câu cá chình ẩn trong khe đá.", "beats": ["Cá chình chui vào khe: phải kéo đúng lúc."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Câu dạng sắp xếp: xếp đúng các bước kéo cá ra khỏi khe.", "reward": "Cá chình.", "vocab": ["eel", "hide", "rock", "slippery"], "assets": ["fish_eel", "river_rock_medium", "fish_net"]}, {"n": 6, "title": "Câu lạc bộ Chân Thác", "minutes": 5, "optional": false, "goal": "Đủ ba loài: vào câu lạc bộ, thả cá lăng lớn về vũng sâu.", "beats": ["Lễ thả cá dưới cầu vồng thác.", "MVP: người có tổng cân cao nhất."], "question_hook": "Câu lời hứa bảo vệ dòng sông (chọn câu đúng ngữ pháp).", "reward": "Huy hiệu \"Câu Lạc Bộ Chân Thác\".", "vocab": ["protect", "promise", "river", "nature"], "assets": ["fish_hemibagrus", "hdri_noon", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Cá hồi vân", "minutes": 5, "optional": true, "goal": "Kéo dài: cá hồi vân bơi ngược thác.", "beats": ["Cá nhảy khỏi mặt nước."], "question_hook": "Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["jump", "upstream"], "assets": ["fish_rainbow_trout"]}, {"n": 8, "title": "Chặng phụ: Biển báo bảo vệ", "minutes": 5, "optional": true, "goal": "Viết biển báo tiếng Anh bảo vệ dòng sông.", "beats": ["Biển báo cắm ở chân thác."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết, không tính thua.", "reward": "Huy hiệu \"Người Giữ Sông\".", "vocab": ["do not", "please", "keep clean"], "assets": ["river_sign"]}]'::jsonb, '{"sizes": {"1-5": "Một thuyền nhôm chung (2-4 người) hoặc mỗi em một thuyền nhỏ cạnh bến; bảng kỷ lục cá nhân.", "6-20": "Thuyền 3-4 người, mỗi em một cần riêng. 2-5 thuyền neo ở 2 khúc sông; bảng kỷ lục theo thuyền và cá nhân.", "21-50": "Thuyền 4 người (50 em = 13 thuyền) rải trên 3 khúc sông: bến gỗ, giữa hồ, chân thác. Mỗi khúc sông tối đa 5 thuyền để không chật màn hình; ai cũng thấy bảng kỷ lục chung."}, "roles": ["Thuyền trưởng (chọn chỗ neo)", "Thợ câu", "Người giữ vợt", "Người ghi kỷ lục"], "rules": {"score": "Điểm một con cá = cân nặng (kg) × 100 × hệ số độ hiếm (Thường 1, Khá 1,5, Hiếm 2,5, Cực hiếm 5). Trả lời nhanh cộng tới 20% điểm.", "upgrade": "Mỗi 3 câu đúng: nâng một cấp cần (gỗ → sợi thủy tinh → carbon → vàng) hoặc chọn mồi mới. Cần cấp cao kéo nhanh hơn và giữ được cá to.", "rarity": "Câu khó hơn (bậc cao hơn trong 5 bậc của gia sư) có tỉ lệ ra cá hiếm cao hơn. Cá Cực hiếm chỉ cắn khi đã có cần vàng.", "release": "Cá được thả lại sông sau khi cân và chụp ảnh (thông điệp bảo vệ thiên nhiên)."}, "avatars": "Mỗi học sinh đứng trên thuyền bằng nhân vật riêng ghép từ hồ sơ diện mạo, mặc áo phao màu thuyền. 12 nhân vật dưới đây là người dẫn chuyện và bạn câu trong phim.", "safety": "Mọi nhân vật luôn mặc áo phao trên thuyền.", "note": "Ba vũng nước = ba khu; thuyền xoay vòng khu mỗi 5 phút để lớp đông không chen một vũng."}'::jsonb, array['anim_cheer','anim_pull_fish','camp_rope','fish_bait','fish_eel','fish_hemibagrus','fish_net','fish_rainbow_trout','fish_rod','fish_sheatfish','fx_bubbles','hdri_noon','mini_ganga_valley','river_boat_aluminium','river_buoy','river_cliff','river_rock_large','river_rock_medium','river_sign','river_waterfall','river_waterfall_pool','surv_map','water_foam','water_normal']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
