insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('fish-04', 'river_fishing', 4, 'Đêm Trăng Câu Cá Tra', 'Video hồ và rừng thông; ý tưởng câu cá đêm với đèn lồng, phao phát sáng.', 'Đêm trăng tròn, chú Tâm mở chuyến "Câu đêm Trăng Rằm" vì cá tra và cá basa chỉ ăn mồi nhiều vào ban đêm. Mỗi thuyền được phát một đèn lồng và những chiếc phao phát sáng, cá cắn câu thì phao lóe sáng. Nhưng giữa đêm, một đám sương dày trôi qua che mất trăng, đèn lồng của vài thuyền tắt. Các thuyền phải giúp nhau thắp lại đèn, đọc dấu sao để tìm đường về các bãi cá. Gần nửa đêm, mặt sông sáng lên vì đàn cá tra lớn bơi qua, đó là lúc tranh tài cuối cùng.', 6, 5, 30, 12, true, 'Sông rộng về đêm, trăng tròn, đèn lồng treo trên mũi thuyền, phao phát sáng xanh lá trên mặt nước. Tiếng ếch nhái, gió mát, đom đóm ven bờ.', '[{"n": 1, "title": "Thắp đèn mũi thuyền", "minutes": 5, "optional": false, "goal": "Thắp đèn lồng, buộc phao phát sáng.", "beats": ["Mỗi câu đúng thắp sáng một phao.", "Đèn trụ bến sáng ấm: thắp đèn mũi thuyền bằng cách đọc đúng tên từng bộ phận của đèn."], "question_hook": "Câu hỏi trên chiếc đèn lồng.", "reward": "Đèn + phao sáng.", "vocab": ["lantern", "glow", "moon", "night", "lamp"], "assets": ["camp_lantern", "fish_bobber", "river_boat_aluminium", "hdri_night", "fish_dock_lamp"]}, {"n": 2, "title": "Cá đêm đầu tiên", "minutes": 5, "optional": false, "goal": "Câu cá basa dưới ánh trăng.", "beats": ["Phao lóe sáng khi cá cắn.", "Một con cá lạ ánh bạc chưa ai biết tên: cả đội đoán đặc điểm để đặt tên cho nó."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Cá basa.", "vocab": ["bite", "flash", "quiet", "basa", "mystery", "night fish"], "assets": ["fish_basa", "fish_reel", "anim_cast", "fish_unknown"]}, {"n": 3, "title": "Mồi đêm", "minutes": 5, "optional": false, "goal": "Đổi mồi phù hợp cá đêm (mồi tôm, mồi cám).", "beats": ["Nâng cần sau 3 câu đúng."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Cần sợi thủy tinh + mồi tôm.", "vocab": ["shrimp", "smell", "choose"], "assets": ["fish_bait", "fish_tackle_box"]}, {"n": 4, "title": "Sương che trăng", "minutes": 5, "optional": false, "goal": "Đèn tắt: giúp thuyền bên cạnh thắp lại, dựa vào sao tìm bãi cá.", "beats": ["Câu đúng của thuyền này thắp đèn cho thuyền kia.", "Sao Bắc Đẩu chỉ hướng bãi cá."], "question_hook": "Câu hỏi trên ngọn đèn của thuyền bạn; hợp câu hướng (north, east).", "reward": "Cả lớp sáng đèn lại.", "vocab": ["fog", "help", "star", "direction"], "assets": ["camp_lantern", "hdri_night", "surv_compass"]}, {"n": 5, "title": "Cá trê và cá lóc ven bờ", "minutes": 5, "optional": false, "goal": "Câu sát bờ lau, cá trê và cá lóc ra kiếm ăn.", "beats": ["Lau sậy rung khi cá đến."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Cần carbon.", "vocab": ["shore", "reed", "snakehead", "catfish"], "assets": ["fish_walking_catfish", "fish_snakehead", "river_reed"]}, {"n": 6, "title": "Đàn cá tra nửa đêm", "minutes": 5, "optional": false, "goal": "Mặt sông sáng lên, tranh tài câu cá tra lớn.", "beats": ["Cá tra lớn cần 2 câu đúng liên tiếp.", "MVP: cá nặng nhất đêm."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Danh hiệu \"Ngư Phủ Trăng Rằm\".", "vocab": ["midnight", "big", "school of fish", "win"], "assets": ["fish_tra", "fish_net", "anim_pull_fish", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Cá chình đêm", "minutes": 5, "optional": true, "goal": "Kéo dài: cá chình ra khỏi hang ban đêm.", "beats": ["Rất trơn, khó giữ."], "question_hook": "Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["eel", "slippery"], "assets": ["fish_eel"]}, {"n": 8, "title": "Chặng phụ: Thơ trăng", "minutes": 5, "optional": true, "goal": "Viết hai câu thơ tiếng Anh về trăng và sông.", "beats": ["Thơ hay đọc trên loa trại."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết, không tính thua.", "reward": "Huy hiệu \"Thi Sĩ Sông Trăng\".", "vocab": ["moonlight", "silver", "calm"], "assets": ["hdri_night"]}]'::jsonb, '{"sizes": {"1-5": "Một thuyền nhôm chung (2-4 người) hoặc mỗi em một thuyền nhỏ cạnh bến; bảng kỷ lục cá nhân.", "6-20": "Thuyền 3-4 người, mỗi em một cần riêng. 2-5 thuyền neo ở 2 khúc sông; bảng kỷ lục theo thuyền và cá nhân.", "21-50": "Thuyền 4 người (50 em = 13 thuyền) rải trên 3 khúc sông: bến gỗ, giữa hồ, chân thác. Mỗi khúc sông tối đa 5 thuyền để không chật màn hình; ai cũng thấy bảng kỷ lục chung."}, "roles": ["Thuyền trưởng (chọn chỗ neo)", "Thợ câu", "Người giữ vợt", "Người ghi kỷ lục"], "rules": {"score": "Điểm một con cá = cân nặng (kg) × 100 × hệ số độ hiếm (Thường 1, Khá 1,5, Hiếm 2,5, Cực hiếm 5). Trả lời nhanh cộng tới 20% điểm.", "upgrade": "Mỗi 3 câu đúng: nâng một cấp cần (gỗ → sợi thủy tinh → carbon → vàng) hoặc chọn mồi mới. Cần cấp cao kéo nhanh hơn và giữ được cá to.", "rarity": "Câu khó hơn (bậc cao hơn trong 5 bậc của gia sư) có tỉ lệ ra cá hiếm cao hơn. Cá Cực hiếm chỉ cắn khi đã có cần vàng.", "release": "Cá được thả lại sông sau khi cân và chụp ảnh (thông điệp bảo vệ thiên nhiên)."}, "avatars": "Mỗi học sinh đứng trên thuyền bằng nhân vật riêng ghép từ hồ sơ diện mạo, mặc áo phao màu thuyền. 12 nhân vật dưới đây là người dẫn chuyện và bạn câu trong phim.", "safety": "Mọi nhân vật luôn mặc áo phao trên thuyền."}'::jsonb, array['anim_cast','anim_cheer','anim_pull_fish','camp_lantern','fish_bait','fish_basa','fish_bobber','fish_dock_lamp','fish_eel','fish_net','fish_reel','fish_snakehead','fish_tackle_box','fish_tra','fish_unknown','fish_walking_catfish','hdri_night','river_boat_aluminium','river_reed','surv_compass']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
