insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('fish-05', 'river_fishing', 5, 'Truyền Thuyết Vua Cá Hồi', 'File: Cá Hồi Hoàng Gia (cá MVP), nâng cấp cần và mồi để săn cá khổng lồ; video câu cá trên thuyền.', 'Ông Chài Tư giữ một cuốn sổ cũ ghi về Vua Cá Hồi, con cá hồi hoàng gia khổng lồ chưa ai bắt được trong 30 năm. Sổ chép ba manh mối bằng tiếng Anh từ một nhà thám hiểm xưa: loại mồi Vua Cá thích, nơi nó nghỉ trưa và giờ nó ra khỏi hang. Mỗi thuyền phải đi qua ba khúc sông, bắt các loài cá chỉ đường và giải từng manh mối để mở khóa cần vàng. Nhưng một thuyền đối thủ do Bà Mũi Nhọn dẫn đầu cũng đang săn Vua Cá, muốn đem nó lên chợ. Lúc hoàng hôn, Vua Cá ra khỏi hang; thuyền bắt được sẽ cân, chụp ảnh và thả nó về sông như lời hứa với ông Chài Tư.', 6, 5, 30, 12, true, 'Ba khúc sông nối nhau: bến gỗ làng chài, hồ rộng giữa núi và cửa hang nơi sông chảy ra từ lòng núi. Từ trưa đến hoàng hôn, nắng vàng rồi đỏ rực. Trong cuốn sổ ông Chài Tư có bản đồ nổi của lưu vực sông.', '[{"n": 1, "title": "Cuốn sổ của ông Chài Tư", "minutes": 5, "optional": false, "goal": "Đọc trang đầu cuốn sổ, nhận nhiệm vụ.", "beats": ["Phim ngắn: bóng cá khổng lồ dưới nước.", "Mỗi câu đúng mở một trang sổ.", "Bản đồ nổi lưu vực sông chỉ ba khúc sông; chạm đúng tên khúc sông thì sổ mở trang."], "question_hook": "Cuốn sổ cũ; câu đọc hiểu ngắn mở từng trang.", "reward": "Manh mối 1: loại mồi.", "vocab": ["legend", "giant", "clue", "old", "river basin", "map"], "assets": ["surv_letter", "river_dock", "river_cabin", "fish_king_salmon", "mini_indus_basin"]}, {"n": 2, "title": "Bến làng chài", "minutes": 5, "optional": false, "goal": "Bắt cá rô phi, cá trắm để đổi lấy mồi ruồi đặc biệt.", "beats": ["Ngư dân làng đổi mồi lấy cá.", "Thuyền chèo và giỏ đan của làng chài nằm sẵn ở bến.", "Một người lạ đi bộ qua bến làng chài, hỏi đường tới hồ giữa núi."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Mồi ruồi đặc biệt.", "vocab": ["trade", "fly", "village", "rowboat", "basket", "stranger"], "assets": ["fish_tilapia", "fish_grass_carp", "fish_bait", "fish_bucket", "river_boat_row", "fish_basket", "char_wanderer"]}, {"n": 3, "title": "Hồ giữa núi", "minutes": 5, "optional": false, "goal": "Câu cá hồi vân để biết nơi Vua Cá nghỉ trưa (manh mối 2).", "beats": ["Cá hồi vân bơi về hướng Vua Cá.", "Nâng cần carbon sau 3 câu đúng.", "Hồ giữa núi nhìn thấy đáy: đá nào, cá nào đọc đúng tên mới thấy."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Manh mối 2 + cần carbon.", "vocab": ["lake", "rest", "follow", "trout", "clear water", "rock"], "assets": ["fish_rainbow_trout", "river_boat_aluminium", "hdri_noon", "mini_clear_river"]}, {"n": 4, "title": "Cuộc đua với Bà Mũi Nhọn", "minutes": 5, "optional": false, "goal": "Thuyền đối thủ chặn đường: vượt lên trước bằng câu trả lời đúng.", "beats": ["Thuyền đối thủ do máy chủ điều khiển.", "Câu đúng = tăng tốc chèo."], "question_hook": "Câu hỏi trên mái chèo; mỗi câu đúng vượt lên một đoạn.", "reward": "Đến cửa hang trước.", "vocab": ["race", "ahead", "rival", "fast"], "assets": ["river_boat_row", "kayak_paddle", "river_cliff"]}, {"n": 5, "title": "Cửa hang", "minutes": 5, "optional": false, "goal": "Giải manh mối 3 (giờ Vua Cá ra), nâng cần vàng.", "beats": ["Manh mối là câu đố giờ giấc bằng tiếng Anh.", "Cần vàng cho thuyền giải xong."], "question_hook": "Câu đố hiện trên vách hang; câu dạng điền từ.", "reward": "Cần vàng.", "vocab": ["cave", "time", "o''clock", "gold"], "assets": ["river_cave", "fish_rod", "surv_letter"]}, {"n": 6, "title": "Hoàng hôn: Vua Cá Hồi", "minutes": 5, "optional": false, "goal": "Vua Cá ra khỏi hang: săn, cân, chụp ảnh, thả về sông.", "beats": ["Vua Cá cần 3 câu đúng liên tiếp, câu cuối khó nhất.", "Cả lớp cổ vũ; MVP là người kéo được Vua Cá hoặc cá nặng nhất.", "Trước khi Vua Cá Hồi hiện ra, một con cá chép vàng hiếm bơi qua: ghi lại đặc điểm của nó."], "question_hook": "Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.", "reward": "Danh hiệu \"Người Gặp Vua Cá\"; ảnh lưu vào sổ ông Chài Tư.", "vocab": ["king", "catch", "photo", "let go", "golden carp", "rare"], "assets": ["fish_king_salmon", "fish_scale", "hdri_sunset", "anim_pull_fish", "anim_cheer", "fish_golden_carp"]}, {"n": 7, "title": "Chặng phụ: Con của Vua Cá", "minutes": 5, "optional": true, "goal": "Kéo dài: đàn cá hồi nhỏ theo sau Vua Cá.", "beats": ["Bắt và thả đàn cá nhỏ."], "question_hook": "Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["baby", "family"], "assets": ["fish_rainbow_trout"]}, {"n": 8, "title": "Chặng phụ: Trang sổ mới", "minutes": 5, "optional": true, "goal": "Viết trang sổ mới kể lại cuộc săn.", "beats": ["Trang sổ được ông Chài Tư dán vào sổ cũ."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết, không tính thua.", "reward": "Huy hiệu \"Thợ Săn Truyền Thuyết\".", "vocab": ["finally", "amazing", "we"], "assets": ["surv_letter"]}]'::jsonb, '{"sizes": {"1-5": "Một thuyền nhôm chung (2-4 người) hoặc mỗi em một thuyền nhỏ cạnh bến; bảng kỷ lục cá nhân.", "6-20": "Thuyền 3-4 người, mỗi em một cần riêng. 2-5 thuyền neo ở 2 khúc sông; bảng kỷ lục theo thuyền và cá nhân.", "21-50": "Thuyền 4 người (50 em = 13 thuyền) rải trên 3 khúc sông: bến gỗ, giữa hồ, chân thác. Mỗi khúc sông tối đa 5 thuyền để không chật màn hình; ai cũng thấy bảng kỷ lục chung."}, "roles": ["Thuyền trưởng (chọn chỗ neo)", "Thợ câu", "Người giữ vợt", "Người ghi kỷ lục"], "rules": {"score": "Điểm một con cá = cân nặng (kg) × 100 × hệ số độ hiếm (Thường 1, Khá 1,5, Hiếm 2,5, Cực hiếm 5). Trả lời nhanh cộng tới 20% điểm.", "upgrade": "Mỗi 3 câu đúng: nâng một cấp cần (gỗ → sợi thủy tinh → carbon → vàng) hoặc chọn mồi mới. Cần cấp cao kéo nhanh hơn và giữ được cá to.", "rarity": "Câu khó hơn (bậc cao hơn trong 5 bậc của gia sư) có tỉ lệ ra cá hiếm cao hơn. Cá Cực hiếm chỉ cắn khi đã có cần vàng.", "release": "Cá được thả lại sông sau khi cân và chụp ảnh (thông điệp bảo vệ thiên nhiên)."}, "avatars": "Mỗi học sinh đứng trên thuyền bằng nhân vật riêng ghép từ hồ sơ diện mạo, mặc áo phao màu thuyền. 12 nhân vật dưới đây là người dẫn chuyện và bạn câu trong phim.", "safety": "Mọi nhân vật luôn mặc áo phao trên thuyền.", "note": "Ba khúc sông = ba khu; thuyền đi theo thứ tự, lớp đông thì xuất phát so le 30 giây."}'::jsonb, array['anim_cheer','anim_pull_fish','char_wanderer','fish_bait','fish_basket','fish_bucket','fish_golden_carp','fish_grass_carp','fish_king_salmon','fish_rainbow_trout','fish_rod','fish_scale','fish_tilapia','hdri_noon','hdri_sunset','kayak_paddle','mini_clear_river','mini_indus_basin','river_boat_aluminium','river_boat_row','river_cabin','river_cave','river_cliff','river_dock','surv_letter']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
