insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('fish-05#11', 'fish-05', 11, 'Tý', 'Cháu ông Chài Tư, thuộc đường sông', 'child', 'm', 'S3', false, 'E_black', 'dark_brown', 'curly', 'short', false, false, 'vn_traditional', 'yellow', 'Áo vàng, quần xắn', null, null, array['bag']::text[], 'Bạn dẫn đường', 'npc');
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('fish-05#12', 'fish-05', 12, 'Vua Cá Hồi', 'Cá hồi hoàng gia khổng lồ, vảy ánh vàng', 'elder', 'n', 'S2', false, 'E_black', 'ash_gray', 'short_neat', 'short', false, false, 'casual', 'red', 'Vảy đỏ cam ánh vàng', null, null, '{}'::text[], 'Cá MVP huyền thoại', 'npc');
insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('surv-01', 'river_survival', 1, 'Thoát khỏi Trại Cờ Cam', 'File "Thay game mới" mục II.3 (cảnh mở đầu cọc gỗ, Task Panel, 2 đội) + video bờ sông đá sỏi, rừng thông, nhà gỗ cũ trong cỏ cao.', 'Trò chơi trận giả cuối khóa của Trại Hè Sông Ngọc bắt đầu bằng một bất ngờ: Đội Săn Tìm phục kích từ trưa, dồn cả nhóm bạn vào Chuồng Gỗ và quấn dây thừng chặt quanh cổng. Minh Khôi phát hiện một tảng đá sắc cạnh hàng rào, cả nhóm thay nhau mài dây và bung cổng thoát ra. Từ đây phải sống sót đến khi trống trại vang lúc hoàng hôn: tìm nước sạch, nhặt đá và gậy dựng bẫy phòng thủ, giải mật thư của bác Kiểm lâm Sáu để tìm hang trú an toàn, và xóa dấu chân trên cát. Đội Săn Tìm của Hạ Vy có bản đồ quét dấu vết và quyết bắt hơn một nửa số người. Nhưng giữa trận, trại cờ cam để quên một thùng Lưới Gắn Thẻ dự phòng; ai lẻn đến được sẽ lật ngược thế cờ, đuổi ngược Đội Săn Tìm và giải cứu đồng đội.', 6, 5, 30, 12, true, 'Bờ sông đá sỏi lúc chiều tà, rừng thông phía sau, một nhà gỗ cũ giữa bãi cỏ cao. Trại của Đội Săn Tìm cắm cờ cam ở đầu bãi. Trời chuyển từ vàng cam sang tím, sương bắt đầu lên mặt nước. Ở góc bờ có một chiếc thuyền chèo cũ phủ lưới bỏ quên.', '[{"n": 1, "title": "Chuồng Gỗ và sợi dây thừng", "minutes": 5, "optional": false, "goal": "Mở màn: thoát khỏi Chuồng Gỗ; Đội Săn Tìm nhận bản đồ và chia khu.", "beats": ["Phim ngắn 20 giây: cổng chuồng quấn dây, Minh Khôi nhìn thấy đá sắc.", "Mỗi câu đúng là một nhát mài dây; thanh dây đứt dần, cổng bung khi cả nhóm đủ 5 câu.", "Đội Săn Tìm đứng ở trại cờ cam, đếm ngược 60 giây rồi mới được xuất phát.", "Tường gỗ có cửa sổ của Chuồng Gỗ: nhìn qua cửa sổ đọc câu hỏi để đoán chỗ giấu dây."], "question_hook": "Câu hỏi hiện ngay trên sợi dây thừng; đúng thì dây sờn thêm một đoạn, sai thì dây chỉ rung nhẹ.", "reward": "Mở khóa đôi giày chạy và bản đồ nhỏ.", "vocab": ["rope", "rock", "escape", "cut", "run", "wall", "window"], "assets": ["surv_holding_pen", "surv_rope", "surv_rope_cut", "surv_sharp_rock", "surv_stake", "surv_rival_tent", "surv_flag", "anim_rope_rub", "surv_pen_wall_window"]}, {"n": 2, "title": "Nhiệm vụ 1: Nước sạch bên suối", "minutes": 5, "optional": false, "goal": "Tìm dòng suối trong, lọc nước vào bình trước khi Đội Săn Tìm khép vòng.", "beats": ["Ba con suối: một đục bùn, một có lá mục, một trong vắt sau khe đá.", "Đội Săn Tìm mở kỹ năng Quét dấu chân lần đầu.", "Người Chạy Trốn bị bắt được đưa về Chuồng Gỗ, bắt đầu giải mật thư hỗ trợ.", "Suối trong chảy ra từ bãi đá: gọi đúng tên mới được múc nước."], "question_hook": "Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao). Chọn đúng con suối cũng là một câu trắc nghiệm.", "reward": "1-3 sao; nhận Bình nước (hồi sức chạy).", "vocab": ["water", "stream", "clean", "dirty", "bottle", "spring", "clear water"], "assets": ["surv_spring", "surv_stone_basin", "camp_bottle", "river_rock_medium", "river_fern", "river_moss_rock", "mini_clear_river"]}, {"n": 3, "title": "Nhiệm vụ 2: Đá nhọn và gậy gỗ", "minutes": 5, "optional": false, "goal": "Gom 3 gậy và 3 đá nhọn để dựng bẫy dây vấp và hàng rào cành quanh hang trú.", "beats": ["Bẫy chỉ làm người Săn Tìm vấp ngã ngồi, cười và mất 5 giây.", "Đội Săn Tìm nhận Ống nhòm, soi được một bụi cây mỗi lần.", "Bác Sáu thả mật thư đầu tiên trên cành thông.", "Thùng container xanh gỉ là kho của trại địch: gọi đúng tên công cụ bên trong mới mở được."], "question_hook": "Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao). Mỗi câu đúng = nhặt được một món; món hiện viền sáng trong cỏ.", "reward": "Mở khóa Bẫy dây vấp (đặt được 1 cái/người).", "vocab": ["stick", "stone", "sharp", "trap", "build", "container", "storage"], "assets": ["surv_stick", "surv_pointed_stone", "surv_tripwire", "surv_trap_rope", "river_branch", "river_rock_small", "surv_container_blue"]}, {"n": 4, "title": "Nhiệm vụ 3: Mật thư của bác Kiểm lâm", "minutes": 5, "optional": false, "goal": "Giải mật thư tiếng Anh để biết lối vào Hang Rêu, nơi an toàn nhất bờ sông.", "beats": ["Mật thư là một đoạn chỉ đường bị xáo chữ.", "Người ở Chuồng Gỗ giải cùng: mỗi câu họ đúng gửi một chữ cho đội.", "Đội Săn Tìm đoán được hướng nếu đội Chạy Trốn trả lời sai nhiều."], "question_hook": "Mật thư hiện như tờ giấy cũ; mỗi câu đúng làm hiện một chữ cái bị mờ. Câu dạng sắp xếp từ và điền từ rất hợp ở chặng này.", "reward": "Mở đường tắt vào Hang Rêu (ẩn nấp sâu 30 giây).", "vocab": ["north", "left", "behind", "cave", "across"], "assets": ["surv_letter", "surv_map", "surv_compass", "river_cave", "river_moss_rock", "river_cliff"]}, {"n": 5, "title": "Nhiệm vụ 4: Xóa dấu và thùng lưới bỏ quên", "minutes": 5, "optional": false, "goal": "Xóa dấu chân trên cát và bùn; lẻn đến thùng Lưới Gắn Thẻ dự phòng ở trại cờ cam.", "beats": ["Dấu chân mỗi người để lại mờ dần sau 40 giây; chổi cành xóa ngay.", "Thùng lưới mở sau 3 câu đúng liên tiếp của cùng một tiểu đội.", "Lưới cướp được: đuổi ngược (người Săn Tìm đứng yên 10 giây) hoặc mở Chuồng Gỗ cứu 2 bạn.", "Thùng lưới nằm trong thuyền chèo bỏ quên cạnh bờ: tìm ra nó để lấy Lưới Cướp.", "Nỏ bắn lưới của Đội Săn Tìm nằm gần thùng lưới bỏ quên: chỉ cướp được khi đọc đúng ba bộ phận."], "question_hook": "Chổi quét dấu: mỗi câu đúng xóa một vệt dấu chân. Nút \"Cướp lưới\" hiện khi lẻn sát sau lưng người Săn Tìm: một câu 8 giây.", "reward": "Lưới Gắn Thẻ (3 lần dùng hoặc 60 giây).", "vocab": ["footprint", "sand", "mud", "sweep", "hide", "net", "rowboat", "launcher"], "assets": ["surv_broom", "decal_footprint_sand", "decal_footprint_mud", "surv_crate", "surv_capture_net", "surv_barrel", "river_boat_row", "surv_net_launcher_a"]}, {"n": 6, "title": "Trống trại lúc hoàng hôn", "minutes": 5, "optional": false, "goal": "Phút cuối: giải cứu, đuổi ngược, giữ người. Hết giờ đếm đầu người.", "beats": ["Mặt trời lặn, đèn pin bật; bụi cây tối hơn nên dễ trốn hơn.", "60 giây cuối: mọi Chuồng Gỗ mở thêm một lượt giải cứu nếu đội trả lời đúng 5 câu liền.", "Trống vang, màn hình đếm người tự do và người bị bắt, công bố MVP và \"Gương Mặt Quật Cường\"."], "question_hook": "Câu hỏi nhanh 10 giây hiện trên Chuồng Gỗ (giải cứu) và trên đèn pin (Săn Tìm soi khu).", "reward": "MVP đội thắng nhận thêm 20% tổng điểm đội thua.", "vocab": ["free", "caught", "team", "win", "brave"], "assets": ["surv_holding_pen", "surv_flashlight", "hdri_sunset", "river_birds", "anim_cheer", "anim_sad"]}, {"n": 7, "title": "Chặng phụ: Đêm sương trên sông", "minutes": 5, "optional": true, "goal": "Khi gia sư kéo dài: sương dày, tầm nhìn 10 m; một vòng giải cứu cuối.", "beats": ["Đội Săn Tìm mất Quét dấu chân, chỉ còn đèn pin.", "Người Chạy Trốn bị bắt có thể tự giải cứu bằng 3 câu khó."], "question_hook": "Câu khó hơn một bậc, thưởng gấp đôi sao.", "reward": "Sao đôi.", "vocab": ["fog", "quiet", "careful"], "assets": ["hdri_night", "surv_flashlight", "water_normal"]}, {"n": 8, "title": "Chặng phụ: Lửa trại tổng kết", "minutes": 5, "optional": true, "goal": "Ôn lại 10 từ của trận quanh lửa trại; mỗi bạn chọn một từ và đặt câu.", "beats": ["Bác Sáu khen từng tiểu đội.", "Ảnh kỷ niệm cả lớp với nhân vật của mình."], "question_hook": "Câu ôn tập không tính thua, chỉ cộng sao.", "reward": "Huy hiệu \"Thoát khỏi Trại Cờ Cam\".", "vocab": ["camp", "fire", "friend", "remember"], "assets": ["camp_firepit", "camp_lantern", "anim_wave"]}]'::jsonb, '{"sizes": {"1-5": "Tất cả học sinh vào Đội Chạy Trốn; Đội Săn Tìm là 2-3 người máy chạy chậm do máy chủ điều khiển, độ khó theo mức của lớp.", "6-20": "Chia 60/40 (ví dụ 12 Chạy Trốn, 8 Săn Tìm). Nhóm 3-4 người cùng màu dây đeo, mỗi nhóm một Đội trưởng.", "21-50": "Chia 60/40 (50 em = 30 Chạy Trốn, 20 Săn Tìm). Tiểu đội 5 người; bản đồ mở rộng 3 khu, mỗi khu một Chuồng Gỗ để không dồn 50 người một chỗ."}, "roles": {"escapers": ["Đội trưởng (giữ bản đồ, chọn đường)", "Trinh sát (dò bụi cây an toàn)", "Thợ giải mã (mật thư)", "Người tìm nước", "Người xóa dấu"], "pursuers": ["Đội trưởng Săn Tìm (chia khu)", "Người dò dấu chân", "Người canh ống nhòm", "Người chạy nhanh", "Người giữ Chuồng Gỗ"]}, "avatars": "12 nhân vật dưới đây là người dẫn chuyện và vai mẫu trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo (không trùng trong lớp) và mặc vest màu đội.", "rules": {"teams": "Đội Chạy Trốn (vest xanh) và Đội Săn Tìm (vest cam). Tỉ lệ 60/40, làm tròn, ít nhất 1 người mỗi đội.", "match": "Một trận liền mạch 30 phút, không chia hiệp. 2 chặng phụ chỉ mở khi gia sư bấm \"Kéo dài\".", "win": "Hết giờ: nếu số Chạy Trốn còn tự do > số bị bắt thì Đội Chạy Trốn thắng; nếu Đội Săn Tìm bắt được hơn 50% thì Đội Săn Tìm thắng; hòa (đúng 50%) thì đội có tổng sao cao hơn thắng.", "stars": "Mỗi nhiệm vụ cho 1-3 sao theo độ chính xác và tốc độ. Điểm = sao × 100 + điểm hành động (bắt, giải cứu, cướp lưới).", "mvp": "MVP đội thắng (điểm cao nhất) nhận thêm 20% tổng điểm của toàn đội thua. Người điểm cao nhất đội thua nhận danh hiệu \"Gương Mặt Quật Cường\".", "capture": "Đội Săn Tìm chạm Lưới Gắn Thẻ vào người Chạy Trốn = bắt. Người bị bắt về Chuồng Gỗ, không bị loại: tiếp tục giải mật thư hỗ trợ đội và có thể được giải cứu.", "snatch": "Người Chạy Trốn lẻn sát sau lưng người Săn Tìm (2 m, không bị nhìn thấy) sẽ hiện nút \"Cướp lưới\": một câu hỏi 8 giây. Đúng: cướp được Lưới, người Săn Tìm mất lưới 45 giây. Sai: vị trí người Chạy Trốn hiện trên bản đồ đội Săn Tìm 5 giây.", "net_power": "Lưới cướp được dùng 3 lần hoặc 60 giây: chạm người Săn Tìm làm họ đứng yên 10 giây (đuổi ngược), hoặc mở Chuồng Gỗ giải cứu 2 đồng đội. Hết lượt, lưới tự về trại Săn Tìm. Người Săn Tìm lấy lại lưới bằng cách chạm người đang cầm.", "pursuer_skills": "Đội Săn Tìm cũng học: mỗi câu đúng nạp một kỹ năng: Quét dấu chân (hiện dấu trong bán kính 15 m, 8 giây), Ống nhòm (soi một bụi cây), Chạy nhanh (5 giây).", "escaper_skills": "Đội Chạy Trốn: câu đúng nạp Xóa dấu (xóa dấu chân 10 giây), Ẩn nấp sâu (không bị Ống nhòm thấy 15 giây), Mồi nhử (tạo dấu chân giả).", "dodge": "Khi bị chạm lưới, người Chạy Trốn có một câu \"Né lưới\" 6 giây, mỗi chặng dùng được 1 lần. Đúng thì thoát.", "safety": "Không có cảnh đau, máu hay vũ khí thật. \"Bị bắt\" = bị gắn thẻ, nhân vật giơ tay cười. Dây thừng chỉ quấn cổng chuồng và ba lô, không trói người.", "no_idle": "Không ai phải ngồi chờ: người bị bắt giải mật thư, người Săn Tìm trả lời để nạp kỹ năng."}, "map_zones": ["Bãi sỏi", "Rừng thông", "Nhà gỗ cỏ cao"]}'::jsonb, array['anim_cheer','anim_rope_rub','anim_sad','anim_wave','camp_bottle','camp_firepit','camp_lantern','decal_footprint_mud','decal_footprint_sand','hdri_night','hdri_sunset','mini_clear_river','river_birds','river_boat_row','river_branch','river_cave','river_cliff','river_fern','river_moss_rock','river_rock_medium','river_rock_small','surv_barrel','surv_broom','surv_capture_net','surv_compass','surv_container_blue','surv_crate','surv_flag','surv_flashlight','surv_holding_pen','surv_letter','surv_map','surv_net_launcher_a','surv_pen_wall_window','surv_pointed_stone','surv_rival_tent','surv_rope','surv_rope_cut','surv_sharp_rock','surv_spring','surv_stake','surv_stick','surv_stone_basin','surv_trap_rope','surv_tripwire','water_normal']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('surv-01#01', 'surv-01', 1, 'Bác Sáu', 'Kiểm lâm già, làm trọng tài, giấu mật thư trên cành thông', 'elder', 'm', 'S3', false, 'E_brown_dark', 'silver', 'side_part', 'short', false, false, 'explorer', 'khaki', 'Áo kiểm lâm kaki, mũ rộng vành, khăn quàng xanh', 'staff_cane', null, array['hat','whistle','map_or_notebook']::text[], 'Trọng tài trận giả, người viết mật thư', 'npc');
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('surv-01#02', 'surv-01', 2, 'Minh Khôi', 'Bình tĩnh, nhìn thấy đá sắc đầu tiên', 'child', 'm', 'S2', false, 'E_black', 'black', 'spiky', 'short', false, false, 'explorer', 'blue', 'Áo thun xanh, quần lửng, ba lô nhỏ', 'rolled_paper', null, array['bag','watch']::text[], 'Đội trưởng Chạy Trốn', 'escapers');
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('surv-01#03', 'surv-01', 3, 'An Nhiên', 'Tai rất thính, nghe tiếng bước chân từ xa', 'child', 'f', 'S4', false, 'E_brown', 'dark_brown', 'ponytail', 'long', false, false, 'casual', 'teal', 'Áo khoác gió xanh ngọc, quần dài', null, null, array['headband']::text[], 'Trinh sát', 'escapers');
