insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('surv-02', 'river_survival', 2, 'Bí mật Thác Ba Tầng', 'Rừng sông hẻo lánh trong file + ý tưởng hang sau thác; nước trong nhìn thấy đá đáy như video.', 'Đội Săn Tìm năm nay chọn đúng thác Ba Tầng làm sân đấu và nhốt nhóm bạn trong chuồng gỗ dưới chân thác. Tiếng nước ầm ầm che tiếng mài dây, nên Mai Anh cắt được dây và mở cổng mà không ai nghe thấy. Truyền thuyết của trại kể rằng sau tầng thác giữa có một hang khô, chỉ ai đọc được ba tấm bia khắc chữ tiếng Anh mới tìm ra lối vào. Cả đội phải tìm nước suối trong, gom đá và gậy dựng chốt chặn ở cầu treo, giải bia đá, rồi xóa dấu chân ướt trên đá trơn. Ở tầng cao nhất, Đội Săn Tìm cất kho Lưới Gắn Thẻ trong một thùng gỗ cạnh cầu vồng: ai lấy được sẽ lật ngược trận đấu.', 6, 5, 30, 12, true, 'Hẻm núi có thác nước ba tầng, bụi nước mờ như sương, vách đá phủ rêu, cầu gỗ treo bắc qua tầng giữa. Buổi chiều nắng xiên qua bụi nước tạo cầu vồng. Thác nước ba tầng đổ xuống hồ phía dưới; một thác cao một tầng nằm khuất bên phải.', '[{"n": 1, "title": "Dưới chân thác", "minutes": 5, "optional": false, "goal": "Mài dây mở chuồng gỗ dưới tiếng thác; Đội Săn Tìm leo lên tầng giữa đặt chốt.", "beats": ["Tiếng thác làm mờ âm thanh: Đội Săn Tìm không nghe được bước chạy trong 60 giây đầu.", "Cổng bung khi đủ số câu đúng của cả nhóm.", "Đội nghe tiếng thác dội: gọi đúng tên các tầng thác để định hướng."], "question_hook": "Câu hỏi hiện trên sợi dây ướt; mỗi câu đúng là một nhát mài.", "reward": "Mở khóa giày bám đá.", "vocab": ["waterfall", "loud", "wet", "climb", "mist"], "assets": ["surv_holding_pen", "surv_rope", "surv_sharp_rock", "river_cliff", "river_moss_rock", "water_foam", "river_waterfall"]}, {"n": 2, "title": "Nhiệm vụ 1: Giọt nước trong", "minutes": 5, "optional": false, "goal": "Hứng nước từ khe đá sạch, tránh vũng nước đọng có bọ gậy.", "beats": ["Ba khe đá, chỉ một khe nước chảy liên tục.", "Đội Săn Tìm dùng Quét dấu chân trên đá ướt (dấu ướt hiện rõ hơn).", "Giọt nước trong rơi xuống hồ chân thác: múc ở đây."], "question_hook": "Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).", "reward": "Bình nước + 1 lần Ẩn nấp sâu.", "vocab": ["drop", "fresh", "pond", "insect", "clear water", "pool"], "assets": ["surv_spring", "surv_stone_basin", "camp_bottle", "river_rock_large", "river_waterfall_pool"]}, {"n": 3, "title": "Nhiệm vụ 2: Chốt chặn cầu treo", "minutes": 5, "optional": false, "goal": "Gom gậy và đá nhọn dựng hàng rào cành ở đầu cầu treo, làm chậm Đội Săn Tìm.", "beats": ["Hàng rào làm người Săn Tìm phải đi vòng 8 giây.", "Cầu treo lắc khi có hơn 4 người đứng trên.", "Thùng container đỏ chặn đường cầu treo: giải câu đố để kéo nó sang bên."], "question_hook": "Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao). Mỗi câu đúng gắn thêm một cành vào hàng rào.", "reward": "Hàng rào cành (1 cái/tiểu đội).", "vocab": ["bridge", "fence", "slow", "branch", "barrier", "container"], "assets": ["river_bridge", "surv_stick", "surv_pointed_stone", "river_branch", "river_fence", "surv_container_red"]}, {"n": 4, "title": "Nhiệm vụ 3: Ba tấm bia đá", "minutes": 5, "optional": false, "goal": "Đọc ba tấm bia để ghép ra lối vào hang sau thác.", "beats": ["Mỗi bia một câu chỉ đường bị mất chữ.", "Người ở chuồng gỗ đọc bia qua ống nhòm và gửi chữ cho đội."], "question_hook": "Bia đá phủ rêu; mỗi câu đúng làm rêu tan bớt, lộ một chữ. Hợp với câu điền từ (cloze).", "reward": "Lối vào hang sau thác.", "vocab": ["stone", "behind", "through", "secret"], "assets": ["surv_letter", "river_cave", "river_cliff", "river_moss_rock"]}, {"n": 5, "title": "Nhiệm vụ 4: Dấu chân ướt và thùng lưới cầu vồng", "minutes": 5, "optional": false, "goal": "Xóa dấu chân ướt trên đá; lẻn lên tầng cao lấy Lưới Gắn Thẻ.", "beats": ["Dấu chân ướt khô dần sau 30 giây dưới nắng.", "Thùng lưới cạnh cầu vồng, được Kenzo canh giữ."], "question_hook": "Chổi cành xóa dấu theo câu đúng; nút \"Cướp lưới\" khi lẻn sau lưng người Săn Tìm.", "reward": "Lưới Gắn Thẻ.", "vocab": ["rainbow", "dry", "sneak", "top"], "assets": ["surv_broom", "decal_footprint_mud", "surv_crate", "surv_capture_net"]}, {"n": 6, "title": "Cầu vồng tắt", "minutes": 5, "optional": false, "goal": "Nắng tắt, cầu vồng biến mất: phút cuối giải cứu và đếm người.", "beats": ["Bụi nước dày lên, che bớt tầm nhìn.", "Công bố kết quả, MVP và Gương Mặt Quật Cường."], "question_hook": "Câu 10 giây trên chuồng gỗ và trên ống nhòm.", "reward": "MVP +20% điểm đội thua.", "vocab": ["last", "rescue", "count", "winner"], "assets": ["surv_holding_pen", "surv_binoculars", "hdri_sunset", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Hang sau thác", "minutes": 5, "optional": true, "goal": "Kéo dài: cả hai đội vào hang tối, chỉ có đèn pin.", "beats": ["Ai đứng yên trong bóng tối 5 giây thì Ống nhòm không thấy."], "question_hook": "Câu hỏi hiện trên Bảng Nhiệm vụ và trên Chuồng Gỗ như trận chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["dark", "echo", "torch"], "assets": ["river_cave", "surv_flashlight"]}, {"n": 8, "title": "Chặng phụ: Kể chuyện bên thác", "minutes": 5, "optional": true, "goal": "Mỗi tiểu đội kể lại đường thoát của mình bằng 3 câu tiếng Anh.", "beats": ["Bình chọn câu chuyện hay nhất."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng bên lửa trại. Câu sắp xếp câu kể, không tính thua.", "reward": "Huy hiệu \"Người giữ bí mật Thác Ba Tầng\".", "vocab": ["story", "first", "then", "finally"], "assets": ["camp_firepit", "anim_wave"]}]'::jsonb, '{"sizes": {"1-5": "Tất cả học sinh vào Đội Chạy Trốn; Đội Săn Tìm là 2-3 người máy chạy chậm do máy chủ điều khiển, độ khó theo mức của lớp.", "6-20": "Chia 60/40 (ví dụ 12 Chạy Trốn, 8 Săn Tìm). Nhóm 3-4 người cùng màu dây đeo, mỗi nhóm một Đội trưởng.", "21-50": "Chia 60/40 (50 em = 30 Chạy Trốn, 20 Săn Tìm). Tiểu đội 5 người; bản đồ mở rộng 3 khu, mỗi khu một Chuồng Gỗ để không dồn 50 người một chỗ."}, "roles": {"escapers": ["Đội trưởng (giữ bản đồ, chọn đường)", "Trinh sát (dò bụi cây an toàn)", "Thợ giải mã (mật thư)", "Người tìm nước", "Người xóa dấu"], "pursuers": ["Đội trưởng Săn Tìm (chia khu)", "Người dò dấu chân", "Người canh ống nhòm", "Người chạy nhanh", "Người giữ Chuồng Gỗ"]}, "avatars": "12 nhân vật dưới đây là người dẫn chuyện và vai mẫu trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo (không trùng trong lớp) và mặc vest màu đội.", "rules": {"teams": "Đội Chạy Trốn (vest xanh) và Đội Săn Tìm (vest cam). Tỉ lệ 60/40, làm tròn, ít nhất 1 người mỗi đội.", "match": "Một trận liền mạch 30 phút, không chia hiệp. 2 chặng phụ chỉ mở khi gia sư bấm \"Kéo dài\".", "win": "Hết giờ: nếu số Chạy Trốn còn tự do > số bị bắt thì Đội Chạy Trốn thắng; nếu Đội Săn Tìm bắt được hơn 50% thì Đội Săn Tìm thắng; hòa (đúng 50%) thì đội có tổng sao cao hơn thắng.", "stars": "Mỗi nhiệm vụ cho 1-3 sao theo độ chính xác và tốc độ. Điểm = sao × 100 + điểm hành động (bắt, giải cứu, cướp lưới).", "mvp": "MVP đội thắng (điểm cao nhất) nhận thêm 20% tổng điểm của toàn đội thua. Người điểm cao nhất đội thua nhận danh hiệu \"Gương Mặt Quật Cường\".", "capture": "Đội Săn Tìm chạm Lưới Gắn Thẻ vào người Chạy Trốn = bắt. Người bị bắt về Chuồng Gỗ, không bị loại: tiếp tục giải mật thư hỗ trợ đội và có thể được giải cứu.", "snatch": "Người Chạy Trốn lẻn sát sau lưng người Săn Tìm (2 m, không bị nhìn thấy) sẽ hiện nút \"Cướp lưới\": một câu hỏi 8 giây. Đúng: cướp được Lưới, người Săn Tìm mất lưới 45 giây. Sai: vị trí người Chạy Trốn hiện trên bản đồ đội Săn Tìm 5 giây.", "net_power": "Lưới cướp được dùng 3 lần hoặc 60 giây: chạm người Săn Tìm làm họ đứng yên 10 giây (đuổi ngược), hoặc mở Chuồng Gỗ giải cứu 2 đồng đội. Hết lượt, lưới tự về trại Săn Tìm. Người Săn Tìm lấy lại lưới bằng cách chạm người đang cầm.", "pursuer_skills": "Đội Săn Tìm cũng học: mỗi câu đúng nạp một kỹ năng: Quét dấu chân (hiện dấu trong bán kính 15 m, 8 giây), Ống nhòm (soi một bụi cây), Chạy nhanh (5 giây).", "escaper_skills": "Đội Chạy Trốn: câu đúng nạp Xóa dấu (xóa dấu chân 10 giây), Ẩn nấp sâu (không bị Ống nhòm thấy 15 giây), Mồi nhử (tạo dấu chân giả).", "dodge": "Khi bị chạm lưới, người Chạy Trốn có một câu \"Né lưới\" 6 giây, mỗi chặng dùng được 1 lần. Đúng thì thoát.", "safety": "Không có cảnh đau, máu hay vũ khí thật. \"Bị bắt\" = bị gắn thẻ, nhân vật giơ tay cười. Dây thừng chỉ quấn cổng chuồng và ba lô, không trói người.", "no_idle": "Không ai phải ngồi chờ: người bị bắt giải mật thư, người Săn Tìm trả lời để nạp kỹ năng."}, "map_zones": ["Chân thác", "Cầu treo tầng giữa", "Đỉnh thác cầu vồng"]}'::jsonb, array['anim_cheer','anim_wave','camp_bottle','camp_firepit','decal_footprint_mud','hdri_sunset','river_branch','river_bridge','river_cave','river_cliff','river_fence','river_moss_rock','river_rock_large','river_waterfall','river_waterfall_pool','surv_binoculars','surv_broom','surv_capture_net','surv_container_red','surv_crate','surv_flashlight','surv_holding_pen','surv_letter','surv_pointed_stone','surv_rope','surv_sharp_rock','surv_spring','surv_stick','surv_stone_basin','water_foam']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
