insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('surv-03', 'river_survival', 3, 'Đêm Đom Đóm Rừng Thông', 'Video rừng thông và lều phát sáng ban đêm; file: lẩn trốn bụi cây, đội truy đuổi dùng bản đồ quét.', 'Đêm cuối trại, bác Ba bảo vệ tổ chức trận "Đom Đóm": Đội Săn Tìm cầm đèn pin, Đội Chạy Trốn chỉ có ánh sáng đom đóm. Mở màn, cả nhóm bị dồn vào chuồng gỗ ở bãi đèn lồng; Gia Bảo mài dây trên một hòn đá sắc dưới ánh trăng và cả nhóm thoát vào rừng. Đom đóm bay theo người trả lời đúng, vừa soi đường vừa dễ làm lộ chỗ trốn, nên mỗi bước phải tính toán. Muốn sống sót đến khi tiếng chuông 12 giờ vang, đội phải lấy nước ở suối trăng, làm bẫy dây, giải mật thư viết bằng mực phát sáng và xóa dấu chân trên lá kim. Đội Săn Tìm cất Lưới Gắn Thẻ dự phòng trong túi treo trên cây thông cổ thụ: ai leo tới được sẽ đổi vai, đuổi ngược đội cầm đèn.', 6, 5, 30, 12, true, 'Rừng thông ven sông vào ban đêm, trăng lưỡi liềm, hàng nghìn đom đóm bay trên bãi cỏ. Đèn lồng giấy treo dọc lối mòn; mặt sông lấp lánh ánh trăng.', '[{"n": 1, "title": "Bãi đèn lồng", "minutes": 5, "optional": false, "goal": "Thoát chuồng gỗ dưới trăng; Đội Săn Tìm bật đèn pin, chia khu rừng.", "beats": ["Đèn lồng giấy đung đưa, bóng cây đổ dài.", "Mỗi câu đúng: một nhát mài dây; đom đóm bay quanh người đúng.", "Cậu bé leo tháp canh quan sát bãi đèn lồng: gọi đúng vị trí đèn để báo cho đội."], "question_hook": "Câu hỏi hiện trên sợi dây dưới ánh trăng.", "reward": "Mở khóa Đom đóm dẫn đường.", "vocab": ["night", "moon", "lantern", "firefly", "lookout"], "assets": ["surv_holding_pen", "surv_rope", "surv_sharp_rock", "camp_lantern", "camp_string_lights", "hdri_night", "watchtower", "char_gamer_boy"]}, {"n": 2, "title": "Nhiệm vụ 1: Suối trăng", "minutes": 5, "optional": false, "goal": "Tìm khúc suối có trăng soi đáy (nước trong), lấy nước trước khi đèn pin quét tới.", "beats": ["Nước đục không phản chiếu trăng.", "Đội Săn Tìm: mỗi câu đúng làm đèn pin sáng xa thêm 3 m."], "question_hook": "Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).", "reward": "Bình nước.", "vocab": ["reflect", "clear", "shine", "bright"], "assets": ["surv_spring", "camp_bottle", "water_normal", "river_reed"]}, {"n": 3, "title": "Nhiệm vụ 2: Bẫy dây trong bóng tối", "minutes": 5, "optional": false, "goal": "Gom gậy và đá dựng bẫy dây vấp quanh lối mòn.", "beats": ["Bẫy chạm vào thì kêu lục lạc và làm người Săn Tìm ngồi bệt 5 giây.", "Đom đóm né khu có bẫy, nên phải nhớ vị trí.", "Lính gác máy của trại địch quét bãi bẫy: nhìn vào tia sáng để biết lúc nào an toàn đi qua."], "question_hook": "Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).", "reward": "Bẫy dây lục lạc.", "vocab": ["bell", "path", "step", "careful", "sentinel", "tripwire"], "assets": ["surv_stick", "surv_pointed_stone", "surv_tripwire", "river_branch", "river_tree_pine", "surv_sentinel"]}, {"n": 4, "title": "Nhiệm vụ 3: Mật thư mực phát sáng", "minutes": 5, "optional": false, "goal": "Đọc mật thư chỉ hiện chữ khi có đom đóm bay qua.", "beats": ["Mỗi câu đúng gọi một đàn đom đóm tới làm sáng một dòng.", "Người ở chuồng gỗ đọc tiếp những dòng còn mờ."], "question_hook": "Mật thư mực phát sáng: câu đúng làm từng chữ sáng lên; hợp câu sắp xếp và điền từ.", "reward": "Vị trí cây thông cổ thụ.", "vocab": ["glow", "old", "tree", "tall"], "assets": ["surv_letter", "surv_compass", "river_tree_pine", "river_butterfly"]}, {"n": 5, "title": "Nhiệm vụ 4: Lá kim và túi lưới trên cây", "minutes": 5, "optional": false, "goal": "Xóa dấu chân trên lá kim; leo cây thông cổ thụ lấy Lưới Gắn Thẻ.", "beats": ["Dấu trên lá kim mờ nhanh nhưng phát tiếng sột soạt.", "Leo cây cần 3 câu đúng liên tiếp."], "question_hook": "Chổi lá thông xóa dấu theo câu đúng; nút \"Cướp lưới\" sau lưng người Săn Tìm.", "reward": "Lưới Gắn Thẻ.", "vocab": ["leaf", "needle", "climb", "quiet"], "assets": ["surv_broom", "decal_footprint_mud", "surv_capture_net", "river_tree_pine"]}, {"n": 6, "title": "Chuông 12 giờ", "minutes": 5, "optional": false, "goal": "Phút cuối đếm người dưới tiếng chuông.", "beats": ["Đom đóm tụ lại thành chữ tên đội thắng trên bầu trời.", "MVP và Gương Mặt Quật Cường."], "question_hook": "Câu 10 giây trên chuồng gỗ và đèn pin.", "reward": "MVP +20% điểm đội thua.", "vocab": ["midnight", "bell", "stars"], "assets": ["surv_holding_pen", "surv_flashlight", "hdri_night", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Mưa sao băng", "minutes": 5, "optional": true, "goal": "Kéo dài: mưa sao băng làm sáng rừng 5 phút, cả hai đội cùng lộ.", "beats": ["Mỗi sao băng = một câu thưởng."], "question_hook": "Câu hỏi hiện trên Bảng Nhiệm vụ và trên Chuồng Gỗ như trận chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["wish", "sky", "shooting star"], "assets": ["hdri_night"]}, {"n": 8, "title": "Chặng phụ: Lời chúc dưới trăng", "minutes": 5, "optional": true, "goal": "Viết lời chúc tiếng Anh cho bạn cùng đội.", "beats": ["Lời chúc hiện trên đèn lồng thả trôi sông."], "question_hook": "Câu viết ngắn chấm theo tiêu chí, không tính thua.", "reward": "Huy hiệu \"Đom Đóm Dũng Cảm\".", "vocab": ["hope", "wish", "kind"], "assets": ["camp_lantern", "water_normal"]}]'::jsonb, '{"sizes": {"1-5": "Tất cả học sinh vào Đội Chạy Trốn; Đội Săn Tìm là 2-3 người máy chạy chậm do máy chủ điều khiển, độ khó theo mức của lớp.", "6-20": "Chia 60/40 (ví dụ 12 Chạy Trốn, 8 Săn Tìm). Nhóm 3-4 người cùng màu dây đeo, mỗi nhóm một Đội trưởng.", "21-50": "Chia 60/40 (50 em = 30 Chạy Trốn, 20 Săn Tìm). Tiểu đội 5 người; bản đồ mở rộng 3 khu, mỗi khu một Chuồng Gỗ để không dồn 50 người một chỗ."}, "roles": {"escapers": ["Đội trưởng (giữ bản đồ, chọn đường)", "Trinh sát (dò bụi cây an toàn)", "Thợ giải mã (mật thư)", "Người tìm nước", "Người xóa dấu"], "pursuers": ["Đội trưởng Săn Tìm (chia khu)", "Người dò dấu chân", "Người canh ống nhòm", "Người chạy nhanh", "Người giữ Chuồng Gỗ"]}, "avatars": "12 nhân vật dưới đây là người dẫn chuyện và vai mẫu trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo (không trùng trong lớp) và mặc vest màu đội.", "rules": {"teams": "Đội Chạy Trốn (vest xanh) và Đội Săn Tìm (vest cam). Tỉ lệ 60/40, làm tròn, ít nhất 1 người mỗi đội.", "match": "Một trận liền mạch 30 phút, không chia hiệp. 2 chặng phụ chỉ mở khi gia sư bấm \"Kéo dài\".", "win": "Hết giờ: nếu số Chạy Trốn còn tự do > số bị bắt thì Đội Chạy Trốn thắng; nếu Đội Săn Tìm bắt được hơn 50% thì Đội Săn Tìm thắng; hòa (đúng 50%) thì đội có tổng sao cao hơn thắng.", "stars": "Mỗi nhiệm vụ cho 1-3 sao theo độ chính xác và tốc độ. Điểm = sao × 100 + điểm hành động (bắt, giải cứu, cướp lưới).", "mvp": "MVP đội thắng (điểm cao nhất) nhận thêm 20% tổng điểm của toàn đội thua. Người điểm cao nhất đội thua nhận danh hiệu \"Gương Mặt Quật Cường\".", "capture": "Đội Săn Tìm chạm Lưới Gắn Thẻ vào người Chạy Trốn = bắt. Người bị bắt về Chuồng Gỗ, không bị loại: tiếp tục giải mật thư hỗ trợ đội và có thể được giải cứu.", "snatch": "Người Chạy Trốn lẻn sát sau lưng người Săn Tìm (2 m, không bị nhìn thấy) sẽ hiện nút \"Cướp lưới\": một câu hỏi 8 giây. Đúng: cướp được Lưới, người Săn Tìm mất lưới 45 giây. Sai: vị trí người Chạy Trốn hiện trên bản đồ đội Săn Tìm 5 giây.", "net_power": "Lưới cướp được dùng 3 lần hoặc 60 giây: chạm người Săn Tìm làm họ đứng yên 10 giây (đuổi ngược), hoặc mở Chuồng Gỗ giải cứu 2 đồng đội. Hết lượt, lưới tự về trại Săn Tìm. Người Săn Tìm lấy lại lưới bằng cách chạm người đang cầm.", "pursuer_skills": "Đội Săn Tìm cũng học: mỗi câu đúng nạp một kỹ năng: Quét dấu chân (hiện dấu trong bán kính 15 m, 8 giây), Ống nhòm (soi một bụi cây), Chạy nhanh (5 giây).", "escaper_skills": "Đội Chạy Trốn: câu đúng nạp Xóa dấu (xóa dấu chân 10 giây), Ẩn nấp sâu (không bị Ống nhòm thấy 15 giây), Mồi nhử (tạo dấu chân giả).", "dodge": "Khi bị chạm lưới, người Chạy Trốn có một câu \"Né lưới\" 6 giây, mỗi chặng dùng được 1 lần. Đúng thì thoát.", "safety": "Không có cảnh đau, máu hay vũ khí thật. \"Bị bắt\" = bị gắn thẻ, nhân vật giơ tay cười. Dây thừng chỉ quấn cổng chuồng và ba lô, không trói người.", "no_idle": "Không ai phải ngồi chờ: người bị bắt giải mật thư, người Săn Tìm trả lời để nạp kỹ năng."}, "map_zones": ["Bãi đèn lồng", "Suối trăng", "Cây thông cổ thụ"]}'::jsonb, array['anim_cheer','camp_bottle','camp_lantern','camp_string_lights','char_gamer_boy','decal_footprint_mud','hdri_night','river_branch','river_butterfly','river_reed','river_tree_pine','surv_broom','surv_capture_net','surv_compass','surv_flashlight','surv_holding_pen','surv_letter','surv_pointed_stone','surv_rope','surv_sentinel','surv_sharp_rock','surv_spring','surv_stick','surv_tripwire','watchtower','water_normal']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('surv-03#01', 'surv-03', 1, 'Bác Ba', 'Bảo vệ trại, đánh chuông 12 giờ', 'elder', 'm', 'S3', false, 'E_brown_dark', 'salt_pepper', 'side_part', 'short', false, false, 'casual', 'navy', 'Áo khoác xanh navy, đèn pin đeo đầu', 'flashlight', null, array['whistle','watch']::text[], 'Trọng tài đêm', 'npc');
