insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('surv-03#11', 'surv-03', 11, 'Tuấn Tú', 'Giữ chuồng gỗ, hay hát nhỏ', 'teen', 'm', 'S3', false, 'E_black', 'black', 'short_neat', 'short', false, false, 'casual', 'orange', 'Vest cam, áo len nâu', 'swatter_net', null, array['instrument']::text[], 'Người giữ Chuồng Gỗ', 'pursuers');
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('surv-03#12', 'surv-03', 12, 'Cú Mèo Nâu', 'Đậu trên cây thông cổ thụ, kêu khi có người leo', 'child', 'n', 'S1', false, 'E_green', 'dark_blonde', 'curly', 'shoulder', false, false, 'casual', 'brown', 'Lông nâu đốm trắng', null, null, array['pet_or_toy']::text[], 'Linh vật canh túi lưới', 'npc');
insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('surv-04', 'river_survival', 4, 'Cơn Mưa Trên Sông Đá', 'File: xóa dấu chân trên cát/bùn để đánh lạc hướng; video bờ đá sỏi và rừng ẩm.', 'Giữa buổi chiều, mây đen kéo về, Đội Săn Tìm tranh thủ nhốt nhóm bạn vào chuồng gỗ dưới mái lá chuối. Khi tia chớp đầu tiên lóe lên, Thiên Ân mài đứt dây thừng trên tảng đá sắc và cả nhóm lao vào màn mưa. Mưa là bạn và cũng là thù: mưa xóa dấu chân trên cát nhưng lại in dấu thật sâu trên bùn. Đội phải hứng nước mưa sạch, dựng mái che bằng gậy và lá chuối, giải mật thư bị nhòe nước, và dụ Đội Săn Tìm theo dấu chân giả. Khi sấm nổ lớn, Đội Săn Tìm phải chạy về trại cất lưới, đó là lúc đội Chạy Trốn cướp được lưới để giải cứu bạn bè.', 6, 5, 30, 12, true, 'Bờ sông đá cuội đầu mùa mưa, mây đen kéo từ thượng nguồn, mưa rào từng đợt. Bùn non dọc bờ, lá chuối rừng to như cái ô, sấm rền xa.', '[{"n": 1, "title": "Tia chớp đầu tiên", "minutes": 5, "optional": false, "goal": "Thoát chuồng gỗ khi mưa bắt đầu; Đội Săn Tìm nhận áo mưa cam.", "beats": ["Mỗi tia chớp làm sáng cả bãi 1 giây: ai đang chạy có thể bị thấy.", "Đủ câu đúng thì dây đứt."], "question_hook": "Câu hỏi hiện trên sợi dây ướt mưa.", "reward": "Mở khóa Lá chuối (che mưa, giảm dấu chân).", "vocab": ["rain", "lightning", "thunder", "wet"], "assets": ["surv_holding_pen", "surv_rope", "surv_sharp_rock", "hdri_cloudy", "river_bush"]}, {"n": 2, "title": "Nhiệm vụ 1: Hứng nước mưa", "minutes": 5, "optional": false, "goal": "Đặt ống tre và chậu đá hứng nước mưa sạch; tránh nước bùn chảy tràn.", "beats": ["Chậu đặt dưới mái lá thì sạch, đặt trên đất thì đục.", "Đội Săn Tìm quét dấu trên bùn rõ gấp đôi."], "question_hook": "Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).", "reward": "Bình nước mưa.", "vocab": ["collect", "bowl", "roof", "muddy"], "assets": ["surv_stone_basin", "camp_bucket", "camp_bottle", "tex_mud"]}, {"n": 3, "title": "Nhiệm vụ 2: Mái che gậy và lá", "minutes": 5, "optional": false, "goal": "Gom gậy, đá nhọn và lá chuối dựng mái che, nơi Ống nhòm không soi được.", "beats": ["Mái che chứa tối đa 4 người.", "Bẫy dây vấp đặt quanh mái che."], "question_hook": "Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao). Câu đúng dựng thêm một cây cột.", "reward": "Mái che lá (ẩn nấp sâu).", "vocab": ["shelter", "cover", "leaf", "dry"], "assets": ["surv_stick", "surv_pointed_stone", "surv_tripwire", "camp_tarp", "river_bush"]}, {"n": 4, "title": "Nhiệm vụ 3: Mật thư nhòe nước", "minutes": 5, "optional": false, "goal": "Khôi phục mật thư bị mưa làm nhòe để tìm hang đá khô.", "beats": ["Chữ nhòe ghép lại bằng các câu đúng.", "Người ở chuồng gỗ giúp bằng câu ngữ pháp.", "Mật thư nhòe nước nằm trong trực thăng rơi: đọc câu hỏi trên bảng điều khiển để lấy nó."], "question_hook": "Tờ mật thư nhòe; câu đúng làm khô từng dòng. Hợp câu sửa câu (transform).", "reward": "Lối vào hang đá khô.", "vocab": ["message", "smudge", "dry cave", "under", "wreck", "letter"], "assets": ["surv_letter", "river_cave", "surv_map", "surv_helicopter_wreck"]}, {"n": 5, "title": "Nhiệm vụ 4: Dấu chân giả", "minutes": 5, "optional": false, "goal": "Xóa dấu thật trên bùn và in dấu giả dẫn Đội Săn Tìm ra bãi lau.", "beats": ["Mỗi câu đúng tạo 5 bước dấu giả.", "Sấm lớn: người Săn Tìm phải về trại cất lưới 20 giây, cơ hội cướp lưới.", "Mảnh đất bùn ướt in rõ dấu chân: đội nào xóa dấu đúng chỗ thì đội kia lạc hướng."], "question_hook": "Chổi xóa dấu và Mồi nhử theo câu đúng; nút \"Cướp lưới\".", "reward": "Lưới Gắn Thẻ.", "vocab": ["fake", "trick", "follow", "reed", "mud", "footprint"], "assets": ["surv_broom", "decal_footprint_mud", "decal_footprint_sand", "surv_capture_net", "river_reed", "ground_soil_patch"]}, {"n": 6, "title": "Tạnh mưa", "minutes": 5, "optional": false, "goal": "Mưa tạnh, cầu vồng lên: phút cuối giải cứu và đếm người.", "beats": ["Bùn khô dần, dấu chân mờ đi.", "Kết quả, MVP, Gương Mặt Quật Cường."], "question_hook": "Câu 10 giây trên chuồng gỗ.", "reward": "MVP +20% điểm đội thua.", "vocab": ["stop", "sun", "rainbow", "safe"], "assets": ["surv_holding_pen", "hdri_noon", "anim_cheer"]}, {"n": 7, "title": "Chặng phụ: Lũ nhỏ", "minutes": 5, "optional": true, "goal": "Kéo dài: nước sông dâng, bãi thu hẹp, hai đội dồn vào giữa.", "beats": ["Ai đứng ở bãi thấp phải trả lời để leo lên đá cao."], "question_hook": "Câu hỏi hiện trên Bảng Nhiệm vụ và trên Chuồng Gỗ như trận chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["flood", "rise", "high", "quick"], "assets": ["river_rock_large", "water_foam"]}, {"n": 8, "title": "Chặng phụ: Phơi đồ quanh lửa", "minutes": 5, "optional": true, "goal": "Ôn từ vựng thời tiết quanh đống lửa sưởi.", "beats": ["Mỗi bạn chọn một từ thời tiết và đặt câu."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng bên lửa trại. Câu ôn, không tính thua.", "reward": "Huy hiệu \"Chiến Binh Mưa\".", "vocab": ["weather", "storm", "cloud", "warm"], "assets": ["camp_firepit", "river_woodpile"]}]'::jsonb, '{"sizes": {"1-5": "Tất cả học sinh vào Đội Chạy Trốn; Đội Săn Tìm là 2-3 người máy chạy chậm do máy chủ điều khiển, độ khó theo mức của lớp.", "6-20": "Chia 60/40 (ví dụ 12 Chạy Trốn, 8 Săn Tìm). Nhóm 3-4 người cùng màu dây đeo, mỗi nhóm một Đội trưởng.", "21-50": "Chia 60/40 (50 em = 30 Chạy Trốn, 20 Săn Tìm). Tiểu đội 5 người; bản đồ mở rộng 3 khu, mỗi khu một Chuồng Gỗ để không dồn 50 người một chỗ."}, "roles": {"escapers": ["Đội trưởng (giữ bản đồ, chọn đường)", "Trinh sát (dò bụi cây an toàn)", "Thợ giải mã (mật thư)", "Người tìm nước", "Người xóa dấu"], "pursuers": ["Đội trưởng Săn Tìm (chia khu)", "Người dò dấu chân", "Người canh ống nhòm", "Người chạy nhanh", "Người giữ Chuồng Gỗ"]}, "avatars": "12 nhân vật dưới đây là người dẫn chuyện và vai mẫu trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo (không trùng trong lớp) và mặc vest màu đội.", "rules": {"teams": "Đội Chạy Trốn (vest xanh) và Đội Săn Tìm (vest cam). Tỉ lệ 60/40, làm tròn, ít nhất 1 người mỗi đội.", "match": "Một trận liền mạch 30 phút, không chia hiệp. 2 chặng phụ chỉ mở khi gia sư bấm \"Kéo dài\".", "win": "Hết giờ: nếu số Chạy Trốn còn tự do > số bị bắt thì Đội Chạy Trốn thắng; nếu Đội Săn Tìm bắt được hơn 50% thì Đội Săn Tìm thắng; hòa (đúng 50%) thì đội có tổng sao cao hơn thắng.", "stars": "Mỗi nhiệm vụ cho 1-3 sao theo độ chính xác và tốc độ. Điểm = sao × 100 + điểm hành động (bắt, giải cứu, cướp lưới).", "mvp": "MVP đội thắng (điểm cao nhất) nhận thêm 20% tổng điểm của toàn đội thua. Người điểm cao nhất đội thua nhận danh hiệu \"Gương Mặt Quật Cường\".", "capture": "Đội Săn Tìm chạm Lưới Gắn Thẻ vào người Chạy Trốn = bắt. Người bị bắt về Chuồng Gỗ, không bị loại: tiếp tục giải mật thư hỗ trợ đội và có thể được giải cứu.", "snatch": "Người Chạy Trốn lẻn sát sau lưng người Săn Tìm (2 m, không bị nhìn thấy) sẽ hiện nút \"Cướp lưới\": một câu hỏi 8 giây. Đúng: cướp được Lưới, người Săn Tìm mất lưới 45 giây. Sai: vị trí người Chạy Trốn hiện trên bản đồ đội Săn Tìm 5 giây.", "net_power": "Lưới cướp được dùng 3 lần hoặc 60 giây: chạm người Săn Tìm làm họ đứng yên 10 giây (đuổi ngược), hoặc mở Chuồng Gỗ giải cứu 2 đồng đội. Hết lượt, lưới tự về trại Săn Tìm. Người Săn Tìm lấy lại lưới bằng cách chạm người đang cầm.", "pursuer_skills": "Đội Săn Tìm cũng học: mỗi câu đúng nạp một kỹ năng: Quét dấu chân (hiện dấu trong bán kính 15 m, 8 giây), Ống nhòm (soi một bụi cây), Chạy nhanh (5 giây).", "escaper_skills": "Đội Chạy Trốn: câu đúng nạp Xóa dấu (xóa dấu chân 10 giây), Ẩn nấp sâu (không bị Ống nhòm thấy 15 giây), Mồi nhử (tạo dấu chân giả).", "dodge": "Khi bị chạm lưới, người Chạy Trốn có một câu \"Né lưới\" 6 giây, mỗi chặng dùng được 1 lần. Đúng thì thoát.", "safety": "Không có cảnh đau, máu hay vũ khí thật. \"Bị bắt\" = bị gắn thẻ, nhân vật giơ tay cười. Dây thừng chỉ quấn cổng chuồng và ba lô, không trói người.", "no_idle": "Không ai phải ngồi chờ: người bị bắt giải mật thư, người Săn Tìm trả lời để nạp kỹ năng."}, "map_zones": ["Bãi đá cuội", "Rừng chuối", "Bãi lau sậy"]}'::jsonb, array['anim_cheer','camp_bottle','camp_bucket','camp_firepit','camp_tarp','decal_footprint_mud','decal_footprint_sand','ground_soil_patch','hdri_cloudy','hdri_noon','river_bush','river_cave','river_reed','river_rock_large','river_woodpile','surv_broom','surv_capture_net','surv_helicopter_wreck','surv_holding_pen','surv_letter','surv_map','surv_pointed_stone','surv_rope','surv_sharp_rock','surv_stick','surv_stone_basin','surv_tripwire','tex_mud','water_foam']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
