insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('surv-04#11', 'surv-04', 11, 'Thanh Tâm', 'Giữ chuồng gỗ dưới mái lá', 'teen', 'f', 'S2', false, 'E_black', 'black', 'twin_buns', 'shoulder', false, false, 'casual', 'orange', 'Áo mưa cam, khăn quàng', 'swatter_net', null, array['necklace']::text[], 'Người giữ Chuồng Gỗ', 'pursuers');
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('surv-04#12', 'surv-04', 12, 'Ếch Xanh', 'Kêu "ộp" báo hiệu sắp sấm', 'child', 'n', 'S3', false, 'E_brown_dark', 'dark_brown', 'bob', 'short', false, false, 'casual', 'green', 'Da xanh bóng', null, null, array['pet_or_toy']::text[], 'Linh vật báo sấm', 'npc');
insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('surv-05', 'river_survival', 5, 'Đảo Lau Sậy Giữa Dòng', 'File: khu rừng sông dã ngoại hẻo lánh; video thuyền nhôm và mặt nước ngọc.', 'Đội Săn Tìm đưa nhóm bạn ra cù lao bằng thuyền nhôm, nhốt vào chuồng gỗ cạnh bến rồi chèo đi giấu bè. Quỳnh Như tìm được mảnh đá sắc trong bãi sỏi, mài đứt dây và dẫn cả nhóm vào rừng lau cao quá đầu. Đảo không có suối, nên phải tìm giếng đá cổ của người đánh cá; phải gom gậy làm bè nhỏ, giải mật thư của ông lái đò Tư để biết bến nào an toàn, và xóa vệt đi trong lau. Đội Săn Tìm đi tuần bằng thuyền quanh đảo, dùng ống nhòm từ mặt nước. Lưới Gắn Thẻ dự phòng nằm trên chiếc thuyền neo ở bến cũ; ai bơi bè tới được sẽ đổi vai và giải cứu cả đội.', 6, 5, 30, 12, true, 'Một cù lao lau sậy giữa sông rộng, nối với bờ bằng bè tre và bến gỗ cũ. Nắng chiều gay gắt rồi dịu dần, sóng vỗ vào thuyền nhôm, chim cò bay ngang. Cù lao nhìn từ xa có cọ và gốc cây cổ, thuyền chèo neo cạnh bến.', '[{"n": 1, "title": "Bến cũ cù lao", "minutes": 5, "optional": false, "goal": "Thoát chuồng gỗ ở bến; Đội Săn Tìm lên thuyền đi tuần.", "beats": ["Tiếng sóng vỗ, thuyền nhôm rời bến.", "Đủ câu đúng thì dây đứt.", "Cù lao lau sậy nhìn từ bến cũ: nhận mặt các điểm nhiệm vụ.", "Cô lái đò giải thích luật cù lao cho cả hai đội trước khi cho lên bến."], "question_hook": "Câu hỏi trên sợi dây buộc cổng chuồng.", "reward": "Mở khóa đường vào rừng lau.", "vocab": ["island", "boat", "reed", "shore", "dock", "ferry", "guide"], "assets": ["surv_holding_pen", "surv_rope", "surv_sharp_rock", "river_dock", "river_boat_aluminium", "river_reed", "mini_large_island", "char_generic_female_2"]}, {"n": 2, "title": "Nhiệm vụ 1: Giếng đá người đánh cá", "minutes": 5, "optional": false, "goal": "Tìm giếng đá cổ có nước ngọt; nước sông mặn phù sa không uống được.", "beats": ["Ba giếng, một giếng cạn, một giếng có rêu, một giếng nước trong.", "Thuyền tuần soi ống nhòm vào bờ.", "Tường đá và gỗ quanh giếng làm Chuồng Gỗ của cù lao: tìm chỗ hở để giải cứu."], "question_hook": "Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).", "reward": "Bình nước ngọt.", "vocab": ["well", "fresh water", "deep", "bucket", "stone wall", "pen"], "assets": ["surv_stone_basin", "camp_bucket", "river_rock_medium", "surv_pen_wall_stone"]}, {"n": 3, "title": "Nhiệm vụ 2: Bè gậy", "minutes": 5, "optional": false, "goal": "Gom gậy và dây làm bè nhỏ để qua lạch nước.", "beats": ["Bè chở 2 người, đi chậm.", "Bẫy dây vấp đặt ở bờ lạch."], "question_hook": "Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao). Mỗi câu đúng buộc thêm một thanh gậy vào bè.", "reward": "Bè gậy.", "vocab": ["raft", "tie", "float", "paddle"], "assets": ["surv_stick", "surv_rope", "surv_tripwire", "river_driftwood", "river_boat_row"]}, {"n": 4, "title": "Nhiệm vụ 3: Mật thư ông lái đò", "minutes": 5, "optional": false, "goal": "Giải mật thư trong chai trôi dạt để biết bến nào an toàn.", "beats": ["Chai trôi dạt vào bãi; mật thư ghi giờ thủy triều và hướng bến.", "Người ở chuồng gỗ đọc tiếp."], "question_hook": "Mật thư trong chai; câu đúng gỡ từng dòng. Hợp câu đọc hiểu ngắn.", "reward": "Bến an toàn.", "vocab": ["bottle", "tide", "east", "safe"], "assets": ["surv_letter", "surv_map", "surv_compass", "camp_bottle"]}, {"n": 5, "title": "Nhiệm vụ 4: Vệt lau và thuyền neo", "minutes": 5, "optional": false, "goal": "Dựng lại lau bị rẽ để xóa vệt; chèo bè tới thuyền neo lấy Lưới Gắn Thẻ.", "beats": ["Vệt lau rẽ hiện rõ từ thuyền tuần.", "Lấy lưới trên thuyền cần 3 câu đúng liên tiếp.", "Thuyền chèo neo cạnh bờ chứa thùng lưới; chỉ cướp được khi đọc đúng tên các món trên thuyền.", "Nỏ lưới kiểu hoạt hình đặt cạnh thuyền neo: cướp được khi đọc đúng tên ba bộ phận."], "question_hook": "Mỗi câu đúng dựng lại một khóm lau; nút \"Cướp lưới\".", "reward": "Lưới Gắn Thẻ.", "vocab": ["hide", "trail", "anchor", "swim", "rowboat", "launcher", "net"], "assets": ["river_reed", "surv_capture_net", "river_boat_aluminium", "decal_footprint_sand", "river_boat_row", "surv_net_launcher_b"]}, {"n": 6, "title": "Hoàng hôn trên cù lao", "minutes": 5, "optional": false, "goal": "Phút cuối giải cứu, đếm người khi mặt trời chạm sông.", "beats": ["Chim cò bay về tổ.", "MVP và Gương Mặt Quật Cường.", "Phao cứu sinh treo ở bến là mốc để đội đếm người cuối trận."], "question_hook": "Câu 10 giây trên chuồng gỗ và trên thuyền tuần.", "reward": "MVP +20% điểm đội thua.", "vocab": ["sunset", "island", "together", "lifebuoy"], "assets": ["surv_holding_pen", "hdri_sunset", "river_birds", "anim_cheer", "river_buoy"]}, {"n": 7, "title": "Chặng phụ: Nước ròng", "minutes": 5, "optional": true, "goal": "Kéo dài: nước rút lộ bãi cát mới, đường trốn thay đổi.", "beats": ["Bãi cát mới in dấu chân rất rõ."], "question_hook": "Câu hỏi hiện trên Bảng Nhiệm vụ và trên Chuồng Gỗ như trận chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["low tide", "sandbar"], "assets": ["tex_sand", "decal_footprint_sand"]}, {"n": 8, "title": "Chặng phụ: Chuyến đò về", "minutes": 5, "optional": true, "goal": "Cả lớp lên đò về bờ, ông Tư hỏi bài.", "beats": ["Ai trả lời đúng được cầm lái đò một đoạn."], "question_hook": "Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng bên lửa trại. Câu ôn, không tính thua.", "reward": "Huy hiệu \"Thủ Lĩnh Cù Lao\".", "vocab": ["ferry", "home", "thank you"], "assets": ["river_boat_row", "river_dock"]}]'::jsonb, '{"sizes": {"1-5": "Tất cả học sinh vào Đội Chạy Trốn; Đội Săn Tìm là 2-3 người máy chạy chậm do máy chủ điều khiển, độ khó theo mức của lớp.", "6-20": "Chia 60/40 (ví dụ 12 Chạy Trốn, 8 Săn Tìm). Nhóm 3-4 người cùng màu dây đeo, mỗi nhóm một Đội trưởng.", "21-50": "Chia 60/40 (50 em = 30 Chạy Trốn, 20 Săn Tìm). Tiểu đội 5 người; bản đồ mở rộng 3 khu, mỗi khu một Chuồng Gỗ để không dồn 50 người một chỗ."}, "roles": {"escapers": ["Đội trưởng (giữ bản đồ, chọn đường)", "Trinh sát (dò bụi cây an toàn)", "Thợ giải mã (mật thư)", "Người tìm nước", "Người xóa dấu"], "pursuers": ["Đội trưởng Săn Tìm (chia khu)", "Người dò dấu chân", "Người canh ống nhòm", "Người chạy nhanh", "Người giữ Chuồng Gỗ"]}, "avatars": "12 nhân vật dưới đây là người dẫn chuyện và vai mẫu trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo (không trùng trong lớp) và mặc vest màu đội.", "rules": {"teams": "Đội Chạy Trốn (vest xanh) và Đội Săn Tìm (vest cam). Tỉ lệ 60/40, làm tròn, ít nhất 1 người mỗi đội.", "match": "Một trận liền mạch 30 phút, không chia hiệp. 2 chặng phụ chỉ mở khi gia sư bấm \"Kéo dài\".", "win": "Hết giờ: nếu số Chạy Trốn còn tự do > số bị bắt thì Đội Chạy Trốn thắng; nếu Đội Săn Tìm bắt được hơn 50% thì Đội Săn Tìm thắng; hòa (đúng 50%) thì đội có tổng sao cao hơn thắng.", "stars": "Mỗi nhiệm vụ cho 1-3 sao theo độ chính xác và tốc độ. Điểm = sao × 100 + điểm hành động (bắt, giải cứu, cướp lưới).", "mvp": "MVP đội thắng (điểm cao nhất) nhận thêm 20% tổng điểm của toàn đội thua. Người điểm cao nhất đội thua nhận danh hiệu \"Gương Mặt Quật Cường\".", "capture": "Đội Săn Tìm chạm Lưới Gắn Thẻ vào người Chạy Trốn = bắt. Người bị bắt về Chuồng Gỗ, không bị loại: tiếp tục giải mật thư hỗ trợ đội và có thể được giải cứu.", "snatch": "Người Chạy Trốn lẻn sát sau lưng người Săn Tìm (2 m, không bị nhìn thấy) sẽ hiện nút \"Cướp lưới\": một câu hỏi 8 giây. Đúng: cướp được Lưới, người Săn Tìm mất lưới 45 giây. Sai: vị trí người Chạy Trốn hiện trên bản đồ đội Săn Tìm 5 giây.", "net_power": "Lưới cướp được dùng 3 lần hoặc 60 giây: chạm người Săn Tìm làm họ đứng yên 10 giây (đuổi ngược), hoặc mở Chuồng Gỗ giải cứu 2 đồng đội. Hết lượt, lưới tự về trại Săn Tìm. Người Săn Tìm lấy lại lưới bằng cách chạm người đang cầm.", "pursuer_skills": "Đội Săn Tìm cũng học: mỗi câu đúng nạp một kỹ năng: Quét dấu chân (hiện dấu trong bán kính 15 m, 8 giây), Ống nhòm (soi một bụi cây), Chạy nhanh (5 giây).", "escaper_skills": "Đội Chạy Trốn: câu đúng nạp Xóa dấu (xóa dấu chân 10 giây), Ẩn nấp sâu (không bị Ống nhòm thấy 15 giây), Mồi nhử (tạo dấu chân giả).", "dodge": "Khi bị chạm lưới, người Chạy Trốn có một câu \"Né lưới\" 6 giây, mỗi chặng dùng được 1 lần. Đúng thì thoát.", "safety": "Không có cảnh đau, máu hay vũ khí thật. \"Bị bắt\" = bị gắn thẻ, nhân vật giơ tay cười. Dây thừng chỉ quấn cổng chuồng và ba lô, không trói người.", "no_idle": "Không ai phải ngồi chờ: người bị bắt giải mật thư, người Săn Tìm trả lời để nạp kỹ năng."}, "map_zones": ["Bến cũ", "Rừng lau", "Bãi giếng đá"], "note": "Đội Săn Tìm đi tuần bằng 2 thuyền (tối đa 6 người/thuyền); số còn lại tuần trên bờ."}'::jsonb, array['anim_cheer','camp_bottle','camp_bucket','char_generic_female_2','decal_footprint_sand','hdri_sunset','mini_large_island','river_birds','river_boat_aluminium','river_boat_row','river_buoy','river_dock','river_driftwood','river_reed','river_rock_medium','surv_capture_net','surv_compass','surv_holding_pen','surv_letter','surv_map','surv_net_launcher_b','surv_pen_wall_stone','surv_rope','surv_sharp_rock','surv_stick','surv_stone_basin','surv_tripwire','tex_sand']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
