insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('dino-01', 'dino_journey', 1, 'Quả Trứng Trên Đồng Cỏ', 'Mở đầu saga: khủng long con nở ra, tập đi, học nhận biết đồng cỏ cùng cha (phim hoạt hình sinh tồn nhẹ nhàng, không bạo lực).', 'Sáng nay, quả trứng cuối cùng của bầy bắt đầu nứt. Bố Gruk đứng canh bên tổ, cô Đuôi Dài và cả bầy nín thở chờ. Chú khủng long con Mốc chui ra, ngơ ngác nhìn đồng cỏ lần đầu tiên. Mỗi chặng, Mốc học một điều để sống: đứng vững, nhận ra cha, gọi tên bạn cùng bầy, uống nước an toàn, biết tiếng gầm nào là báo động. Mỗi vật phát sáng trên đồng cỏ chứa một câu hỏi, đúng thì Mốc làm được việc đó. Hoàng hôn xuống, Mốc phải chạy một mình về tổ trước khi trời tối. Cha đứng ở cuối đường, và đó là lần đầu Mốc nghe cha gọi tên mình.', 6, 5, 30, 12, true, 'Đồng cỏ xanh trải dài lúc rạng đông, sương còn đọng trên ngọn cỏ cao. Quả trứng nằm trong tổ lót lá bên túp da cổ, quanh đó là hồ nước nhỏ, hàng cọ và những tảng đá phủ rêu. Xa xa là cao nguyên đỏ.', '[{"n": 1, "title": "Quả trứng nứt", "minutes": 5, "optional": false, "goal": "Giúp Mốc phá vỏ trứng và chui ra khỏi tổ.", "beats": ["Mỗi câu đúng làm vỏ trứng nứt thêm một đường.", "Bố Gruk đỡ nhẹ vỏ trứng, bầy đứng quanh nhìn."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Quả trứng sáng lên mỗi khi bạn đứng cạnh.", "reward": "Mốc nở ra và có tên.", "vocab": ["egg", "crack", "baby", "nest", "shell"], "assets": ["dino_nest_shelter", "tree_nursery_pot", "wood_plank_a", "ground_grass_patch", "mushrooms", "hdri_dawn"], "subtitles": [{"en": "The egg is starting to crack.", "vi": "Có tiếng nứt! quả trứng đang nứt ra.", "parts": ["Có tiếng nứt! ", ["egg", "quả trứng", 0], " đang ", ["crack", "nứt ra", 1], "."]}, {"en": "Welcome, little one! You have a warm nest.", "vi": "Chào bé con! Mẹ thiên nhiên cho con một tổ ấm.", "parts": ["Chào ", ["baby", "bé con", 0], "! Mẹ thiên nhiên cho con một ", ["nest", "tổ", 1], " ấm."]}]}, {"n": 2, "title": "Bước chân đầu tiên", "minutes": 5, "optional": false, "goal": "Tập đứng, tập đi, theo dấu chân cha trên cỏ.", "beats": ["Mốc loạng choạng, mỗi câu đúng đi vững thêm một bước.", "Bố Gruk bước chậm để dấu chân cha in rõ cho con theo."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Dấu chân cha sáng dần lên, chạm đúng dấu kế tiếp.", "reward": "Mốc đi vững.", "vocab": ["walk", "follow", "step", "dad", "grass"], "assets": ["dino_trex_brown", "ground_grass_tuft", "ground_grass_block", "river_grass_tall", "river_butterfly", "anim_wave"], "subtitles": [{"en": "Dad walks slowly and Moc follows every step.", "vi": "Bố bước chậm, Mốc bước theo từng bước chân.", "parts": [["Dad", "Bố", 0], " bước chậm, Mốc ", ["follow", "bước theo", 1], " từng ", ["step", "bước chân", 1], "."]}, {"en": "Do not be afraid! It is only grass.", "vi": "Đừng sợ! Cỏ cao chỉ cỏ thôi.", "parts": ["Đừng sợ! Cỏ cao chỉ ", ["grass", "cỏ", 0], " thôi."]}]}, {"n": 3, "title": "Gặp bầy nhỏ", "minutes": 5, "optional": false, "goal": "Gọi tên các bạn cùng bầy: Sừng, Gai, Chân Dài.", "beats": ["Mỗi bạn có một đặc điểm; gọi đúng thì bạn chạy tới chơi cùng.", "Cô Đuôi Dài dạy cách chào bằng cái chạm mũi."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi bạn nhỏ là một thẻ từ: nối đúng tên và đặc điểm.", "reward": "Ba bạn mới.", "vocab": ["friend", "horn", "tail", "big", "small"], "assets": ["dino_triceratops", "dino_stegosaurus", "ground_clearing", "tree_x01", "tree_x02", "anim_cheer"], "subtitles": [{"en": "This is a new friend with a big horn.", "vi": "Đây là bạn mới: cậu ấy có một cái sừng to.", "parts": ["Đây là ", ["friend", "bạn", 0], " mới: cậu ấy có một cái ", ["horn", "sừng", 2], " ", ["big", "to", 0], "."]}, {"en": "That one has a small tail full of spikes.", "vi": "Cậu kia thì có cái đuôi đầy gai nhỏ.", "parts": ["Cậu kia thì có cái ", ["tail", "đuôi", 1], " đầy gai ", ["small", "nhỏ", 0], "."]}]}, {"n": 4, "title": "Uống nước lần đầu", "minutes": 5, "optional": false, "goal": "Tới hồ nước, nhận biết nước sạch và nước đục.", "beats": ["Cô Đuôi Dài chỉ nước trong, nước đục nổi bọt thì tránh.", "Mốc cúi đầu uống từng ngụm nhỏ, cả bầy canh xung quanh."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Vũng nước nào đúng thì sáng xanh.", "reward": "Mốc biết chọn nước.", "vocab": ["water", "drink", "clean", "muddy", "lake"], "assets": ["mini_azure_river", "river_lilypad", "river_reed", "palm_a", "palm_b", "river_pebbles"], "subtitles": [{"en": "The water is clean, drink up, little one!", "vi": "Nước sạch trong vắt, uống đi con!", "parts": ["Nước ", ["clean", "sạch", 1], " trong vắt, ", ["drink", "uống", 0], " đi con!"]}, {"en": "This one is muddy, do not drink it.", "vi": "Còn vũng này đục lắm, đừng uống.", "parts": ["Còn vũng này ", ["muddy", "đục", 2], " lắm, đừng ", ["drink", "uống", 0], "."]}]}, {"n": 5, "title": "Tiếng gầm báo động", "minutes": 5, "optional": false, "goal": "Phân biệt tiếng gầm vui, gọi bầy và báo nguy.", "beats": ["Ba tiếng gầm khác nhau vang lên từ vách đá; nghe đúng thì Mốc phản ứng đúng.", "Một bóng tối lướt qua trên cao, hóa ra là con chim lớn."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi tiếng gầm là một câu nghe, chọn đúng ý nghĩa của nó.", "reward": "Mốc biết nghe báo động.", "vocab": ["roar", "danger", "listen", "safe", "run"], "assets": ["river_cliff", "river_rock_large", "river_rock_medium", "river_birds", "tree_x03", "tree_x04"], "subtitles": [{"en": "Listen! This roar means danger.", "vi": "Nghe! Tiếng gầm này nghĩa là nguy hiểm.", "parts": [["Listen", "Nghe", 1], "! Tiếng gầm này nghĩa là ", ["danger", "nguy hiểm", 2], "."]}, {"en": "Everyone run to a safe place!", "vi": "Mọi người chạy về chỗ an toàn nào!", "parts": ["Mọi người ", ["run", "chạy", 0], " về chỗ ", ["safe", "an toàn", 1], " nào!"]}]}, {"n": 6, "title": "Chạy về tổ trước hoàng hôn", "minutes": 5, "optional": false, "goal": "Một mình chạy về tổ qua bãi cỏ khi trời sắp tối.", "beats": ["Đường chạy thẳng băng, mỗi câu đúng tăng tốc, sai thì vấp nhẹ.", "Bố Gruk đứng ở cuối đường và gọi tên Mốc lần đầu."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Ba đoạn đường, mỗi đoạn một câu; đúng cả ba thì về kịp.", "reward": "Tên Mốc và huy hiệu \"Bước Chạy Đầu\".", "vocab": ["home", "night", "fast", "name", "proud"], "assets": ["ground_strip_6x20", "ground_grass_iso", "tree_x05", "tree_x06_duo", "dino_nest_shelter", "hdri_sunset"], "subtitles": [{"en": "It is getting dark, run home fast!", "vi": "Trời sắp tối, chạy nhanh về nhà thôi!", "parts": ["Trời sắp tối, chạy ", ["fast", "nhanh", 1], " về ", ["home", "nhà", 0], " thôi!"]}, {"en": "\"Moc!\" Dad calls his name. He is so proud.", "vi": "\"Mốc!\" Cha gọi tên con. Cha thật tự hào.", "parts": ["\"", ["Moc", "Mốc", 0], "!\" Cha gọi tên con. Cha thật ", ["proud", "tự hào", 3], "."]}]}, {"n": 7, "title": "Chặng phụ: Đếm sao bên ổ", "minutes": 5, "optional": true, "goal": "Nằm cạnh cha, đếm sao và học các con số.", "beats": ["Mỗi câu đúng một ngôi sao hiện lên."], "question_hook": "Câu hỏi hiện trên vật thể phát sáng trên đồng cỏ như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["star", "count", "sleep"], "assets": ["tree_pixel", "hdri_night"], "subtitles": [{"en": "One, two, three... what stars!", "vi": "Một, hai, ba... ngôi sao ơi!", "parts": ["Một, hai, ba... ", ["star", "ngôi sao", 0], " ơi!"]}]}, {"n": 8, "title": "Chặng phụ: Nhật ký khủng long con", "minutes": 5, "optional": true, "goal": "Nói hoặc chọn một câu về ngày đầu tiên của em.", "beats": ["Dòng nhật ký được khắc lên một tảng đá cạnh ổ."], "question_hook": "Câu viết ngắn, chấm theo tiêu chí, không tính thua.", "reward": "Huy hiệu \"Ngày Đầu Đời\".", "vocab": ["today", "happy", "first"], "assets": ["tree_pixel_stylized"], "subtitles": [{"en": "Today I am very happy.", "vi": "Hôm nay con rất vui.", "parts": ["Hôm nay con rất ", ["happy", "vui", 1], "."]}]}]'::jsonb, '{"sizes": {"1-5": "Chơi một mình: em đóng chính chú khủng long con Mốc (tự đặt tên, chọn loài và màu); cha Gruk và cả bầy do máy điều khiển. Có 2-5 bạn thì mỗi bạn là một khủng long con trong bầy của em.", "6-20": "Mỗi em là một khủng long con trong bầy: chọn loài và màu. Bầy chia 3-4 nhóm (4-5 em/nhóm), mỗi nhóm đi sau một khủng long lớn do máy dẫn đường; nhóm trả lời đúng nhiều thì cả bầy đi nhanh hơn và chọn được lối tắt.", "21-50": "Bầy lớn: 8-10 nhóm 5 em cùng đi trên một đường mòn nhưng chia 2 bãi cỏ cạnh nhau để không đông; thanh \"Dũng cảm cả bầy\" dùng chung. Mỗi máy chỉ vẽ 8 khủng long gần nhất và tên bạn trong nhóm để máy yếu vẫn mượt."}, "roles": ["Khủng long con đi đầu (đọc dấu chân)", "Người canh gió (báo nguy hiểm)", "Người tìm nước", "Người giữ trứng và tổ", "Chim đưa tin của bầy (báo tin cho cả nhóm)"], "scoring": "Mỗi việc đúng = 1-3 sao theo độ chính xác và tốc độ. Thanh \"Dũng cảm cả bầy\" là thanh Boss chung: cả lớp cùng lấp đầy; nhóm nhiều sao nhất được cha khen và đi đầu đàn ở chặng sau.", "avatars": "Chế độ một mình: nhân vật là chú khủng long con Mốc. Chế độ lớp: mỗi học sinh một khủng long con, chọn loài (T-rex, Raptor, Triceratops, Stegosaurus, Diplodocus, Sauropod) và màu; trùng loài được, khác màu. 12 nhân vật dưới đây là cha, người lớn, bạn nhỏ và muông thú trong câu chuyện.", "species": {"trex": "dino_trex_brown", "raptor": "dino_raptor_rider", "triceratops": "dino_triceratops", "stegosaurus": "dino_stegosaurus", "diplodocus": "dino_diplodocus", "sauropod": "dino_sauropod_grey"}, "safety": "Không máu, không cảnh đau. Cảnh bắt nạt chỉ là xô đẩy, gầm gừ và chặn đường; ai \"ngã\" chỉ ngồi xuống, đứng dậy được. Săn mồi dùng hoạt ảnh vồ mồi rồi cắt cảnh; thú nhỏ luôn chạy thoát hoặc \"ngủ\" một lát, không bị làm hại.", "subtitle_rule": "Mức Beginner: toàn tiếng Việt. Mức A1 đến B2: từ có bậc thấp hơn mức đang chọn hiện tiếng Anh, từ còn lại tiếng Việt. Mức C1: toàn tiếng Anh."}'::jsonb, array['anim_cheer','anim_wave','dino_antelope','dino_diplodocus','dino_nest_shelter','dino_rabbit','dino_raptor_rider','dino_rat','dino_sauropod_grey','dino_stegosaurus','dino_trex_brown','dino_triceratops','dino_wolf_a','dino_wolf_b','ground_clearing','ground_grass_block','ground_grass_iso','ground_grass_patch','ground_grass_tuft','ground_strip_6x20','hdri_dawn','hdri_night','hdri_sunset','mini_azure_river','mushrooms','palm_a','palm_b','river_birds','river_butterfly','river_cliff','river_grass_tall','river_lilypad','river_pebbles','river_reed','river_rock_large','river_rock_medium','tree_nursery_pot','tree_pixel','tree_pixel_stylized','tree_x01','tree_x02','tree_x03','tree_x04','tree_x05','tree_x06_duo','wood_plank_a']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
