insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('dino-02', 'dino_journey', 2, 'Bài Học Săn Mồi', 'Chương 2 của saga: cha dạy con đọc dấu chân, nằm im trong cỏ, theo gió, vồ mồi và chia mồi cho bầy (nhẹ nhàng, không cảnh đau).', 'Mốc đã chạy vững, hôm nay Bố Gruk dẫn Mốc ra đồng cỏ xa hơn để học cách tự kiếm ăn. Cha chỉ cho Mốc đọc dấu chân trên bùn: dấu nào của thỏ, của linh dương, của chuột. Rồi hai cha con nằm im trong cỏ, đổi hướng theo gió để mồi không phát hiện. Mỗi lần săn, Mốc phải trả lời đúng mới vồ trúng; sai thì mồi chạy thoát và cha chỉ cười. Săn xong, cha dạy Mốc chia mồi cho cả bầy, kể cả Lông Xù đang đói. Mốc hiểu: săn giỏi không phải để giành phần mình, mà để bầy không ai bị đói.', 6, 5, 30, 12, true, 'Đồng cỏ rộng giữa trưa, cỏ cao đến bụng, gió thổi thành từng đợt sóng. Có bãi bùn mềm in dấu chân, lùm cây thưa, vài khối đá lớn làm chỗ nấp.', '[{"n": 1, "title": "Dấu chân trên bùn", "minutes": 5, "optional": false, "goal": "Đọc dấu chân và đoán con vật đã đi qua.", "beats": ["Dấu chân in rõ trên bãi bùn, to nhỏ khác nhau.", "Bố Gruk chỉ vết ba ngón, vết hai ngón."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi dấu chân là một câu nối đúng tên con vật.", "reward": "Mốc đọc được dấu chân.", "vocab": ["footprint", "mud", "rabbit", "track", "small"], "assets": ["ground_soil_patch", "dino_rabbit", "river_pebbles", "river_pebbles__alt1", "tree_x07_elm", "hdri_noon"], "subtitles": [{"en": "Look, a footprint in the mud.", "vi": "Nhìn kìa, một dấu chân trên bùn.", "parts": ["Nhìn kìa, một ", ["footprint", "dấu chân", 2], " trên ", ["mud", "bùn", 2], "."]}, {"en": "A small print like this belongs to a rabbit.", "vi": "Dấu nhỏ thế này là của một con thỏ.", "parts": ["Dấu ", ["small", "nhỏ", 0], " thế này là của một con ", ["rabbit", "thỏ", 1], "."]}]}, {"n": 2, "title": "Nằm im trong cỏ", "minutes": 5, "optional": false, "goal": "Ẩn mình trong cỏ cao để mồi không thấy.", "beats": ["Cỏ cao che kín, mỗi câu đúng làm Mốc nằm im thêm một nhịp.", "Bố Gruk thì thầm: chỉ thở nhẹ thôi."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trong bụi cỏ rung rinh.", "reward": "Mốc nấp giỏi.", "vocab": ["hide", "quiet", "tall grass", "still", "breathe"], "assets": ["river_grass_tall", "ground_grass_dark", "dino_antelope", "river_bush", "river_fern"], "subtitles": [{"en": "Stay still and hide in the tall grass.", "vi": "Nằm yên và nấp trong cỏ cao nhé.", "parts": ["Nằm yên và ", ["hide", "nấp", 1], " trong cỏ cao nhé."]}, {"en": "You must be quiet, do not breathe hard.", "vi": "Phải thật im lặng, đừng thở mạnh.", "parts": ["Phải thật ", ["quiet", "im lặng", 1], ", đừng ", ["breathe", "thở", 3], " mạnh."]}]}, {"n": 3, "title": "Theo hướng gió", "minutes": 5, "optional": false, "goal": "Đổi hướng tiếp cận ngược gió để mồi không ngửi thấy mùi.", "beats": ["Cánh bướm và lá bay cho biết hướng gió.", "Cha đứng đầu hướng gió, con đứng sau."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Hướng gió là một mũi tên, chọn đúng hướng mới tiến lên.", "reward": "Mốc đi ngược gió.", "vocab": ["wind", "left", "right", "smell", "against"], "assets": ["tree_x08_verdant", "tree_x09_lone", "river_butterfly__alt1", "dino_rat", "ground_grass_emerald"], "subtitles": [{"en": "The wind blows from left to right.", "vi": "Gió thổi từ bên trái sang bên phải.", "parts": [["Wind", "Gió", 1], " thổi từ bên ", ["left", "trái", 0], " sang bên ", ["right", "phải", 0], "."]}, {"en": "The prey will smell us if we go the wrong way.", "vi": "Mồi sẽ ngửi thấy mùi của ta nếu đi sai hướng.", "parts": ["Mồi sẽ ngửi thấy ", ["smell", "mùi", 2], " của ta nếu đi sai hướng."]}]}, {"n": 4, "title": "Cú vồ đầu tiên", "minutes": 5, "optional": false, "goal": "Vồ trúng con mồi nhỏ đúng thời điểm.", "beats": ["Thanh nhịp: bấm đúng lúc câu đúng, cú vồ trúng.", "Con mồi bị trượt chỉ chạy đi, không có ai đau."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện ngay trên con mồi trước cú vồ.", "reward": "Bữa ăn đầu tiên Mốc tự kiếm.", "vocab": ["jump", "catch", "quick", "prey", "miss"], "assets": ["dino_rat", "dino_rabbit", "ground_grass_iso", "ground_grass_block", "tree_x10_ancient_a"], "subtitles": [{"en": "Wait... jump! Did you catch it or miss it?", "vi": "Chờ đã... nhảy lên! Bắt được rồi hay trượt?", "parts": ["Chờ đã... ", ["jump", "nhảy", 1], " lên! Bắt được rồi hay ", ["miss", "trượt", 2], "?"]}, {"en": "The prey is quick, so you must be accurate.", "vi": "Con mồi chạy rất nhanh, phải thật chính xác.", "parts": ["Con mồi chạy rất ", ["quick", "nhanh", 1], ", phải thật chính xác."]}]}, {"n": 5, "title": "Chia mồi cho bầy", "minutes": 5, "optional": false, "goal": "Mang mồi về và chia công bằng, kể cả cho Lông Xù.", "beats": ["Cha chia thành các phần đều nhau và dạy Mốc đếm.", "Lông Xù nhìn từ xa, Mốc đem một phần ra cho nó."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu đếm và chia: mỗi phần đúng thì bầy đủ ăn.", "reward": "Mốc học chia sẻ.", "vocab": ["share", "half", "hungry", "enough", "together"], "assets": ["dino_trex_brown", "dino_raptor_rider", "dino_wolf_a", "river_stump", "river_log_fallen"], "subtitles": [{"en": "We share with everyone, even those who are hungry.", "vi": "Chúng ta chia sẻ cho mọi người, kể cả bạn đang đói.", "parts": ["Chúng ta ", ["share", "chia sẻ", 1], " cho mọi người, kể cả bạn đang ", ["hungry", "đói", 1], "."]}, {"en": "Give half to that friend.", "vi": "Chia một nửa cho bạn ấy nhé.", "parts": ["Chia ", ["half", "một nửa", 2], " cho bạn ấy nhé."]}]}, {"n": 6, "title": "Về bầy mang thức ăn", "minutes": 5, "optional": false, "goal": "Mang thức ăn về, cả bầy cùng ăn và kể chuyện bên tổ.", "beats": ["Bầy quây tròn, cô Đuôi Dài khen Mốc.", "Cha kể lần đầu tiên cha đi săn khi còn nhỏ."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên bữa ăn chung, đúng là bầy được no.", "reward": "Huy hiệu \"Thợ Săn Nhỏ\".", "vocab": ["dinner", "family", "story", "proud", "full"], "assets": ["dino_diplodocus", "dino_sauropod_grey", "ground_stone_floor", "tree_x11_ancient_b", "fx_fire", "hdri_sunset"], "subtitles": [{"en": "The whole family eats dinner together.", "vi": "Cả gia đình cùng ăn bữa tối.", "parts": ["Cả ", ["family", "gia đình", 1], " cùng ăn ", ["dinner", "bữa tối", 1], "."]}, {"en": "Dad tells an old story and everyone is full.", "vi": "Cha kể một câu chuyện xưa, ai cũng no bụng.", "parts": ["Cha kể một ", ["story", "câu chuyện", 1], " xưa, ai cũng no bụng."]}]}, {"n": 7, "title": "Chặng phụ: Nấm lạ", "minutes": 5, "optional": true, "goal": "Phân biệt nấm ăn được và nấm không ăn.", "beats": ["Cô Đuôi Dài dạy nhìn màu và mùi, cái gì lạ thì không ăn."], "question_hook": "Câu hỏi hiện trên vật thể phát sáng trên đồng cỏ như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["mushroom", "safe", "poison"], "assets": ["mushrooms", "river_moss_rock"], "subtitles": [{"en": "This red mushroom may be poisonous.", "vi": "Cây nấm đỏ này có thể độc.", "parts": ["Cây ", ["mushroom", "nấm", 2], " đỏ này có thể ", ["poison", "độc", 4], "."]}]}, {"n": 8, "title": "Chặng phụ: Nhật ký săn", "minutes": 5, "optional": true, "goal": "Nói hoặc chọn một câu về điều em học được.", "beats": ["Dòng nhật ký được khắc lên một tảng đá."], "question_hook": "Câu viết ngắn, chấm theo tiêu chí, không tính thua.", "reward": "Huy hiệu \"Bài Học Đầu Tay\".", "vocab": ["learn", "today", "share"], "assets": ["river_sign"], "subtitles": [{"en": "Today I learned how to share.", "vi": "Hôm nay con học được cách chia sẻ.", "parts": ["Hôm nay con ", ["learn", "học được", 1], " cách chia sẻ."]}]}]'::jsonb, '{"sizes": {"1-5": "Chơi một mình: em đóng chính chú khủng long con Mốc (tự đặt tên, chọn loài và màu); cha Gruk và cả bầy do máy điều khiển. Có 2-5 bạn thì mỗi bạn là một khủng long con trong bầy của em.", "6-20": "Mỗi em là một khủng long con trong bầy: chọn loài và màu. Bầy chia 3-4 nhóm (4-5 em/nhóm), mỗi nhóm đi sau một khủng long lớn do máy dẫn đường; nhóm trả lời đúng nhiều thì cả bầy đi nhanh hơn và chọn được lối tắt.", "21-50": "Bầy lớn: 8-10 nhóm 5 em cùng đi trên một đường mòn nhưng chia 2 bãi cỏ cạnh nhau để không đông; thanh \"Dũng cảm cả bầy\" dùng chung. Mỗi máy chỉ vẽ 8 khủng long gần nhất và tên bạn trong nhóm để máy yếu vẫn mượt."}, "roles": ["Khủng long con đi đầu (đọc dấu chân)", "Người canh gió (báo nguy hiểm)", "Người tìm nước", "Người giữ trứng và tổ", "Chim đưa tin của bầy (báo tin cho cả nhóm)"], "scoring": "Mỗi việc đúng = 1-3 sao theo độ chính xác và tốc độ. Thanh \"Dũng cảm cả bầy\" là thanh Boss chung: cả lớp cùng lấp đầy; nhóm nhiều sao nhất được cha khen và đi đầu đàn ở chặng sau.", "avatars": "Chế độ một mình: nhân vật là chú khủng long con Mốc. Chế độ lớp: mỗi học sinh một khủng long con, chọn loài (T-rex, Raptor, Triceratops, Stegosaurus, Diplodocus, Sauropod) và màu; trùng loài được, khác màu. 12 nhân vật dưới đây là cha, người lớn, bạn nhỏ và muông thú trong câu chuyện.", "species": {"trex": "dino_trex_brown", "raptor": "dino_raptor_rider", "triceratops": "dino_triceratops", "stegosaurus": "dino_stegosaurus", "diplodocus": "dino_diplodocus", "sauropod": "dino_sauropod_grey"}, "safety": "Không máu, không cảnh đau. Cảnh bắt nạt chỉ là xô đẩy, gầm gừ và chặn đường; ai \"ngã\" chỉ ngồi xuống, đứng dậy được. Săn mồi dùng hoạt ảnh vồ mồi rồi cắt cảnh; thú nhỏ luôn chạy thoát hoặc \"ngủ\" một lát, không bị làm hại.", "subtitle_rule": "Mức Beginner: toàn tiếng Việt. Mức A1 đến B2: từ có bậc thấp hơn mức đang chọn hiện tiếng Anh, từ còn lại tiếng Việt. Mức C1: toàn tiếng Anh."}'::jsonb, array['dino_antelope','dino_diplodocus','dino_rabbit','dino_raptor_rider','dino_rat','dino_sauropod_grey','dino_stegosaurus','dino_trex_brown','dino_triceratops','dino_wolf_a','dino_wolf_b','fx_fire','ground_grass_block','ground_grass_dark','ground_grass_emerald','ground_grass_iso','ground_soil_patch','ground_stone_floor','hdri_noon','hdri_sunset','mushrooms','river_bush','river_butterfly__alt1','river_fern','river_grass_tall','river_log_fallen','river_moss_rock','river_pebbles','river_pebbles__alt1','river_sign','river_stump','tree_x07_elm','tree_x08_verdant','tree_x09_lone','tree_x10_ancient_a','tree_x11_ancient_b']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
