insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('dino-03', 'dino_journey', 3, 'Đường Dài Tới Hồ Nước', 'Chương 3 của saga: hạn hán, cả bầy đi qua cao nguyên khô và rừng nấm tìm hồ nước thật; cha và cô Đuôi Dài dạy tìm nước, tiết kiệm sức, đi cùng nhau.', 'Mùa khô kéo dài, vũng nước của bầy cạn dần. Ông Cổ Dài nhớ có một hồ lớn sau cao nguyên và dẫn cả bầy đi. Đường dài, nắng gắt; Mốc học cách đi theo đội hình, nghỉ dưới bóng đá, tìm nước bằng cách nhìn chim bay và nghe tiếng gió. Qua rừng nấm, thác nước chặn đường, cả bầy phải xếp hàng đi qua từng bậc đá. Cuối cùng hồ nước hiện ra, nhưng cha dặn: uống từng chút, nhường người già và bé nhỏ trước. Mốc nhìn thấy cha uống sau cùng, dù cha mệt nhất.', 6, 5, 30, 12, true, 'Cao nguyên đỏ khô cằn, đất nứt nẻ, vài bụi cây gầy. Rồi rừng nấm khổng lồ, thác nước lấp lánh, và cuối đường là hồ xanh có đảo nổi giữa hồ.', '[{"n": 1, "title": "Cao nguyên khô", "minutes": 5, "optional": false, "goal": "Nhận ra dấu hiệu hạn hán và quyết định lên đường.", "beats": ["Đất nứt thành mảng, bụi bay, cỏ vàng úa.", "Ông Cổ Dài kể về hồ nước xưa."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi vết nứt là một câu về thời tiết và nước.", "reward": "Bầy xuất phát.", "vocab": ["dry", "hot", "thirsty", "plateau", "leave"], "assets": ["dino_world_dry_plateau", "river_cliff__alt1", "ground_stone_floor", "dino_sauropod_grey", "hdri_noon"], "subtitles": [{"en": "The sky is hot and the ground is dry and cracked.", "vi": "Trời nóng và đất khô nứt nẻ.", "parts": ["Trời ", ["hot", "nóng", 1], " và đất ", ["dry", "khô", 1], " nứt nẻ."]}, {"en": "We must leave to find water. Everyone is thirsty.", "vi": "Chúng ta phải rời đi để tìm nước. Ai cũng đang khát.", "parts": ["Chúng ta phải ", ["leave", "rời đi", 2], " để tìm nước. Ai cũng đang ", ["thirsty", "khát", 2], "."]}]}, {"n": 2, "title": "Đi theo đội hình", "minutes": 5, "optional": false, "goal": "Cả bầy đi thành hàng: lớn trước, nhỏ giữa, già cuối.", "beats": ["Mỗi nhóm giữ khoảng cách vừa đủ, không ai bị bỏ lại.", "Tia Chớp chạy đi chạy lại báo tin cho cả hàng."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên lưng khủng long đi trước; đúng thì hàng gọn.", "reward": "Bầy đi nhanh hơn.", "vocab": ["line", "front", "behind", "together", "stay"], "assets": ["dino_raptor_rider", "dino_triceratops", "dino_stegosaurus", "river_rock_small", "river_rock_medium"], "subtitles": [{"en": "Stay in line, do not fall behind.", "vi": "Ở lại trong hàng, đừng tụt lại phía sau.", "parts": [["Stay", "Ở lại", 1], " trong hàng, đừng tụt lại ", ["behind", "phía sau", 2], "."]}, {"en": "We walk together.", "vi": "Chúng ta đi cùng nhau.", "parts": ["Chúng ta đi ", ["together", "cùng nhau", 1], "."]}]}, {"n": 3, "title": "Rừng nấm khổng lồ", "minutes": 5, "optional": false, "goal": "Đi qua rừng nấm, nghỉ dưới bóng râm, tìm lối ra.", "beats": ["Nấm to che nắng, nhưng đường rẽ nhiều nhánh.", "Cô Đuôi Dài dạy đánh dấu đường bằng cành cây."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi ngã rẽ là một câu hỏi chỉ đường.", "reward": "Cả bầy nghỉ lấy sức.", "vocab": ["shade", "rest", "path", "turn", "giant"], "assets": ["mushrooms", "tree_x09_lone", "tree_x10_ancient_a", "tree_x12_dark_bark", "river_fern__alt1"], "subtitles": [{"en": "We can rest a little in this shade.", "vi": "Dưới bóng râm này ta có thể nghỉ một chút.", "parts": ["Dưới ", ["shade", "bóng râm", 3], " này ta có thể ", ["rest", "nghỉ", 1], " một chút."]}, {"en": "Choose the right path and turn.", "vi": "Chọn đúng lối đi rồi rẽ nhé.", "parts": ["Chọn đúng ", ["path", "lối đi", 2], " rồi ", ["turn", "rẽ", 1], " nhé."]}]}, {"n": 4, "title": "Thác nước chắn lối", "minutes": 5, "optional": false, "goal": "Leo qua từng bậc đá cạnh thác, giúp nhau qua.", "beats": ["Thác đổ mát lạnh, bậc đá trơn.", "Khủng long lớn đưa đuôi làm cầu cho bạn nhỏ."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi bậc đá là một câu; đúng thì bậc đá chắc.", "reward": "Cả bầy qua thác.", "vocab": ["waterfall", "climb", "slippery", "help", "bridge"], "assets": ["mini_runestone_falls", "river_waterfall", "river_waterfall_pool", "river_moss_rock", "wood_plank_b"], "subtitles": [{"en": "The waterfall is strong and the rocks are slippery.", "vi": "Thác nước chảy rất mạnh, đá thì trơn.", "parts": [["Waterfall", "Thác nước", 2], " chảy rất mạnh, đá thì ", ["slippery", "trơn", 4], "."]}, {"en": "Help each other climb across.", "vi": "Hãy giúp nhau leo qua.", "parts": ["Hãy ", ["help", "giúp", 1], " nhau ", ["climb", "leo", 2], " qua."]}]}, {"n": 5, "title": "Hồ nước hiện ra", "minutes": 5, "optional": false, "goal": "Tìm thấy hồ, canh chừng và uống theo thứ tự.", "beats": ["Mặt hồ phẳng như gương, có đảo nổi ở giữa.", "Cha dặn nhường người già và bé nhỏ uống trước."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Vũng nước nào an toàn thì sáng xanh.", "reward": "Cả bầy có nước.", "vocab": ["lake", "drink", "first", "old", "careful"], "assets": ["mini_jungle_river", "mini_floating_oasis", "river_lilypad__alt1", "palm_a", "palm_b"], "subtitles": [{"en": "There is the lake! But be careful when drinking.", "vi": "Hồ kia rồi! Nhưng hãy cẩn thận khi uống.", "parts": [["Lake", "Hồ", 1], " kia rồi! Nhưng hãy cẩn thận khi ", ["drink", "uống", 0], "."]}, {"en": "The old and the little ones drink first.", "vi": "Người già và bé nhỏ uống trước.", "parts": ["Người già và bé nhỏ uống ", ["first", "trước", 1], "."]}]}, {"n": 6, "title": "Cha uống sau cùng", "minutes": 5, "optional": false, "goal": "Cả bầy nghỉ bên hồ; Mốc thấy cha mệt nhưng vẫn nhường.", "beats": ["Cha ngồi xuống, thở dài, nhìn con cười.", "Ông Cổ Dài kể: một bầy mạnh khi biết nhường nhau."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên mặt hồ; đúng là sóng lăn tăn.", "reward": "Huy hiệu \"Cả Bầy Đến Nơi\".", "vocab": ["tired", "thank", "strong", "family", "rest"], "assets": ["dino_trex_brown", "dino_diplodocus", "river_driftwood", "river_birds", "hdri_sunset"], "subtitles": [{"en": "Dad is very tired but still smiling.", "vi": "Cha mệt lắm, nhưng cha vẫn mỉm cười.", "parts": ["Cha ", ["tired", "mệt", 1], " lắm, nhưng cha vẫn mỉm cười."]}, {"en": "Thank you, Dad, thank you so much.", "vi": "Cảm ơn cha, cảm ơn cha rất nhiều.", "parts": ["Cảm ơn cha, ", ["thank", "cảm ơn", 0], " cha rất nhiều."]}]}, {"n": 7, "title": "Chặng phụ: Đảo nổi giữa hồ", "minutes": 5, "optional": true, "goal": "Ngắm đảo nổi và học từ chỉ vị trí.", "beats": ["Đảo nổi xa xa, bay lơ lửng."], "question_hook": "Câu hỏi hiện trên vật thể phát sáng trên đồng cỏ như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["island", "above", "near"], "assets": ["mini_floating_waterfall"], "subtitles": [{"en": "That island floats above the lake.", "vi": "Hòn đảo kia bay trên mặt hồ.", "parts": ["Hòn ", ["island", "đảo", 2], " kia bay trên mặt ", ["lake", "hồ", 1], "."]}]}, {"n": 8, "title": "Chặng phụ: Nhật ký đường dài", "minutes": 5, "optional": true, "goal": "Nói hoặc chọn một câu về chuyến đi.", "beats": ["Dòng nhật ký khắc lên thân gỗ trôi."], "question_hook": "Câu viết ngắn, chấm theo tiêu chí, không tính thua.", "reward": "Huy hiệu \"Người Đi Xa\".", "vocab": ["long", "walk", "tired"], "assets": ["wood_plank_a"], "subtitles": [{"en": "Today I walked very far.", "vi": "Hôm nay con đã đi bộ rất xa.", "parts": ["Hôm nay con đã ", ["walk", "đi bộ", 1], " rất ", ["long", "xa", 1], "."]}]}]'::jsonb, '{"sizes": {"1-5": "Chơi một mình: em đóng chính chú khủng long con Mốc (tự đặt tên, chọn loài và màu); cha Gruk và cả bầy do máy điều khiển. Có 2-5 bạn thì mỗi bạn là một khủng long con trong bầy của em.", "6-20": "Mỗi em là một khủng long con trong bầy: chọn loài và màu. Bầy chia 3-4 nhóm (4-5 em/nhóm), mỗi nhóm đi sau một khủng long lớn do máy dẫn đường; nhóm trả lời đúng nhiều thì cả bầy đi nhanh hơn và chọn được lối tắt.", "21-50": "Bầy lớn: 8-10 nhóm 5 em cùng đi trên một đường mòn nhưng chia 2 bãi cỏ cạnh nhau để không đông; thanh \"Dũng cảm cả bầy\" dùng chung. Mỗi máy chỉ vẽ 8 khủng long gần nhất và tên bạn trong nhóm để máy yếu vẫn mượt."}, "roles": ["Khủng long con đi đầu (đọc dấu chân)", "Người canh gió (báo nguy hiểm)", "Người tìm nước", "Người giữ trứng và tổ", "Chim đưa tin của bầy (báo tin cho cả nhóm)"], "scoring": "Mỗi việc đúng = 1-3 sao theo độ chính xác và tốc độ. Thanh \"Dũng cảm cả bầy\" là thanh Boss chung: cả lớp cùng lấp đầy; nhóm nhiều sao nhất được cha khen và đi đầu đàn ở chặng sau.", "avatars": "Chế độ một mình: nhân vật là chú khủng long con Mốc. Chế độ lớp: mỗi học sinh một khủng long con, chọn loài (T-rex, Raptor, Triceratops, Stegosaurus, Diplodocus, Sauropod) và màu; trùng loài được, khác màu. 12 nhân vật dưới đây là cha, người lớn, bạn nhỏ và muông thú trong câu chuyện.", "species": {"trex": "dino_trex_brown", "raptor": "dino_raptor_rider", "triceratops": "dino_triceratops", "stegosaurus": "dino_stegosaurus", "diplodocus": "dino_diplodocus", "sauropod": "dino_sauropod_grey"}, "safety": "Không máu, không cảnh đau. Cảnh bắt nạt chỉ là xô đẩy, gầm gừ và chặn đường; ai \"ngã\" chỉ ngồi xuống, đứng dậy được. Săn mồi dùng hoạt ảnh vồ mồi rồi cắt cảnh; thú nhỏ luôn chạy thoát hoặc \"ngủ\" một lát, không bị làm hại.", "subtitle_rule": "Mức Beginner: toàn tiếng Việt. Mức A1 đến B2: từ có bậc thấp hơn mức đang chọn hiện tiếng Anh, từ còn lại tiếng Việt. Mức C1: toàn tiếng Anh."}'::jsonb, array['dino_antelope','dino_diplodocus','dino_rabbit','dino_raptor_rider','dino_sauropod_grey','dino_stegosaurus','dino_trex_brown','dino_triceratops','dino_wolf_a','dino_wolf_b','dino_world_dry_plateau','ground_stone_floor','hdri_noon','hdri_sunset','mini_floating_oasis','mini_floating_waterfall','mini_jungle_river','mini_runestone_falls','mushrooms','palm_a','palm_b','river_birds','river_cliff__alt1','river_driftwood','river_fern__alt1','river_lilypad__alt1','river_moss_rock','river_rock_medium','river_rock_small','river_waterfall','river_waterfall_pool','tree_x09_lone','tree_x10_ancient_a','tree_x12_dark_bark','wood_plank_a','wood_plank_b']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('dino-03#01', 'dino-03', 1, 'Mốc', 'Khủng long con tò mò, nhân vật chính (khi chơi một mình)', 'child', 'm', 'S5', false, 'E_brown_dark', 'black', 'messy', 'short', false, false, 'casual', 'orange', '[dino_trex_brown] Khủng long con nhỏ, da nâu cam, bụng sáng, vết sọc trên đuôi', null, null, array['flower']::text[], 'Khủng long con, người kể chuyện', 'heroes');
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('dino-03#02', 'dino-03', 2, 'Bố Gruk', 'Cha của Mốc, săn giỏi, ít nói, luôn đi trước chắn gió', 'adult', 'm', 'S3', false, 'E_black', 'black', 'messy', 'short', false, false, 'casual', 'brown', '[dino_trex_brown] T-rex trưởng thành da nâu sẫm, sẹo nhỏ trên mõm', null, null, '{}'::text[], 'Cha, người dạy Mốc', 'npc');
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('dino-03#03', 'dino-03', 3, 'Cô Đuôi Dài', 'Khủng long cổ dài hiền, trông cả bầy nhỏ', 'adult', 'f', 'S4', false, 'E_brown', 'black', 'messy', 'short', false, false, 'casual', 'green', '[dino_diplodocus] Diplodocus xanh lá, đốm nâu dọc cổ', null, null, '{}'::text[], 'Cô giáo của bầy', 'npc');
