insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('dino-03#05', 'dino-03', 5, 'Tia Chớp', 'Raptor đeo túi, đưa tin nhanh nhất bầy', 'teen', 'f', 'S2', false, 'E_black', 'black', 'messy', 'short', false, false, 'casual', 'yellow', '[dino_raptor_rider] Raptor nâu nhạt, yên và túi vải nhỏ trên lưng', null, null, array['bag']::text[], 'Chim đưa tin của bầy', 'heroes');
