insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('dino-04', 'dino_journey', 4, 'Đêm Bão Và Tổ Ấm', 'Chương 4 của saga: bão đêm, cả bầy tìm chỗ trú, đối mặt sói đói, sưởi ấm bên nhau; Mốc thấy cha bắt đầu yếu đi.', 'Chiều xuống, bầu trời đổi màu; Ông Cổ Dài ngửi thấy mùi bão. Cả bầy phải kịp tìm chỗ trú trước khi trời tối hẳn. Mốc giúp khuân ván gỗ gia cố túp da cổ, chỉ chỗ gió lùa, đếm đủ cả bầy bên trong. Đêm xuống, lũ sói đói lảng vảng quanh chỗ trú; cô Đuôi Dài dạy bầy đứng sát nhau, cha đứng chắn cửa. Sấm sét làm một cây đổ gần lối vào, cả bầy phải làm việc cùng nhau để dọn lối. Sáng ra, mưa tạnh, Mốc nhận thấy cha đứng chậm hơn trước và hơi thở nặng hơn.', 6, 5, 30, 12, true, 'Bờ hồ lúc chạng vạng, mây đen cuồn cuộn, gió giật; có túp da cổ làm chỗ trú, rừng cây cổ thụ và thân gỗ đổ. Sấm chớp xa, mưa rơi từng đợt.', '[{"n": 1, "title": "Mây đen kéo tới", "minutes": 5, "optional": false, "goal": "Nhận biết dấu hiệu bão và báo cho cả bầy.", "beats": ["Gió đổi hướng, chim bay thấp, mây đen dày.", "Ông Cổ Dài ngửi không khí và lắc đầu."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi dấu hiệu là một câu về thời tiết.", "reward": "Cả bầy kịp báo động.", "vocab": ["storm", "cloud", "wind", "cold", "warn"], "assets": ["tree_x11_ancient_b", "dino_sauropod_grey", "river_birds", "hdri_cloudy"], "subtitles": [{"en": "A storm is coming and clouds cover the sky.", "vi": "Bão sắp tới, mây đen kín trời.", "parts": [["Storm", "Bão", 2], " sắp tới, ", ["cloud", "mây", 1], " đen kín trời."]}, {"en": "Let everyone warn each other.", "vi": "Mọi người hãy báo cho nhau biết nhé.", "parts": ["Mọi người hãy ", ["warn", "báo", 4], " cho nhau biết nhé."]}]}, {"n": 2, "title": "Tìm chỗ trú", "minutes": 5, "optional": false, "goal": "Dẫn cả bầy vào túp da cổ và gia cố mái.", "beats": ["Ván gỗ ghép thành mái, dây thừng buộc chặt.", "Mốc đếm đủ cả bầy vào trong."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi tấm ván là một câu; đúng thì ván được chèn vào đúng chỗ.", "reward": "Chỗ trú chắc chắn.", "vocab": ["shelter", "roof", "inside", "strong", "count"], "assets": ["dino_nest_shelter", "wood_plank_b", "wood_plank_a", "camp_rope", "tree_x04", "anim_kneel_work"], "subtitles": [{"en": "Quick, get into the shelter, it is going to rain!", "vi": "Mau vào chỗ trú, trời sắp mưa!", "parts": ["Mau vào ", ["shelter", "chỗ trú", 2], ", trời sắp mưa!"]}, {"en": "The roof must be strong. Let us count if everyone is here.", "vi": "Mái nhà phải thật chắc. Ta cùng đếm xem đủ chưa.", "parts": ["Mái nhà phải thật ", ["strong", "chắc", 1], ". Ta cùng ", ["count", "đếm", 0], " xem đủ chưa."]}]}, {"n": 3, "title": "Sói rình ngoài cửa", "minutes": 5, "optional": false, "goal": "Giữ bình tĩnh khi sói xuất hiện quanh chỗ trú.", "beats": ["Những cặp mắt vàng phát sáng ngoài bóng tối.", "Cô Đuôi Dài dặn cả bầy đứng sát nhau, không ai chạy ra."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Hành động đúng là sáng lên: đứng im, đứng sát, hay gọi cha.", "reward": "Bầy an toàn.", "vocab": ["wolf", "close", "stay", "brave", "dark"], "assets": ["dino_wolf_a", "dino_wolf_b", "ground_grass_dark", "river_bush__alt2", "hdri_night"], "subtitles": [{"en": "There are two wolves out there and it is dark.", "vi": "Có hai con sói ngoài kia, trời lại tối.", "parts": ["Có hai con ", ["wolf", "sói", 1], " ngoài kia, trời lại ", ["dark", "tối", 1], "."]}, {"en": "Stay together and be brave.", "vi": "Hãy ở yên bên nhau và thật dũng cảm.", "parts": ["Hãy ", ["stay", "ở yên", 1], " bên nhau và thật ", ["brave", "dũng cảm", 3], "."]}]}, {"n": 4, "title": "Sưởi ấm bên nhau", "minutes": 5, "optional": false, "goal": "Dựa vào nhau giữ ấm, kể chuyện đợi bão qua.", "beats": ["Cả bầy xích lại, đứa lớn che đứa nhỏ.", "Ông Cổ Dài kể chuyện về lần bão lớn xưa."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên đống lửa nhỏ trong chỗ trú.", "reward": "Cả bầy ấm áp.", "vocab": ["warm", "together", "story", "sleep", "cold"], "assets": ["dino_stegosaurus", "dino_triceratops", "fx_fire", "fx_smoke", "river_woodpile"], "subtitles": [{"en": "The night is cold, but together we are warm.", "vi": "Đêm lạnh, nhưng khi ở bên nhau thì rất ấm.", "parts": ["Đêm ", ["cold", "lạnh", 1], ", nhưng khi ở bên nhau thì rất ", ["warm", "ấm", 1], "."]}, {"en": "Grandpa tells a story so the children can sleep.", "vi": "Cụ kể một câu chuyện cho các cháu ngủ.", "parts": ["Cụ kể một ", ["story", "câu chuyện", 1], " cho các cháu ", ["sleep", "ngủ", 0], "."]}]}, {"n": 5, "title": "Sấm sét và cây đổ", "minutes": 5, "optional": false, "goal": "Cùng nhau dọn cây đổ chắn lối vào.", "beats": ["Một tia sét đánh gần, thân cây đổ chắn cửa.", "Khủng long lớn đẩy, khủng long nhỏ kéo dây."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi lần đẩy là một câu; đúng cả nhóm thì thân cây nhúc nhích.", "reward": "Lối vào được mở.", "vocab": ["thunder", "push", "pull", "tree", "together"], "assets": ["tree_x12_dark_bark", "river_driftwood", "river_log_fallen", "camp_rope", "dino_trex_brown"], "subtitles": [{"en": "Thunder cracked and a tree fell across the door.", "vi": "Sấm đánh một tiếng, cây cây đổ chắn cửa.", "parts": [["Thunder", "Sấm", 2], " đánh một tiếng, cây ", ["tree", "cây", 0], " đổ chắn cửa."]}, {"en": "Everybody push and pull!", "vi": "Mọi người cùng đẩy và kéo!", "parts": ["Mọi người cùng ", ["push", "đẩy", 1], " và ", ["pull", "kéo", 1], "!"]}]}, {"n": 6, "title": "Bình minh sau bão", "minutes": 5, "optional": false, "goal": "Mưa tạnh, cả bầy bước ra; Mốc thấy cha mệt hơn.", "beats": ["Cầu vồng bắc ngang thác nước.", "Cha đứng chậm lại, thở nặng nhưng vẫn cười với con."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên cầu vồng; đúng là cầu vồng sáng thêm màu.", "reward": "Huy hiệu \"Sống Sót Qua Bão\".", "vocab": ["rainbow", "morning", "tired", "worry", "hope"], "assets": ["river_waterfall", "river_waterfall_pool", "dino_diplodocus", "ground_grass_emerald", "hdri_dawn"], "subtitles": [{"en": "There is a rainbow after the storm!", "vi": "Có một chiếc cầu vồng sau cơn bão!", "parts": ["Có một chiếc ", ["rainbow", "cầu vồng", 2], " sau cơn bão!"]}, {"en": "Dad looks tired. Moc starts to worry.", "vi": "Cha trông mệt. Mốc bắt đầu thấy lo lắng.", "parts": ["Cha trông ", ["tired", "mệt", 1], ". Mốc bắt đầu thấy ", ["worry", "lo lắng", 4], "."]}]}, {"n": 7, "title": "Chặng phụ: Đếm tiếng sấm", "minutes": 5, "optional": true, "goal": "Đếm giữa chớp và sấm để đoán bão xa hay gần.", "beats": ["Mỗi tiếng đếm đúng là một vòng nước tỏa ra."], "question_hook": "Câu hỏi hiện trên vật thể phát sáng trên đồng cỏ như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["count", "far", "near"], "assets": ["tree_x08_verdant"], "subtitles": [{"en": "Is the storm still far or already near?", "vi": "Bão còn xa hay đã gần?", "parts": ["Bão còn ", ["far", "xa", 1], " hay đã ", ["near", "gần", 1], "?"]}]}, {"n": 8, "title": "Chặng phụ: Nhật ký đêm bão", "minutes": 5, "optional": true, "goal": "Nói hoặc chọn một câu về đêm bão.", "beats": ["Dòng nhật ký khắc lên vách túp da."], "question_hook": "Câu viết ngắn, chấm theo tiêu chí, không tính thua.", "reward": "Huy hiệu \"Đêm Bão\".", "vocab": ["night", "storm", "safe"], "assets": ["river_sign"], "subtitles": [{"en": "Tonight I feel safe with the herd.", "vi": "Đêm nay con thấy an toàn bên bầy.", "parts": ["Đêm nay con thấy ", ["safe", "an toàn", 1], " bên bầy."]}]}]'::jsonb, '{"sizes": {"1-5": "Chơi một mình: em đóng chính chú khủng long con Mốc (tự đặt tên, chọn loài và màu); cha Gruk và cả bầy do máy điều khiển. Có 2-5 bạn thì mỗi bạn là một khủng long con trong bầy của em.", "6-20": "Mỗi em là một khủng long con trong bầy: chọn loài và màu. Bầy chia 3-4 nhóm (4-5 em/nhóm), mỗi nhóm đi sau một khủng long lớn do máy dẫn đường; nhóm trả lời đúng nhiều thì cả bầy đi nhanh hơn và chọn được lối tắt.", "21-50": "Bầy lớn: 8-10 nhóm 5 em cùng đi trên một đường mòn nhưng chia 2 bãi cỏ cạnh nhau để không đông; thanh \"Dũng cảm cả bầy\" dùng chung. Mỗi máy chỉ vẽ 8 khủng long gần nhất và tên bạn trong nhóm để máy yếu vẫn mượt."}, "roles": ["Khủng long con đi đầu (đọc dấu chân)", "Người canh gió (báo nguy hiểm)", "Người tìm nước", "Người giữ trứng và tổ", "Chim đưa tin của bầy (báo tin cho cả nhóm)"], "scoring": "Mỗi việc đúng = 1-3 sao theo độ chính xác và tốc độ. Thanh \"Dũng cảm cả bầy\" là thanh Boss chung: cả lớp cùng lấp đầy; nhóm nhiều sao nhất được cha khen và đi đầu đàn ở chặng sau.", "avatars": "Chế độ một mình: nhân vật là chú khủng long con Mốc. Chế độ lớp: mỗi học sinh một khủng long con, chọn loài (T-rex, Raptor, Triceratops, Stegosaurus, Diplodocus, Sauropod) và màu; trùng loài được, khác màu. 12 nhân vật dưới đây là cha, người lớn, bạn nhỏ và muông thú trong câu chuyện.", "species": {"trex": "dino_trex_brown", "raptor": "dino_raptor_rider", "triceratops": "dino_triceratops", "stegosaurus": "dino_stegosaurus", "diplodocus": "dino_diplodocus", "sauropod": "dino_sauropod_grey"}, "safety": "Không máu, không cảnh đau. Cảnh bắt nạt chỉ là xô đẩy, gầm gừ và chặn đường; ai \"ngã\" chỉ ngồi xuống, đứng dậy được. Săn mồi dùng hoạt ảnh vồ mồi rồi cắt cảnh; thú nhỏ luôn chạy thoát hoặc \"ngủ\" một lát, không bị làm hại.", "subtitle_rule": "Mức Beginner: toàn tiếng Việt. Mức A1 đến B2: từ có bậc thấp hơn mức đang chọn hiện tiếng Anh, từ còn lại tiếng Việt. Mức C1: toàn tiếng Anh."}'::jsonb, array['anim_kneel_work','camp_rope','dino_antelope','dino_diplodocus','dino_nest_shelter','dino_rabbit','dino_raptor_rider','dino_rat','dino_sauropod_grey','dino_stegosaurus','dino_trex_brown','dino_triceratops','dino_wolf_a','dino_wolf_b','fx_fire','fx_smoke','ground_grass_dark','ground_grass_emerald','hdri_cloudy','hdri_dawn','hdri_night','river_birds','river_bush__alt2','river_driftwood','river_log_fallen','river_sign','river_waterfall','river_waterfall_pool','river_woodpile','tree_x04','tree_x08_verdant','tree_x11_ancient_b','tree_x12_dark_bark','wood_plank_a','wood_plank_b']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
