insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('dino-04#12', 'dino-04', 12, 'Linh Dương Đốm', 'Linh dương nghe tiếng sấm từ xa', 'adult', 'f', 'S5', false, 'E_brown_dark', 'black', 'messy', 'short', false, false, 'casual', 'khaki', '[dino_antelope] Linh dương nâu đốm trắng', null, null, '{}'::text[], 'Người nghe bão', 'npc');
insert into public.game_scenarios (id, game, seq, title, inspiration, story, rounds, minutes_per_round, total_minutes, character_count, active, setting, stages, class_plan, asset_ids, plan_version) values ('dino-05', 'dino_journey', 5, 'Cha Già Và Ngày Đứng Lên', 'Chương cuối của saga: cha đã già, bị các khủng long khác bắt nạt khi đi uống nước; Mốc đã lớn đứng lên, gọi cả bầy cùng giải cứu cha.', 'Mùa nước đã qua, Mốc đã lớn gần bằng nửa cha. Bố Gruk bây giờ đi chậm, lưng còng, không còn là kẻ săn nhanh nhất. Một chiều, cha ra hồ uống nước một mình thì bị Răng Vàng và Bóng Đêm chặn đường, xô đẩy và giành chỗ uống. Tia Chớp chạy về báo tin; Mốc khựng lại, nhớ những bài học: đọc dấu chân, nghe báo động, đứng sát nhau, nhường người già. Mốc không lao vào một mình. Mốc gọi cả bầy: cô Đuôi Dài, ông Cổ Dài, Sừng Nhỏ, Gai Gai... mỗi người một việc. Cả bầy đứng thành một hàng chắn, gầm vang cùng lúc; hai kẻ bắt nạt lùi lại, bỏ đi. Cha ngước nhìn con, nói: "Con đã lớn rồi." Hoàng hôn xuống, cha con cùng uống nước bên nhau, cả bầy đứng quanh.', 6, 5, 30, 12, true, 'Hồ nước lúc chiều tà, vầng mặt trời đỏ chạm cao nguyên. Gần hồ là bãi đá và đảo rừng nổi lơ lửng, nơi bầy khủng long lạ hay tụ họp. Cỏ vàng rực trong nắng.', '[{"n": 1, "title": "Cha chậm bước", "minutes": 5, "optional": false, "goal": "Nhận ra cha đã già: đi chậm, uống chậm, hay nghỉ.", "beats": ["Mốc đi cạnh cha, chậm lại cho vừa nhịp.", "Ông Cổ Dài nói: già không phải yếu, chỉ cần người bên cạnh."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên dấu chân cha, mỗi dấu chân nặng hơn trước.", "reward": "Mốc hiểu cha.", "vocab": ["old", "slow", "tired", "help", "back"], "assets": ["dino_trex_brown", "ground_grass_tuft", "tree_x01", "tree_x03", "ground_grass_patch", "hdri_noon"], "subtitles": [{"en": "Dad is old and walks more slowly than before.", "vi": "Cha đã già, bước đi chậm hơn trước.", "parts": ["Cha đã ", ["old", "già", 0], ", bước đi ", ["slow", "chậm", 1], " hơn trước."]}, {"en": "Moc says: \"Let me help you, Dad.\"", "vi": "Mốc nói: \"Để con giúp cha.\"", "parts": ["Mốc nói: \"Để con ", ["help", "giúp", 1], " cha.\""]}]}, {"n": 2, "title": "Hai kẻ bắt nạt", "minutes": 5, "optional": false, "goal": "Chứng kiến Răng Vàng và Bóng Đêm chặn đường cha ở hồ.", "beats": ["Hai T-rex lạ gầm gừ, giành chỗ uống, xô cha ngã ngồi.", "Cha không đánh lại, chỉ lùi lại để tránh va chạm."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi hành động của kẻ bắt nạt là một câu mô tả; chọn đúng để hiểu chuyện gì đang xảy ra.", "reward": "Mốc nhìn rõ sự thật.", "vocab": ["bully", "push", "angry", "unfair", "lake"], "assets": ["dino_trex_yellow", "dino_trex_black", "dino_wolf_a", "mini_azure_river", "river_rock_large"], "subtitles": [{"en": "Two big dinosaurs push Dad around at the lake.", "vi": "Hai con khủng long to xác xô đẩy cha ở bờ hồ.", "parts": ["Hai con khủng long to xác ", ["push", "xô đẩy", 1], " cha ở bờ hồ."]}, {"en": "They bully an old dinosaur. How unfair!", "vi": "Họ bắt nạt người già. Thật bất công!", "parts": ["Họ ", ["bully", "bắt nạt", 4], " người già. Thật ", ["unfair", "bất công", 4], "!"]}]}, {"n": 3, "title": "Mốc dừng lại suy nghĩ", "minutes": 5, "optional": false, "goal": "Nhớ lại các bài học và lên kế hoạch, không lao vào một mình.", "beats": ["Mốc nhắm mắt: dấu chân, tiếng gầm, đứng sát nhau, nhường người già.", "Mốc quyết định: cần cả bầy."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi bài học là một thẻ nhớ; chọn đúng bài học dùng cho tình huống này.", "reward": "Một kế hoạch.", "vocab": ["think", "plan", "remember", "alone", "together"], "assets": ["mini_logic_island", "tree_x05", "tree_x06_duo", "river_stump", "hdri_sunset"], "subtitles": [{"en": "Moc stops to think. He cannot do it alone.", "vi": "Mốc dừng lại để suy nghĩ. Một mình thì không thể.", "parts": ["Mốc dừng lại để ", ["think", "suy nghĩ", 1], ". Một mình thì không thể."]}, {"en": "I must remember everything Dad taught me and make a plan.", "vi": "Con phải nhớ mọi điều cha dạy và có một kế hoạch.", "parts": ["Con phải ", ["remember", "nhớ", 2], " mọi điều cha dạy và có một ", ["plan", "kế hoạch", 1], "."]}]}, {"n": 4, "title": "Gọi cả bầy", "minutes": 5, "optional": false, "goal": "Chạy tới từng thành viên của bầy và kêu gọi họ.", "beats": ["Tia Chớp chạy trước báo tin; mỗi bạn nhận một việc.", "Cô Đuôi Dài, ông Cổ Dài, Sừng Nhỏ, Gai Gai đều đồng ý ngay."], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi lời gọi là một câu; đúng thì người đó tới.", "reward": "Cả bầy có mặt.", "vocab": ["call", "herd", "ask", "join", "ready"], "assets": ["dino_raptor_rider", "dino_diplodocus", "dino_sauropod_grey", "dino_triceratops", "dino_stegosaurus", "anim_cheer"], "subtitles": [{"en": "Moc runs to call the whole herd.", "vi": "Mốc chạy đi gọi cả bầy.", "parts": ["Mốc chạy đi ", ["call", "gọi", 1], " cả ", ["herd", "bầy", 3], "."]}, {"en": "\"Are you ready to join me?\"", "vi": "\"Các bạn có sẵn sàng tham gia cùng tôi không?\"", "parts": ["\"Các bạn có ", ["ready", "sẵn sàng", 2], " ", ["join", "tham gia", 3], " cùng tôi không?\""]}]}, {"n": 5, "title": "Đứng lên", "minutes": 5, "optional": false, "goal": "Cả bầy xếp hàng tiến về hồ, đứng chắn trước hai kẻ bắt nạt.", "beats": ["Mốc đứng đầu hàng, cả bầy sát bên.", "Mốc nói: \"Dừng lại. Đây là cha của tôi, và đây là nước của tất cả mọi người.\""], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Ba lượt câu hỏi: lời nói, đội hình, tiếng gầm chung; đúng cả ba thì bầy chắn thành công.", "reward": "Thanh \"Dũng cảm cả bầy\" đầy.", "vocab": ["stand up", "brave", "stop", "roar", "together"], "assets": ["dino_trex_brown", "dino_trex_yellow", "dino_trex_black", "ground_strip_6x20", "ground_grass_iso", "hdri_sunset"], "subtitles": [{"en": "Moc stands up and says: \"Stop!\"", "vi": "Mốc đứng lên và nói: \"Dừng lại!\"", "parts": ["Mốc ", ["stand up", "đứng lên", 3], " và nói: \"", ["Stop", "Dừng lại", 1], "!\""]}, {"en": "The whole herd roars bravely together.", "vi": "Cả bầy cùng gầm một tiếng thật dũng cảm.", "parts": ["Cả bầy cùng gầm một tiếng thật ", ["brave", "dũng cảm", 3], "."]}]}, {"n": 6, "title": "Giải cứu và hòa bình", "minutes": 5, "optional": false, "goal": "Hai kẻ bắt nạt lùi lại; cha được đỡ dậy; cả bầy uống nước cùng nhau.", "beats": ["Răng Vàng và Bóng Đêm nhìn hàng chắn, rồi bỏ đi.", "Cha ngước nhìn con: \"Con đã lớn rồi.\""], "question_hook": "Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi cuối hiện trên mặt hồ; đúng thì ánh hoàng hôn phủ vàng cả bầy.", "reward": "Huy hiệu \"Người Con Dũng Cảm\" cho nhóm đứng đầu và cho cả lớp.", "vocab": ["rescue", "proud", "safe", "family", "peace"], "assets": ["dino_world_floating_jungle", "mini_floating_waterfall", "mini_floating_oasis", "dino_diplodocus", "dino_trex_brown", "hdri_sunset"], "subtitles": [{"en": "Dad is rescued. The whole family is safe.", "vi": "Cha đã được giải cứu. Cả nhà đều an toàn.", "parts": ["Cha đã được ", ["rescue", "giải cứu", 3], ". Cả nhà đều ", ["safe", "an toàn", 1], "."]}, {"en": "\"You have grown up,\" Dad said, \"I am so proud of you.\"", "vi": "\"Con đã lớn rồi,\" cha nói, \"cha rất tự hào về con.\"", "parts": ["\"Con đã lớn rồi,\" cha nói, \"cha rất ", ["proud", "tự hào", 3], " về con.\""]}]}, {"n": 7, "title": "Chặng phụ: Bài học của cha", "minutes": 5, "optional": true, "goal": "Cha kể lại điều quan trọng nhất cha muốn Mốc nhớ.", "beats": ["Cha kể bên hồ, cả bầy ngồi nghe."], "question_hook": "Câu hỏi hiện trên vật thể phát sáng trên đồng cỏ như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.", "reward": "Sao đôi.", "vocab": ["listen", "brave", "kind"], "assets": ["tree_pixel", "hdri_dawn"], "subtitles": [{"en": "Always be brave and kind.", "vi": "Hãy luôn dũng cảm và tử tế.", "parts": ["Hãy luôn ", ["brave", "dũng cảm", 3], " và ", ["kind", "tử tế", 2], "."]}]}, {"n": 8, "title": "Chặng phụ: Lời thề của bầy", "minutes": 5, "optional": true, "goal": "Mỗi em nói hoặc chọn một câu lời hứa cho người già và bạn nhỏ.", "beats": ["Lời hứa được khắc lên tảng đá cạnh hồ."], "question_hook": "Câu viết ngắn, chấm theo tiêu chí, không tính thua.", "reward": "Huy hiệu \"Cả Bầy Một Lòng\".", "vocab": ["promise", "help", "always"], "assets": ["river_sign"], "subtitles": [{"en": "I promise I will always help the old.", "vi": "Em hứa sẽ luôn giúp người già.", "parts": ["Em ", ["promise", "hứa", 3], " sẽ luôn ", ["help", "giúp", 1], " người già."]}]}]'::jsonb, '{"sizes": {"1-5": "Chơi một mình: em đóng chính chú khủng long con Mốc (tự đặt tên, chọn loài và màu); cha Gruk và cả bầy do máy điều khiển. Có 2-5 bạn thì mỗi bạn là một khủng long con trong bầy của em.", "6-20": "Mỗi em là một khủng long con trong bầy: chọn loài và màu. Bầy chia 3-4 nhóm (4-5 em/nhóm), mỗi nhóm đi sau một khủng long lớn do máy dẫn đường; nhóm trả lời đúng nhiều thì cả bầy đi nhanh hơn và chọn được lối tắt.", "21-50": "Bầy lớn: 8-10 nhóm 5 em cùng đi trên một đường mòn nhưng chia 2 bãi cỏ cạnh nhau để không đông; thanh \"Dũng cảm cả bầy\" dùng chung. Mỗi máy chỉ vẽ 8 khủng long gần nhất và tên bạn trong nhóm để máy yếu vẫn mượt."}, "roles": ["Khủng long con đi đầu (đọc dấu chân)", "Người canh gió (báo nguy hiểm)", "Người tìm nước", "Người giữ trứng và tổ", "Chim đưa tin của bầy (báo tin cho cả nhóm)"], "scoring": "Mỗi việc đúng = 1-3 sao theo độ chính xác và tốc độ. Thanh \"Dũng cảm cả bầy\" là thanh Boss chung: cả lớp cùng lấp đầy; nhóm nhiều sao nhất được cha khen và đi đầu đàn ở chặng sau.", "avatars": "Chế độ một mình: nhân vật là chú khủng long con Mốc. Chế độ lớp: mỗi học sinh một khủng long con, chọn loài (T-rex, Raptor, Triceratops, Stegosaurus, Diplodocus, Sauropod) và màu; trùng loài được, khác màu. 12 nhân vật dưới đây là cha, người lớn, bạn nhỏ và muông thú trong câu chuyện.", "species": {"trex": "dino_trex_brown", "raptor": "dino_raptor_rider", "triceratops": "dino_triceratops", "stegosaurus": "dino_stegosaurus", "diplodocus": "dino_diplodocus", "sauropod": "dino_sauropod_grey"}, "safety": "Không máu, không cảnh đau. Cảnh bắt nạt chỉ là xô đẩy, gầm gừ và chặn đường; ai \"ngã\" chỉ ngồi xuống, đứng dậy được. Săn mồi dùng hoạt ảnh vồ mồi rồi cắt cảnh; thú nhỏ luôn chạy thoát hoặc \"ngủ\" một lát, không bị làm hại.", "subtitle_rule": "Mức Beginner: toàn tiếng Việt. Mức A1 đến B2: từ có bậc thấp hơn mức đang chọn hiện tiếng Anh, từ còn lại tiếng Việt. Mức C1: toàn tiếng Anh."}'::jsonb, array['anim_cheer','dino_antelope','dino_diplodocus','dino_raptor_rider','dino_sauropod_grey','dino_stegosaurus','dino_trex_black','dino_trex_brown','dino_trex_yellow','dino_triceratops','dino_wolf_a','dino_wolf_b','dino_world_floating_jungle','ground_grass_iso','ground_grass_patch','ground_grass_tuft','ground_strip_6x20','hdri_dawn','hdri_noon','hdri_sunset','mini_azure_river','mini_floating_oasis','mini_floating_waterfall','mini_logic_island','river_rock_large','river_sign','river_stump','tree_pixel','tree_x01','tree_x03','tree_x05','tree_x06_duo']::text[], 2) on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration, story = excluded.story, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, total_minutes = excluded.total_minutes, character_count = excluded.character_count, active = excluded.active, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan, asset_ids = excluded.asset_ids, plan_version = excluded.plan_version;
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('dino-05#01', 'dino-05', 1, 'Mốc', 'Khủng long con tò mò, nhân vật chính (khi chơi một mình)', 'child', 'm', 'S4', false, 'E_brown', 'black', 'messy', 'short', false, false, 'casual', 'orange', '[dino_trex_brown] Khủng long con nhỏ, da nâu cam, bụng sáng, vết sọc trên đuôi', null, null, array['flower']::text[], 'Khủng long con, người kể chuyện', 'heroes');
insert into public.scenario_characters (id, scenario_id, slot, name, feature, age_group, gender, skin_code, skin_freckles, eye_code, hair_color, hair_style, hair_length, hair_dyed, hair_covered, outfit_theme, outfit_color, clothing_text, prop_category, weapon_label, accessories, role, team) values ('dino-05#02', 'dino-05', 2, 'Bố Gruk', 'Cha của Mốc đã già, đi chậm, lưng còng, hiền hậu', 'elder', 'm', 'S3', false, 'E_brown_dark', 'salt_pepper', 'messy', 'short', false, false, 'casual', 'brown', '[dino_trex_brown] T-rex trưởng thành da nâu sẫm, sẹo nhỏ trên mõm, bước chậm, lưng còng hơn', null, null, array['bandage']::text[], 'Cha, người dạy Mốc', 'npc');
